// Number handling: decimal literals (canonical representation like decNumber)
// and double formatting compatible with jq's dtoa-based output.

use std::cmp::Ordering;

#[derive(Clone, Debug)]
pub enum DecKind {
    Finite { digits: Vec<u8>, exp: i64 }, // digits: ascii digits, no leading zeros (at least "0")
    Inf,
}

#[derive(Clone, Debug)]
pub struct Literal {
    pub f: f64,
    pub neg: bool,
    pub kind: DecKind,
    pub repr: String,
}

impl Literal {
    pub fn is_inf(&self) -> bool {
        matches!(self.kind, DecKind::Inf)
    }
}

pub enum ParsedNum {
    Lit(Literal),
    NaN,
}

/// Parse a number per decNumber's from-string syntax.
pub fn parse_decimal(s: &str) -> Option<ParsedNum> {
    let b = s.as_bytes();
    let mut i = 0;
    let mut neg = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        neg = b[i] == b'-';
        i += 1;
    }
    let rest = &s[i..];
    if rest.is_empty() {
        return None;
    }
    let lower = rest.to_ascii_lowercase();
    if lower == "inf" || lower == "infinity" {
        let f = if neg { f64::NEG_INFINITY } else { f64::INFINITY };
        return Some(ParsedNum::Lit(Literal { f, neg, kind: DecKind::Inf, repr: String::new() }));
    }
    if lower.starts_with("nan") || lower.starts_with("snan") {
        let payload = if lower.starts_with("nan") { &lower[3..] } else { &lower[4..] };
        if !payload.bytes().all(|c| c.is_ascii_digit()) {
            return None;
        }
        // reject payload digits other than a single zero
        let p = payload.trim_start_matches('0');
        if !p.is_empty() {
            return None;
        }
        if payload.len() > 1 {
            // decNumber would keep digits; jq rejects digits > 1
            return None;
        }
        return Some(ParsedNum::NaN);
    }
    let mut digits: Vec<u8> = Vec::new();
    let mut frac_digits: i64 = 0;
    let mut seen_digit = false;
    let mut seen_dot = false;
    while i < b.len() {
        let c = b[i];
        if c.is_ascii_digit() {
            digits.push(c);
            seen_digit = true;
            if seen_dot {
                frac_digits += 1;
            }
            i += 1;
        } else if c == b'.' && !seen_dot {
            seen_dot = true;
            i += 1;
        } else {
            break;
        }
    }
    if !seen_digit {
        return None;
    }
    let mut exp: i64 = 0;
    if i < b.len() {
        if b[i] == b'e' || b[i] == b'E' {
            i += 1;
            let mut eneg = false;
            if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
                eneg = b[i] == b'-';
                i += 1;
            }
            if i >= b.len() {
                return None;
            }
            let mut e: i64 = 0;
            while i < b.len() {
                let c = b[i];
                if !c.is_ascii_digit() {
                    return None;
                }
                if e < 100_000_000_000 {
                    e = e * 10 + (c - b'0') as i64;
                }
                i += 1;
            }
            exp = if eneg { -e } else { e };
        } else {
            return None;
        }
    }
    let exp = exp - frac_digits;
    // strip leading zeros
    let first_nz = digits.iter().position(|&c| c != b'0');
    let digits = match first_nz {
        Some(p) => digits[p..].to_vec(),
        None => vec![b'0'],
    };
    let mut lit = Literal { f: 0.0, neg, kind: DecKind::Finite { digits, exp }, repr: String::new() };
    // overflow handling like decNumber (emax 999999999)
    if let DecKind::Finite { digits, exp } = &lit.kind {
        let adj = exp + digits.len() as i64 - 1;
        if digits != &vec![b'0'] && adj > 999_999_999 {
            lit.kind = DecKind::Inf;
        } else if digits == &vec![b'0'] {
            // clamp exponent for zeros
            let e = (*exp).clamp(-1_999_999_997, 999_999_999);
            lit.kind = DecKind::Finite { digits: vec![b'0'], exp: e };
        } else if adj < -1_999_999_997 {
            lit.kind = DecKind::Finite { digits: vec![b'0'], exp: -1_999_999_997 };
        }
    }
    finish_literal(&mut lit);
    Some(ParsedNum::Lit(lit))
}

pub fn finish_literal(lit: &mut Literal) {
    match &lit.kind {
        DecKind::Inf => {
            lit.f = if lit.neg { f64::NEG_INFINITY } else { f64::INFINITY };
            lit.repr = String::new();
        }
        DecKind::Finite { digits, exp } => {
            lit.repr = dec_to_string(lit.neg, digits, *exp);
            // compute double value
            let mut s = String::new();
            if lit.neg {
                s.push('-');
            }
            s.push_str(std::str::from_utf8(digits).unwrap());
            s.push('e');
            s.push_str(&exp.to_string());
            lit.f = s.parse::<f64>().unwrap_or(0.0);
        }
    }
}

/// decNumber to-scientific-string
pub fn dec_to_string(neg: bool, digits: &[u8], exp: i64) -> String {
    let mut out = String::new();
    if neg {
        out.push('-');
    }
    let n = digits.len() as i64;
    let adj = exp + n - 1;
    let ds = std::str::from_utf8(digits).unwrap();
    if exp <= 0 && adj >= -6 {
        if exp == 0 {
            out.push_str(ds);
        } else {
            let point = n + exp; // digits before point
            if point > 0 {
                out.push_str(&ds[..point as usize]);
                out.push('.');
                out.push_str(&ds[point as usize..]);
            } else {
                out.push_str("0.");
                for _ in 0..(-point) {
                    out.push('0');
                }
                out.push_str(ds);
            }
        }
    } else {
        out.push_str(&ds[..1]);
        if n > 1 {
            out.push('.');
            out.push_str(&ds[1..]);
        }
        out.push('E');
        if adj >= 0 {
            out.push('+');
        } else {
            out.push('-');
        }
        out.push_str(&adj.abs().to_string());
    }
    out
}

pub fn negate_literal(l: &Literal) -> Literal {
    let mut r = l.clone();
    match &l.kind {
        DecKind::Inf => {
            r.neg = !l.neg;
        }
        DecKind::Finite { digits, .. } => {
            if digits.len() == 1 && digits[0] == b'0' {
                r.neg = false;
            } else {
                r.neg = !l.neg;
            }
        }
    }
    finish_literal(&mut r);
    r
}

fn is_zero_digits(d: &[u8]) -> bool {
    d.len() == 1 && d[0] == b'0'
}

/// Compare two decimal literals numerically.
pub fn cmp_literal(a: &Literal, b: &Literal) -> Ordering {
    // sign handling
    let a_zero = matches!(&a.kind, DecKind::Finite { digits, .. } if is_zero_digits(digits));
    let b_zero = matches!(&b.kind, DecKind::Finite { digits, .. } if is_zero_digits(digits));
    let sa: i32 = if a_zero { 0 } else if a.neg { -1 } else { 1 };
    let sb: i32 = if b_zero { 0 } else if b.neg { -1 } else { 1 };
    if sa != sb {
        return sa.cmp(&sb);
    }
    if sa == 0 {
        return Ordering::Equal;
    }
    let mag = cmp_magnitude(a, b);
    if sa < 0 {
        mag.reverse()
    } else {
        mag
    }
}

fn cmp_magnitude(a: &Literal, b: &Literal) -> Ordering {
    match (&a.kind, &b.kind) {
        (DecKind::Inf, DecKind::Inf) => Ordering::Equal,
        (DecKind::Inf, _) => Ordering::Greater,
        (_, DecKind::Inf) => Ordering::Less,
        (DecKind::Finite { digits: da, exp: ea }, DecKind::Finite { digits: db, exp: eb }) => {
            let adja = ea + da.len() as i64 - 1;
            let adjb = eb + db.len() as i64 - 1;
            if adja != adjb {
                return adja.cmp(&adjb);
            }
            let n = da.len().max(db.len());
            for i in 0..n {
                let ca = if i < da.len() { da[i] } else { b'0' };
                let cb = if i < db.len() { db[i] } else { b'0' };
                if ca != cb {
                    return ca.cmp(&cb);
                }
            }
            Ordering::Equal
        }
    }
}

/// Format a double the way jq does (shortest round-trip, %.17g-like layout).
pub fn fmt_double(d: f64) -> String {
    if d.is_nan() {
        return "null".to_string();
    }
    let mut d = d;
    if d > f64::MAX {
        d = f64::MAX;
    }
    if d < -f64::MAX {
        d = -f64::MAX;
    }
    if d == 0.0 {
        return if d.is_sign_negative() { "-0".to_string() } else { "0".to_string() };
    }
    let s = format!("{:e}", d);
    // s like "-1.2345e-7" or "1e17"
    let (mant, exps) = s.split_at(s.find('e').unwrap());
    let exp10: i64 = exps[1..].parse().unwrap();
    let mut neg = false;
    let mut digits = String::new();
    for c in mant.chars() {
        if c == '-' {
            neg = true;
        } else if c.is_ascii_digit() {
            digits.push(c);
        }
    }
    // strip trailing zeros (shouldn't be any except "0")
    while digits.len() > 1 && digits.ends_with('0') {
        digits.pop();
    }
    let nd = digits.len() as i64;
    let decpt = exp10 + 1;
    let mut out = String::new();
    if neg {
        out.push('-');
    }
    if decpt <= -4 || decpt > nd + 15 {
        out.push_str(&digits[..1]);
        if nd > 1 {
            out.push('.');
            out.push_str(&digits[1..]);
        }
        out.push('e');
        let e = decpt - 1;
        if e < 0 {
            out.push('-');
        } else {
            out.push('+');
        }
        let ea = e.abs();
        if ea < 10 {
            out.push('0');
        }
        out.push_str(&ea.to_string());
    } else if decpt <= 0 {
        out.push_str("0.");
        for _ in 0..(-decpt) {
            out.push('0');
        }
        out.push_str(&digits);
    } else {
        if nd <= decpt {
            out.push_str(&digits);
            for _ in 0..(decpt - nd) {
                out.push('0');
            }
        } else {
            out.push_str(&digits[..decpt as usize]);
            out.push('.');
            out.push_str(&digits[decpt as usize..]);
        }
    }
    out
}
EOF
echo done"}

