    let mut neg = false;
    let mut digits = String::new();
    for c in mant.chars() {
        if c == '-' {
            neg = true;
        } else if c.is_ascii_digit() {
            digits.push(c);
        }
    }
    // strip trailing zeros (shouldn't be any except "0")
    while digits.len() > 1 && digits.ends_with('0') {
        digits.pop();
    }
    let nd = digits.len() as i64;
    let decpt = exp10 + 1;
    let mut out = String::new();
    if neg {
        out.push('-');
    }
    if decpt <= -4 || decpt > nd + 15 {
        out.push_str(&digits[..1]);
        if nd > 1 {
            out.push('.');
            out.push_str(&digits[1..]);
        }
        out.push('e');
        let e = decpt - 1;
        if e < 0 {
            out.push('-');
        } else {
            out.push('+');
        }
        let ea = e.abs();
        if ea < 10 {
            out.push('0');
        }
        out.push_str(&ea.to_string());
    } else if decpt <= 0 {
        out.push_str("0.");
        for _ in 0..(-decpt) {
            out.push('0');
        }
        out.push_str(&digits);
    } else {
        if nd <= decpt {
            out.push_str(&digits);
            for _ in 0..(decpt - nd) {
                out.push('0');
            }
        } else {
            out.push_str(&digits[..decpt as usize]);
            out.push('.');
            out.push_str(&digits[decpt as usize..]);
        }
    }
    out
}
