use crate::number::{self, ParsedNum};
use crate::value::{num_to_string, Map, Value};
use std::rc::Rc;

// ---------------- UTF-8 handling (jq-compatible) ----------------

fn utf8_len_of(first: u8) -> i32 {
    match first {
        0x00..=0x7F => 1,
        0x80..=0xBF => 255,
        0xC0..=0xC1 => 0,
        0xC2..=0xDF => 2,
        0xE0..=0xEF => 3,
        0xF0..=0xF4 => 4,
        _ => 0,
    }
}

/// Decode next codepoint like jvp_utf8_next; returns (codepoint or -1, length)
pub fn utf8_next(b: &[u8], i: usize) -> (i32, usize) {
    let first = b[i];
    let length = utf8_len_of(first);
    if first & 0x80 == 0 {
        return (first as i32, 1);
    }
    if length == 0 || length == 255 {
        return (-1, 1);
    }
    let length = length as usize;
    if i + length > b.len() {
        return (-1, b.len() - i);
    }
    let mask: u8 = match length {
        2 => 0x1F,
        3 => 0x0F,
        _ => 0x07,
    };
    let mut cp: i32 = (first & mask) as i32;
    for k in 1..length {
        let ch = b[i + k];
        if utf8_len_of(ch) != 255 {
            return (-1, k);
        }
        cp = (cp << 6) | (ch & 0x3f) as i32;
    }
    let first_cp = match length {
        2 => 0x80,
        3 => 0x800,
        _ => 0x10000,
    };
    if cp < first_cp {
        return (-1, length);
    }
    if (0xD800..=0xDFFF).contains(&cp) {
        return (-1, length);
    }
    if cp > 0x10FFFF {
        return (-1, length);
    }
    (cp, length)
}

/// Convert bytes to a valid UTF-8 string, replacing bad sequences like jq.
pub fn bytes_to_string(b: &[u8]) -> String {
    if let Ok(s) = std::str::from_utf8(b) {
        return s.to_string();
    }
    let mut out = String::with_capacity(b.len() + 8);
    let mut i = 0;
    while i < b.len() {
        let (cp, len) = utf8_next(b, i);
        if cp < 0 {
            out.push('\u{FFFD}');
        } else {
            out.push(char::from_u32(cp as u32).unwrap_or('\u{FFFD}'));
        }
        i += len;
    }
    out
}

// ---------------- Dumping ----------------

pub struct Colors {
    pub null: String,
    pub fals: String,
    pub tru: String,
    pub num: String,
    pub str: String,
    pub arr: String,
    pub obj: String,
    pub key: String,
}

impl Colors {
    pub fn default_colors() -> Colors {
        Colors {
            null: "0;90".into(),
            fals: "0;39".into(),
            tru: "0;39".into(),
            num: "0;39".into(),
            str: "0;32".into(),
            arr: "1;39".into(),
            obj: "1;39".into(),
            key: "1;34".into(),
        }
    }
}

pub struct DumpOpts<'a> {
    pub pretty: bool,
    pub indent: usize,
    pub tab: bool,
    pub sort_keys: bool,
    pub ascii: bool,
    pub colors: Option<&'a Colors>,
}

impl<'a> DumpOpts<'a> {
    pub fn compact() -> DumpOpts<'static> {
        DumpOpts { pretty: false, indent: 0, tab: false, sort_keys: false, ascii: false, colors: None }
    }
}

pub fn dump_string_escaped(s: &str, ascii: bool, out: &mut Vec<u8>) {
    out.push(b'"');
    for c in s.chars() {
        let cp = c as u32;
        if (0x20..=0x7E).contains(&cp) {
            if c == '"' || c == '\\' {
                out.push(b'\\');
            }
            out.push(cp as u8);
        } else if cp < 0x20 || cp == 0x7F {
            match c {
                '\u{8}' => out.extend_from_slice(b"\\b"),
                '\t' => out.extend_from_slice(b"\\t"),
                '\r' => out.extend_from_slice(b"\\r"),
                '\n' => out.extend_from_slice(b"\\n"),
                '\u{c}' => out.extend_from_slice(b"\\f"),
                _ => out.extend_from_slice(format!("\\u{:04x}", cp).as_bytes()),
            }
        } else if ascii {
            if cp <= 0xFFFF {
                out.extend_from_slice(format!("\\u{:04x}", cp).as_bytes());
            } else {
                let c2 = cp - 0x10000;
                out.extend_from_slice(
                    format!("\\u{:04x}\\u{:04x}", 0xD800 | ((c2 & 0xffc00) >> 10), 0xDC00 | (c2 & 0x3ff)).as_bytes(),
                );
            }
        } else {
            let mut buf = [0u8; 4];
            out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
        }
    }
    out.push(b'"');
}

fn put_indent(n: usize, opts: &DumpOpts, out: &mut Vec<u8>) {
    if opts.tab {
        for _ in 0..n {
            out.push(b'\t');
        }
    } else {
        for _ in 0..(n * opts.indent) {
            out.push(b' ');
        }
    }
}

fn col_start(c: &str, out: &mut Vec<u8>) {
    out.extend_from_slice(b"\x1b[");
    out.extend_from_slice(c.as_bytes());
    out.push(b'm');
}
const COLRESET: &[u8] = b"\x1b[0m";

pub fn dump_value(v: &Value, opts: &DumpOpts, level: usize, out: &mut Vec<u8>) {
    let colors = opts.colors;
    match v {
        Value::Null | Value::False | Value::True | Value::Num(_) | Value::Lit(_) | Value::Str(_) => {
            let (col, text): (Option<&str>, Vec<u8>) = match v {
                Value::Null => (colors.map(|c| c.null.as_str()), b"null".to_vec()),
                Value::False => (colors.map(|c| c.fals.as_str()), b"false".to_vec()),
                Value::True => (colors.map(|c| c.tru.as_str()), b"true".to_vec()),
                Value::Num(f) if f.is_nan() => (colors.map(|c| c.null.as_str()), b"null".to_vec()),
                Value::Num(_) | Value::Lit(_) => (colors.map(|c| c.num.as_str()), num_to_string(v).into_bytes()),
                Value::Str(s) => {
                    let mut b = Vec::new();
                    dump_string_escaped(s, opts.ascii, &mut b);
                    (colors.map(|c| c.str.as_str()), b)
                }
                _ => unreachable!(),
            };
            if let Some(c) = col {
                col_start(c, out);
                out.extend_from_slice(&text);
                out.extend_from_slice(COLRESET);
            } else {
                out.extend_from_slice(&text);
            }
        }
        Value::Arr(a) => {
            let col = colors.map(|c| c.arr.as_str());
            if a.is_empty() {
                if let Some(c) = col {
                    col_start(c, out);
                    out.extend_from_slice(b"[]");
                    out.extend_from_slice(COLRESET);
                } else {
                    out.extend_from_slice(b"[]");
                }
                return;
            }
            put_punct(col, b"[", out);
            for (i, e) in a.iter().enumerate() {
                if i > 0 {
                    put_punct(col, b",", out);
                }
                if opts.pretty {
                    out.push(b'\n');
                    put_indent(level + 1, opts, out);
                }
                dump_value(e, opts, level + 1, out);
            }
            if opts.pretty {
                out.push(b'\n');
                put_indent(level, opts, out);
            }
            put_punct(col, b"]", out);
        }
        Value::Obj(o) => {
            let col = colors.map(|c| c.obj.as_str());
            if o.is_empty() {
                if let Some(c) = col {
                    col_start(c, out);
                    out.extend_from_slice(b"{}");
                    out.extend_from_slice(COLRESET);
                } else {
                    out.extend_from_slice(b"{}");
                }
                return;
            }
            put_punct(col, b"{", out);
            let keys: Vec<Rc<str>> = if opts.sort_keys { o.sorted_keys() } else { o.keys().cloned().collect() };
            for (i, k) in keys.iter().enumerate() {
                if i > 0 {
                    put_punct(col, b",", out);
                }
                if opts.pretty {
                    out.push(b'\n');
                    put_indent(level + 1, opts, out);
                }
                if let Some(c) = colors {
                    col_start(&c.key, out);
                    dump_string_escaped(k, opts.ascii, out);
                    out.extend_from_slice(COLRESET);
                } else {
                    dump_string_escaped(k, opts.ascii, out);
                }
                put_punct(col, b":", out);
                if opts.pretty {
                    out.push(b' ');
                }
                dump_value(o.get(k).unwrap(), opts, level + 1, out);
            }
            if opts.pretty {
                out.push(b'\n');
                put_indent(level, opts, out);
            }
            put_punct(col, b"}", out);
        }
    }
}

fn put_punct(col: Option<&str>, p: &[u8], out: &mut Vec<u8>) {
    if let Some(c) = col {
        col_start(c, out);
        out.extend_from_slice(p);
        out.extend_from_slice(COLRESET);
    } else {
        out.extend_from_slice(p);
    }
}

pub fn to_json(v: &Value) -> String {
    let mut out = Vec::new();
    dump_value(v, &DumpOpts::compact(), 0, &mut out);
    // output is always valid utf8
    unsafe { String::from_utf8_unchecked(out) }
}

pub fn to_json_sorted(v: &Value) -> String {
    let mut out = Vec::new();
    let mut o = DumpOpts::compact();
    o.sort_keys = true;
    dump_value(v, &o, 0, &mut out);
    unsafe { String::from_utf8_unchecked(out) }
}

/// jv_dump_string_trunc
pub fn dump_trunc(v: &Value, bufsize: usize) -> String {
    let s = to_json(v);
    trunc_str(&s, bufsize)
}

pub fn trunc_str(s: &str, bufsize: usize) -> String {
    let b = s.as_bytes();
    if b.len() > bufsize - 1 {
        let mut out: Vec<u8> = b[..bufsize - 1].to_vec();
        if bufsize >= 4 {
            let n = out.len();
            out[n - 3] = b'.';
            out[n - 2] = b'.';
            out[n - 1] = b'.';
        }
        bytes_to_string(&out)
    } else {
        s.to_string()
    }
}

// ---------------- Parsing ----------------

#[derive(PartialEq, Clone, Copy)]
enum St {
    Normal,
    Str,
    StrEscape,
    WaitRs,
}

#[derive(PartialEq, Clone, Copy)]
enum LastSeen {
    None,
    OpenArray,
    OpenObject,
    Colon,
    Comma,
    Value,
}

pub struct Parser {
    pub streaming: bool,
    pub seq: bool,
    stack: Vec<Value>,  // normal mode stack
    path: Vec<Value>,   // streaming path
    last_seen: LastSeen,
    output: Option<Vec<Value>>,
    next: Option<Value>,
    token: Vec<u8>,
    pub line: i64,
    pub column: i64,
    st: St,
    last_ch_was_ws: bool,
    buf: Vec<u8>,
    pos: usize,
    partial: bool,
    eof: bool,
    bom_state: u8, // 0 = start, 1..3 bytes of BOM matched, 4 = done
    has_buf: bool,
}

pub enum ParseResult {
    Value(Value),
    Error(String),
    NeedMore,
    Eof,
}

const MAX_DEPTH: usize = 10000;

impl Parser {
    pub fn new(streaming: bool, seq: bool) -> Parser {
        Parser {
            streaming,
            seq,
            stack: Vec::new(),
            path: Vec::new(),
            last_seen: LastSeen::None,
            output: None,
            next: None,
            token: Vec::new(),
            line: 1,
            column: 0,
            st: if seq { St::WaitRs } else { St::Normal },
            last_ch_was_ws: false,
            buf: Vec::new(),
            pos: 0,
            partial: true,
            eof: false,
            bom_state: 0,
            has_buf: false,
        }
    }

    pub fn set_buf(&mut self, data: &[u8], partial: bool) {
        let mut data = data;
        if self.bom_state < 4 {
            // strip UTF-8 BOM at very start
            const BOM: [u8; 3] = [0xEF, 0xBB, 0xBF];
            let mut k = 0;
            while self.bom_state < 3 && k < data.len() && data[k] == BOM[self.bom_state as usize] {
                self.bom_state += 1;
                k += 1;
            }
            if self.bom_state == 3 {
                self.bom_state = 4;
                data = &data[k..];
            } else if k == data.len() && self.bom_state > 0 && partial {
                // wait for more
                data = &data[k..];
            } else if self.bom_state > 0 {
                self.bom_state = 0xff;
            } else if !data.is_empty() {
                self.bom_state = 4;
            }
        }
        self.buf = data.to_vec();
        self.pos = 0;
        self.partial = partial;
        self.has_buf = true;
    }

    fn reset(&mut self) {
        self.stack.clear();
        self.path.clear();
        self.last_seen = LastSeen::None;
        self.output = None;
        self.next = None;
        self.token.clear();
        self.st = St::Normal;
    }

    fn err_at(&self, msg: &str) -> String {
        format!("{} at line {}, column {}", msg, self.line, self.column)
    }

    pub fn current_path(&self) -> Value {
        Value::from_vec(self.path.clone())
    }

    pub fn next_value(&mut self) -> ParseResult {
        if self.eof {
            return ParseResult::Eof;
        }
        if !self.has_buf {
            return ParseResult::NeedMore;
        }
        if self.bom_state == 0xff {
            if !self.seq {
                self.has_buf = false;
                self.eof = true;
                return ParseResult::Error("Malformed BOM".to_string());
            }
            self.st = St::WaitRs;
            self.bom_state = 4;
        }
        if self.streaming {
            if let Some(v) = self.stream_check_done() {
                return ParseResult::Value(v);
            }
        }
        let mut msg: Option<Result<Value, String>> = None;
        let mut ch = 0u8;
        while msg.is_none() && self.pos < self.buf.len() {
            ch = self.buf[self.pos];
            self.pos += 1;
            if self.st == St::WaitRs {
                if ch == b'\n' {
                    self.line += 1;
                    self.column = 0;
                } else {
                    self.column += 1;
                }
                if ch == 0x1e {
                    self.st = St::Normal;
                }
                continue;
            }
            msg = self.scan(ch);
        }
        match msg {
            Some(Ok(v)) => return ParseResult::Value(v),
            Some(Err(m)) => {
                if ch != 0x1e && self.seq {
                    let e = format!("{} at line {}, column {} (need RS to resync)", m, self.line, self.column);
                    self.reset();
                    self.st = St::WaitRs;
                    return ParseResult::Error(e);
                }
                let e = self.err_at(&m);
                self.reset();
                if !self.seq {
                    self.buf.clear();
                    self.pos = 0;
                }
                return ParseResult::Error(e);
            }
            None => {}
        }
        if self.partial {
            self.has_buf = false;
            return ParseResult::NeedMore;
        }
        // EOF
        self.eof = true;
        if self.st == St::WaitRs {
            return ParseResult::Error(format!(
                "Unfinished abandoned text at EOF at line {}, column {}",
                self.line, self.column
            ));
        }
        if self.st != St::Normal {
            let e = format!("Unfinished string at EOF at line {}, column {}", self.line, self.column);
            self.reset();
            self.st = St::WaitRs;
            return ParseResult::Error(e);
        }
        if let Err(m) = self.check_literal() {
            let e = format!("{} at EOF at line {}, column {}", m, self.line, self.column);
            self.reset();
            self.st = St::WaitRs;
            return ParseResult::Error(e);
        }
        if (self.streaming && !self.path.is_empty()) || (!self.streaming && !self.stack.is_empty()) {
            let e = format!("Unfinished JSON term at EOF at line {}, column {}", self.line, self.column);
            self.reset();
            self.st = St::WaitRs;
            return ParseResult::Error(e);
        }
        let value = if self.streaming {
            match self.next.take() {
                Some(v) => Some(Value::from_vec(vec![Value::from_vec(self.path.clone()), v])),
                None => None,
            }
        } else {
            self.next.take()
        };
        match value {
            Some(v) => {
                if self.seq && !self.last_ch_was_ws && v.is_number() {
                    return ParseResult::Error(format!(
                        "Potentially truncated top-level numeric value at EOF at line {}, column {}",
                        self.line, self.column
                    ));
                }
                ParseResult::Value(v)
            }
            None => ParseResult::Eof,
        }
    }

    fn check_done(&mut self) -> Option<Value> {
        if self.streaming {
            self.stream_check_done()
        } else if self.stack.is_empty() && self.next.is_some() {
            self.next.take()
        } else {
            None
        }
    }

    fn stream_check_done(&mut self) -> Option<Value> {
        if self.path.is_empty() && self.next.is_some() {
            let v = self.next.take().unwrap();
            return Some(Value::from_vec(vec![Value::from_vec(self.path.clone()), v]));
        }
        if let Some(o) = self.output.take() {
            if o.len() > 2 {
                let first = Value::from_vec(o[..2].to_vec());
                self.output = Some(o[..1].to_vec());
                return Some(first);
            }
            return Some(Value::from_vec(o));
        }
        None
    }

    fn check_truncation(&self) -> bool {
        if self.streaming {
            !self.path.is_empty()
                || matches!(self.next, Some(Value::Num(_)) | Some(Value::Lit(_)) | Some(Value::True) | Some(Value::False) | Some(Value::Null))
        } else {
            self.seq
                && !self.last_ch_was_ws
                && (!self.stack.is_empty() || !self.token.is_empty() || matches!(self.next, Some(Value::Num(_)) | Some(Value::Lit(_))))
        }
    }

    fn is_top_num(&self) -> bool {
        if self.streaming {
            self.path.is_empty() && matches!(self.next, Some(Value::Num(_)) | Some(Value::Lit(_)))
        } else {
            self.stack.is_empty() && matches!(self.next, Some(Value::Num(_)) | Some(Value::Lit(_)))
        }
    }

    fn scan(&mut self, ch: u8) -> Option<Result<Value, String>> {
        self.column += 1;
        if ch == b'\n' {
            self.line += 1;
            self.column = 0;
        }
        if ch == 0x1e {
            if self.check_truncation() {
                if self.check_literal().is_ok() && self.is_top_num() {
                    return Some(Err("Potentially truncated top-level numeric value".into()));
                }
                return Some(Err("Truncated value".into()));
            }
            if let Err(e) = self.check_literal() {
                return Some(Err(e));
            }
            if self.st == St::Normal {
                if let Some(v) = self.check_done() {
                    return Some(Ok(v));
                }
            }
            self.reset();
            return None;
        }
        let mut answer: Option<Value> = None;
        self.last_ch_was_ws = false;
        if self.st == St::Normal {
            let is_ws = matches!(ch, b' ' | b'\t' | b'\r' | b'\n');
            let is_struct = matches!(ch, b'[' | b',' | b']' | b'{' | b':' | b'}');
            let is_quote = ch == b'"';
            if is_ws {
                self.last_ch_was_ws = true;
            }
            if is_ws || is_struct || is_quote {
                if let Err(e) = self.check_literal() {
                    return Some(Err(e));
                }
                if let Some(v) = self.check_done() {
                    answer = Some(v);
                }
            }
            if is_quote {
                self.st = St::Str;
            } else if is_struct {
                let r = if self.streaming { self.stream_token(ch) } else { self.token_ch(ch) };
                if let Err(e) = r {
                    return Some(Err(e));
                }
            } else if !is_ws {
                self.token.push(ch);
            }
            if answer.is_none() {
                if let Some(v) = self.check_done() {
                    answer = Some(v);
                }
            }
        } else {
            if ch == b'"' && self.st == St::Str {
                if let Err(e) = self.found_string() {
                    return Some(Err(e));
                }
                self.st = St::Normal;
                if let Some(v) = self.check_done() {
                    answer = Some(v);
                }
            } else {
                self.token.push(ch);
                if ch == b'\\' && self.st == St::Str {
                    self.st = St::StrEscape;
                } else {
                    self.st = St::Str;
                }
            }
        }
        answer.map(Ok)
    }

    fn value(&mut self, v: Value) -> Result<(), String> {
        if self.streaming {
            if self.next.is_some() || self.last_seen == LastSeen::Value {
                return Err("Expected separator between values".into());
            }
            if !self.path.is_empty() {
                self.last_seen = LastSeen::Value;
            } else {
                self.last_seen = LastSeen::None;
            }
        } else if self.next.is_some() {
            return Err("Expected separator between values".into());
        }
        self.next = Some(v);
        Ok(())
    }

    fn check_literal(&mut self) -> Result<(), String> {
        if self.token.is_empty() {
            return Ok(());
        }
        let tok = std::mem::take(&mut self.token);
        let (pattern, v): (Option<&[u8]>, Value) = match tok[0] {
            b't' => (Some(b"true"), Value::True),
            b'f' => (Some(b"false"), Value::False),
            b'\'' => {
                self.token = tok;
                return Err("Invalid string literal; expected \", but got '".into());
            }
            b'n' => {
                if tok.len() == 3 {
                    (Some(b"nan"), Value::Num(f64::NAN))
                } else {
                    (Some(b"null"), Value::Null)
                }
            }
            _ => (None, Value::Null),
        };
        if let Some(p) = pattern {
            if tok.as_slice() != p {
                self.token = tok;
                return Err("Invalid literal".into());
            }
            self.value(v)?;
        } else {
            let s = match std::str::from_utf8(&tok) {
                Ok(s) => s,
                Err(_) => {
                    self.token = tok;
                    return Err("Invalid numeric literal".into());
                }
            };
            match number::parse_decimal(s) {
                Some(ParsedNum::Lit(l)) => self.value(Value::Lit(Rc::new(l)))?,
                Some(ParsedNum::NaN) => self.value(Value::Num(f64::NAN))?,
                None => {
                    self.token = tok;
                    return Err("Invalid numeric literal".into());
                }
            }
        }
        Ok(())
    }

    fn found_string(&mut self) -> Result<(), String> {
        let tok = std::mem::take(&mut self.token);
        let mut out: Vec<u8> = Vec::with_capacity(tok.len());
        let mut i = 0;
        let end = tok.len();
        while i < end {
            let c = tok[i];
            i += 1;
            if c == b'\\' {
                if i >= end {
                    return Err("Expected escape character at end of string".into());
                }
                let c = tok[i];
                i += 1;
                match c {
                    b'\\' | b'"' | b'/' => out.push(c),
                    b'b' => out.push(8),
                    b'f' => out.push(12),
                    b't' => out.push(9),
                    b'n' => out.push(10),
                    b'r' => out.push(13),
                    b'u' => {
                        if i + 4 > end {
                            return Err("Invalid \\uXXXX escape".into());
                        }
                        let h = match unhex4(&tok[i..i + 4]) {
                            Some(h) => h,
                            None => return Err("Invalid characters in \\uXXXX escape".into()),
                        };
                        i += 4;
                        let mut cp = h;
                        if (0xD800..=0xDBFF).contains(&cp) {
                            if i + 6 > end || tok[i] != b'\\' || tok[i + 1] != b'u' {
                                return Err("Invalid \\uXXXX\\uXXXX surrogate pair escape".into());
                            }
                            let s = match unhex4(&tok[i + 2..i + 6]) {
                                Some(s) => s,
                                None => return Err("Invalid \\uXXXX\\uXXXX surrogate pair escape".into()),
                            };
                            if !(0xDC00..=0xDFFF).contains(&s) {
                                return Err("Invalid \\uXXXX\\uXXXX surrogate pair escape".into());
                            }
                            i += 6;
                            cp = 0x10000 + (((cp - 0xD800) << 10) | (s - 0xDC00));
                        }
                        if cp > 0x10FFFF {
                            cp = 0xFFFD;
                        }
                        encode_utf8_raw(cp, &mut out);
                    }
                    _ => return Err("Invalid escape".into()),
                }
            } else {
                if c > 0 && c <= 0x1f {
                    return Err("Invalid string: control characters from U+0000 through U+001F must be escaped".into());
                }
                out.push(c);
            }
        }
        let s = bytes_to_string(&out);
        self.value(Value::from_string(s))
    }

    fn token_ch(&mut self, ch: u8) -> Result<(), String> {
        match ch {
            b'[' => {
                if self.stack.len() >= MAX_DEPTH {
                    return Err("Exceeds depth limit for parsing".into());
                }
                if self.next.is_some() {
                    return Err("Expected separator between values".into());
                }
                self.stack.push(Value::from_vec(Vec::new()));
            }
            b'{' => {
                if self.stack.len() >= MAX_DEPTH {
                    return Err("Exceeds depth limit for parsing".into());
                }
                if self.next.is_some() {
                    return Err("Expected separator between values".into());
                }
                self.stack.push(Value::from_map(Map::new()));
            }
            b':' => {
                if self.next.is_none() {
                    return Err("Expected string key before ':'".into());
                }
                if self.stack.is_empty() || !matches!(self.stack.last(), Some(Value::Obj(_))) {
                    return Err("':' not as part of an object".into());
                }
                if !matches!(self.next, Some(Value::Str(_))) {
                    return Err("Object keys must be strings".into());
                }
                let k = self.next.take().unwrap();
                self.stack.push(k);
            }
            b',' => {
                if self.next.is_none() {
                    return Err("Expected value before ','".into());
                }
                if self.stack.is_empty() {
                    return Err("',' not as part of an object or array".into());
                }
                let n = self.stack.len();
                match &mut self.stack[n - 1] {
                    Value::Arr(a) => {
                        let v = self.next.take().unwrap();
                        Rc::make_mut(a).push(v);
                    }
                    Value::Str(_) => {
                        let k = self.stack.pop().unwrap();
                        let v = self.next.take().unwrap();
                        if let (Value::Obj(o), Value::Str(k)) = (&mut self.stack[n - 2], k) {
                            Rc::make_mut(o).insert(k, v);
                        }
                    }
                    _ => return Err("Objects must consist of key:value pairs".into()),
                }
            }
            b']' => {
                if self.stack.is_empty() || !matches!(self.stack.last(), Some(Value::Arr(_))) {
                    return Err("Unmatched ']'".into());
                }
                let n = self.stack.len();
                if let Some(v) = self.next.take() {
                    if let Value::Arr(a) = &mut self.stack[n - 1] {
                        Rc::make_mut(a).push(v);
                    }
                } else if let Value::Arr(a) = &self.stack[n - 1] {
                    if !a.is_empty() {
                        return Err("Expected another array element".into());
                    }
                }
                self.next = self.stack.pop();
            }
            b'}' => {
                if self.stack.is_empty() {
                    return Err("Unmatched '}'".into());
                }
                let n = self.stack.len();
                if self.next.is_some() {
                    if !matches!(self.stack[n - 1], Value::Str(_)) {
                        return Err("Objects must consist of key:value pairs".into());
                    }
                    let k = self.stack.pop().unwrap();
                    let v = self.next.take().unwrap();
                    if let (Value::Obj(o), Value::Str(k)) = (&mut self.stack[n - 2], k) {
                        Rc::make_mut(o).insert(k, v);
                    }
                } else {
                    match &self.stack[n - 1] {
                        Value::Obj(o) => {
                            if !o.is_empty() {
                                return Err("Expected another key-value pair".into());
                            }
                        }
                        _ => return Err("Unmatched '}'".into()),
                    }
                }
                self.next = self.stack.pop();
            }
            _ => {}
        }
        Ok(())
    }

    fn stream_token(&mut self, ch: u8) -> Result<(), String> {
        let n = self.path.len();
        match ch {
            b'[' => {
                if self.next.is_some() {
                    return Err("Expected a separator between values".into());
                }
                if self.last_seen == LastSeen::OpenObject {
                    return Err("Expected string key after '{', found '['".into());
                }
                if self.last_seen == LastSeen::Comma {
                    if !self.path[n - 1].is_number() {
                        return Err("Expected string key after ',' in object, found '['".into());
                    }
                }
                self.path.push(Value::Num(0.0));
                self.last_seen = LastSeen::OpenArray;
            }
            b'{' => {
                if self.last_seen == LastSeen::Value {
                    return Err("Expected a separator between values".into());
                }
                if self.last_seen == LastSeen::OpenObject {
                    return Err("Expected string key after '{', found '{'".into());
                }
                if self.last_seen == LastSeen::Comma {
                    if !self.path[n - 1].is_number() {
                        return Err("Expected string key after ',' in object, found '{'".into());
                    }
                }
                self.path.push(Value::Null);
                self.last_seen = LastSeen::OpenObject;
            }
            b':' => {
                if n == 0 || self.path[n - 1].is_number() {
                    return Err("':' not as part of an object".into());
                }
                if self.next.is_none() || self.last_seen == LastSeen::None {
                    self.next = None;
                    return Err("Expected string key before ':'".into());
                }
                if !matches!(self.next, Some(Value::Str(_))) {
                    self.next = None;
                    return Err("Object keys must be strings".into());
                }
                if self.last_seen != LastSeen::Value {
                    return Err("':' should follow a key".into());
                }
                self.last_seen = LastSeen::Colon;
                self.path[n - 1] = self.next.take().unwrap();
            }
            b',' => {
                if self.last_seen != LastSeen::Value {
                    return Err("Expected value before ','".into());
                }
                if n == 0 {
                    return Err("',' not as part of an object or array".into());
                }
                let last = self.path[n - 1].clone();
                if last.is_number() {
                    let idx = last.as_f64();
                    if let Some(v) = self.next.take() {
                        self.output = Some(vec![Value::from_vec(self.path.clone()), v]);
                    }
                    self.path[n - 1] = Value::Num(idx + 1.0);
                    self.last_seen = LastSeen::Comma;
                } else if matches!(last, Value::Str(_)) {
                    if let Some(v) = self.next.take() {
                        self.output = Some(vec![Value::from_vec(self.path.clone()), v]);
                    }
                    self.path[n - 1] = Value::True;
                    self.last_seen = LastSeen::Comma;
                } else {
                    return Err("Objects must consist of key:value pairs".into());
                }
            }
            b']' => {
                if n == 0 {
                    return Err("Unmatched ']' at the top-level".into());
                }
                if self.last_seen == LastSeen::Comma {
                    return Err("Expected another array element".into());
                }
                let last = &self.path[n - 1];
                if !last.is_number() {
                    return Err("Unmatched ']' in the middle of an object".into());
                }
                if let Some(v) = self.next.take() {
                    self.output = Some(vec![Value::from_vec(self.path.clone()), v, Value::True]);
                } else if self.last_seen != LastSeen::OpenArray {
                    self.output = Some(vec![Value::from_vec(self.path.clone())]);
                }
                self.path.pop();
                self.next = None;
                if self.last_seen == LastSeen::OpenArray {
                    self.output = Some(vec![Value::from_vec(self.path.clone()), Value::from_vec(vec![])]);
                }
                self.last_seen = if self.path.is_empty() { LastSeen::None } else { LastSeen::Value };
            }
            b'}' => {
                if n == 0 {
                    return Err("Unmatched '}' at the top-level".into());
                }
                if self.last_seen == LastSeen::Comma {
                    return Err("Expected another key:value pair".into());
                }
                let last = self.path[n - 1].clone();
                if last.is_number() {
                    return Err("Unmatched '}' in the middle of an array".into());
                }
                if let Some(v) = self.next.take() {
                    if !matches!(last, Value::Str(_)) {
                        return Err("Objects must consist of key:value pairs".into());
                    }
                    self.output = Some(vec![Value::from_vec(self.path.clone()), v, Value::True]);
                } else {
                    if self.last_seen == LastSeen::Colon {
                        return Err("Missing value in key:value pair".into());
                    }
                    if self.last_seen == LastSeen::OpenArray {
                        return Err("Unmatched '}' in the middle of an array".into());
                    }
                    if self.last_seen != LastSeen::Value && self.last_seen != LastSeen::OpenObject {
                        return Err("Unmatched '}'".into());
                    }
                    if self.last_seen != LastSeen::OpenObject {
                        self.output = Some(vec![Value::from_vec(self.path.clone())]);
                    }
                }
                self.path.pop();
                self.next = None;
                if self.last_seen == LastSeen::OpenObject {
                    self.output = Some(vec![Value::from_vec(self.path.clone()), Value::from_map(Map::new())]);
                }
                self.last_seen = if self.path.is_empty() { LastSeen::None } else { LastSeen::Value };
            }
            _ => {}
        }
        Ok(())
    }
}

fn unhex4(b: &[u8]) -> Option<u32> {
    let mut r = 0u32;
    for &c in b {
        let d = match c {
            b'0'..=b'9' => c - b'0',
            b'a'..=b'f' => c - b'a' + 10,
            b'A'..=b'F' => c - b'A' + 10,
            _ => return None,
        };
        r = (r << 4) | d as u32;
    }
    Some(r)
}

fn encode_utf8_raw(cp: u32, out: &mut Vec<u8>) {
    if cp < 0x80 {
        out.push(cp as u8);
    } else if cp < 0x800 {
        out.push(0xC0 | (cp >> 6) as u8);
        out.push(0x80 | (cp & 0x3F) as u8);
    } else if cp < 0x10000 {
        out.push(0xE0 | (cp >> 12) as u8);
        out.push(0x80 | ((cp >> 6) & 0x3F) as u8);
        out.push(0x80 | (cp & 0x3F) as u8);
    } else {
        out.push(0xF0 | (cp >> 18) as u8);
        out.push(0x80 | ((cp >> 12) & 0x3F) as u8);
        out.push(0x80 | ((cp >> 6) & 0x3F) as u8);
        out.push(0x80 | (cp & 0x3F) as u8);
    }
}

/// Parse a complete text as a single JSON value (jv_parse_sized semantics)
pub fn parse_single(text: &[u8]) -> Result<Value, String> {
    let mut p = Parser::new(false, false);
    p.set_buf(text, false);
    let disp = bytes_to_string(text.split(|&c| c == 0).next().unwrap_or(&[]));
    let r = match p.next_value() {
        ParseResult::Value(v) => match p.next_value() {
            ParseResult::Value(_) => Err("Unexpected extra JSON values".to_string()),
            ParseResult::Error(e) => Err(e),
            _ => Ok(v),
        },
        ParseResult::Error(e) => Err(e),
        _ => Err("Expected JSON value".to_string()),
    };
    r.map_err(|e| format!("{} (while parsing '{}')", e, disp))
}

/// Parse all values from a text (jv_load_file / slurp style)
pub fn parse_all(text: &[u8]) -> Result<Vec<Value>, String> {
    let mut p = Parser::new(false, false);
    p.set_buf(text, false);
    let mut out = Vec::new();
    loop {
        match p.next_value() {
            ParseResult::Value(v) => out.push(v),
            ParseResult::Error(e) => return Err(e),
            _ => break,
        }
    }
    Ok(out)
}
