pub struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    // stack of contexts: 'p' paren, '[' bracket, '{' brace, 's' string, 'i' interpolation
    stack: Vec<char>,
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a str) -> Lexer<'a> {
        Lexer { src: src.as_bytes(), pos: 0, stack: Vec::new() }
    }

    fn in_string(&self) -> bool {
        matches!(self.stack.last(), Some('s'))
    }

