enum Ctx {
    Paren,      // recoverable
    Bracket,    // recoverable
    Brace,      // recoverable (object)
    IfThen,     // after 'then' of an if
    TryCatch,   // after 'catch'
    ObjPair(usize), // inside object pair starting at token index
}

pub struct Parser {
    toks: Vec<Token>,
    pos: usize,
    pub errors: Vec<PError>,
    ctx: Vec<(Ctx, usize)>, // context and start token index
    failed: bool,
}

type PResult<T> = Result<T, ()>;

fn tok_name(t: &Tok) -> String {
    match t {
        Tok::Eof => "end of file".into(),
        Tok::Ident(_) => "IDENT".into(),
        Tok::Field(_) => "FIELD".into(),
        Tok::Binding(_) => "BINDING".into(),
        Tok::Format(_) => "FORMAT".into(),
        Tok::Literal(_) => "LITERAL".into(),
        Tok::QQStart => "QQSTRING_START".into(),
        Tok::QQText(_) => "QQSTRING_TEXT".into(),
        Tok::QQInterpStart => "QQSTRING_INTERP_START".into(),
        Tok::QQInterpEnd => "QQSTRING_INTERP_END".into(),
        Tok::QQEnd => "QQSTRING_END".into(),
        Tok::Invalid(_) => "INVALID_CHARACTER".into(),
        Tok::Loc => "$__loc__".into(),
        Tok::Keyword(k) => k.to_string(),
        Tok::Op(o) => o.to_string(),
        Tok::Punct(c) => format!("'{}'", c),
    }
}

pub fn parse_number_literal(s: &str) -> Value {
    match number::parse_decimal(s) {
        Some(ParsedNum::Lit(l)) => Value::Lit(Rc::new(l)),
        Some(ParsedNum::NaN) => Value::Num(f64::NAN),
        None => Value::Num(s.parse::<f64>().unwrap_or(0.0)),
    }
}

impl Parser {
    pub fn new(src: &str) -> Parser {
        let toks = Lexer::new(src).tokenize();
        Parser { toks, pos: 0, errors: Vec::new(), ctx: Vec::new(), failed: false }
    }

    fn peek(&self) -> &Tok {
        &self.toks[self.pos].tok
    }
    fn peek_at(&self, k: usize) -> &Tok {
        let i = (self.pos + k).min(self.toks.len() - 1);
        &self.toks[i].tok
    }
    fn advance(&mut self) -> Token {
        let t = self.toks[self.pos].clone();
        if self.pos < self.toks.len() - 1 {
            self.pos += 1;
        }
        t
    }
    fn is_punct(&self, c: char) -> bool {
        matches!(self.peek(), Tok::Punct(x) if *x == c)
    }
    fn is_kw(&self, k: &str) -> bool {
        matches!(self.peek(), Tok::Keyword(x) if *x == k)
    }
    fn is_op(&self, o: &str) -> bool {
        matches!(self.peek(), Tok::Op(x) if *x == o)
    }

    // location of current token (EOF -> last real token)
    fn err_span(&self, idx: usize) -> (usize, usize) {
        let t = &self.toks[idx];
        if t.tok == Tok::Eof {
            if idx > 0 {
                let p = &self.toks[idx - 1];
                return (p.start, p.end);
            }
            return (0, 0);
        }
        (t.start, t.end)
    }

    fn syntax_error(&mut self, expecting: &[String]) -> () {
        if self.failed {
            return;
        }
        self.failed = true;
        let idx = self.pos;
        let t = self.toks[idx].tok.clone();
        let mut msg = format!("syntax error, unexpected {}", tok_name(&t));
        if !expecting.is_empty() && expecting.len() <= 4 {
            msg.push_str(", expecting ");
            msg.push_str(&expecting.join(" or "));
        }
        let (s, e) = self.err_span(idx);
        self.errors.push(PError { msg, start: s, end: e });
        // secondary messages from error recovery
        for (c, start_idx) in self.ctx.clone().iter().rev() {
            match c {
                Ctx::Paren | Ctx::Bracket => break,
                Ctx::Brace => break,
                Ctx::ObjPair(_) => {
                    // look for ':' at depth 0 before ',' or '}'
                    let pair_start = self.toks[*start_idx].start;
                    let mut depth: i32 = 0;
                    let mut j = idx;
                    let mut found: Option<usize> = None;
                    // if error token is ':' itself
                    if matches!(self.toks[idx].tok, Tok::Punct(':')) {
                        found = Some(self.toks[idx].end);
                    } else {
                        j += 1;
                        let mut prev_end = self.toks[idx].end;
                        while j < self.toks.len() {
                            match &self.toks[j].tok {
                                Tok::Eof => break,
                                Tok::Punct('(') | Tok::Punct('[') | Tok::Punct('{') | Tok::QQInterpStart => depth += 1,
                                Tok::Punct(')') | Tok::Punct(']') | Tok::QQInterpEnd => depth -= 1,
                                Tok::Punct('}') => {
                                    if depth == 0 {
                                        break;
                                    }
                                    depth -= 1;
                                }
                                Tok::Punct(',') if depth == 0 => break,
                                Tok::Punct(':') if depth == 0 => {
                                    found = Some(prev_end);
                                    break;
                                }
                                _ => {}
                            }
                            prev_end = self.toks[j].end;
                            j += 1;
                        }
                    }
                    if let Some(end) = found {
                        self.errors.push(PError {
                            msg: "May need parentheses around object key expression".into(),
                            start: pair_start,
                            end,
                        });
                    }
                    break;
                }
                Ctx::IfThen => {
                    let st = self.toks[*start_idx].start;
                    self.errors.push(PError { msg: "Possibly unterminated 'if' statement".into(), start: st, end: e });
                    break;
                }
                Ctx::TryCatch => {
                    let st = self.toks[*start_idx].start;
                    self.errors.push(PError { msg: "Possibly unterminated 'try' statement".into(), start: st, end: e });
                    break;
                }
            }
        }
    }

    fn fail<T>(&mut self, expecting: &[&str]) -> PResult<T> {
        let v: Vec<String> = expecting.iter().map(|s| s.to_string()).collect();
        self.syntax_error(&v);
        Err(())
    }

    fn exp_fail<T>(&mut self, named: &[&str], chars: &[&str]) -> PResult<T> {
        let mut v: Vec<String> = named.iter().map(|s| s.to_string()).collect();
        v.push("'|'".into());
        v.push("','".into());
        for c in chars {
            v.push(c.to_string());
        }
        self.syntax_error(&v);
        Err(())
    }

    fn semantic_error(&mut self, msg: String, start: usize, end: usize) {
        self.errors.push(PError { msg, start, end });
    }

    // ---------------- top level ----------------

    pub fn parse_program(&mut self, is_module: bool) -> Option<Program> {
        let r = self.parse_program_inner(is_module);
        match r {
            Ok(p) if self.errors.is_empty() => Some(p),
            _ => None,
        }
    }

    fn parse_program_inner(&mut self, is_module: bool) -> PResult<Program> {
        let mut prog = Program { module_meta: None, imports: Vec::new(), defs: Vec::new(), body: None };
        if self.is_kw("module") {
            let st = self.toks[self.pos].start;
            self.advance();
            let e = self.parse_pipe(false)?;
            if !self.is_punct(';') {
                return self.exp_fail(&[], &["';'"]);
            }
            let en = self.toks[self.pos].end;
            self.advance();
            match const_value(&e) {
                Some(v @ Value::Obj(_)) => prog.module_meta = Some(v),
                _ => {
                    self.semantic_error("Module metadata must be constant".into(), st, en);
                    return Err(());
                }
            }
        }
        while self.is_kw("import") || self.is_kw("include") {
            let imp = self.parse_import()?;
            prog.imports.push(imp);
        }
        // FuncDefs or Exp
        let start_pos = self.pos;
        // try: sequence of defs followed by EOF
        let mut defs = Vec::new();
        while self.is_kw("def") {
            let d = self.parse_funcdef()?;
            defs.push(d);
        }
        if *self.peek() == Tok::Eof {
            prog.defs = defs;
            if !is_module {
                // main program: "Top-level program not given"
            }
            return Ok(prog);
        }
        // otherwise it's an expression: re-parse from start_pos
        self.pos = start_pos;
        let e = self.parse_pipe(false)?;
        if *self.peek() != Tok::Eof {
            return self.fail(&["end of file"]);
        }
        prog.body = Some(e);
        Ok(prog)
    }

    fn parse_string_const(&mut self) -> PResult<(String, usize, usize)> {
        // Import path: String (FORMAT optional) - must be constant
        let st = self.toks[self.pos].start;
        let e = match self.peek().clone() {
            Tok::QQStart => self.parse_string(None)?,
            Tok::Format(f) => {
                self.advance();
                if *self.peek() != Tok::QQStart {
                    return self.fail(&["QQSTRING_START"]);
                }
                self.parse_string(Some(f))?
            }
            _ => return self.fail(&["FORMAT", "QQSTRING_START"]),
        };
        let en = self.toks[self.pos - 1].end;
        match const_value(&e) {
            Some(Value::Str(s)) => Ok((s.to_string(), st, en)),
            _ => {
                self.semantic_error("Import path must be constant".into(), st, en);
                Err(())
            }
        }
    }

    fn parse_import(&mut self) -> PResult<Import> {
        let is_include = self.is_kw("include");
        let pos = self.toks[self.pos].start;
        self.advance();
        let (path, _, _) = self.parse_string_const()?;
        let mut imp = Import { path, alias: None, is_data: false, meta: None, pos };
        if !is_include {
            if !self.is_kw("as") {
                return self.fail(&["as"]);
            }
            self.advance();
            match self.peek().clone() {
                Tok::Ident(n) => {
                    self.advance();
                    imp.alias = Some(n);
                }
                Tok::Binding(n) => {
                    self.advance();
                    imp.alias = Some(n);
                    imp.is_data = true;
                }
                _ => return self.fail(&["IDENT", "BINDING"]),
            }
        }
        if !self.is_punct(';') {
            // metadata
            let st = self.toks[self.pos].start;
            let e = self.parse_pipe(false)?;
            let en = self.toks[self.pos.saturating_sub(1)].end;
            if !self.is_punct(';') {
                return self.exp_fail(&[], &["';'"]);
            }
            match const_value(&e) {
                Some(v @ Value::Obj(_)) => imp.meta = Some(v),
                _ => {
                    self.semantic_error("Module metadata must be constant".into(), st, en);
                    return Err(());
                }
            }
        }
        self.advance();
        Ok(imp)
    }

    fn parse_funcdef(&mut self) -> PResult<Rc<FuncDefAst>> {
        let pos = self.toks[self.pos].start;
        self.advance(); // def
        let name = match self.peek().clone() {
            Tok::Ident(n) => {
                self.advance();
                n
            }
            _ => return self.fail(&["IDENT"]),
        };
        let mut params = Vec::new();
        if self.is_punct('(') {
            self.advance();
            loop {
                match self.peek().clone() {
                    Tok::Ident(n) => {
                        self.advance();
                        params.push(n);
                    }
                    Tok::Binding(n) => {
                        self.advance();
                        params.push(format!("${}", n));
                    }
                    _ => return self.fail(&["IDENT", "BINDING"]),
                }
                if self.is_punct(';') {
                    self.advance();
                    continue;
                }
                if self.is_punct(')') {
                    self.advance();
                    break;
                }
                return self.fail(&["';'", "')'"]);
            }
        }
        if !self.is_punct(':') {
            if params.is_empty() {
                return self.fail(&["':'", "'('"]);
            }
            return self.fail(&["':'"]);
        }
        self.advance();
        let body = self.parse_pipe(false)?;
        if !self.is_punct(';') {
            return self.exp_fail(&[], &["';'"]);
        }
        self.advance();
        Ok(Rc::new(FuncDefAst { name, params, body, pos }))
    }

    // ---------------- expressions ----------------

    /// Pipe level: handles '|' (right assoc) and lower-precedence constructs.
    /// no_comma: object-value context
    fn parse_pipe(&mut self, no_comma: bool) -> PResult<Ast> {
        let lhs = self.parse_comma(no_comma)?;
        if self.is_punct('|') {
            self.advance();
            let rhs = self.parse_pipe(no_comma)?;
            return Ok(Ast::Pipe(Box::new(lhs), Box::new(rhs)));
        }
        Ok(lhs)
    }

    fn parse_comma(&mut self, no_comma: bool) -> PResult<Ast> {
        let mut lhs = self.parse_binary(3, no_comma)?;
        if no_comma {
            return Ok(lhs);
        }
        while self.is_punct(',') {
            self.advance();
            let rhs = self.parse_binary(3, no_comma)?;
            lhs = Ast::Comma(Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }

    fn binop_info(&self) -> Option<(u8, &'static str)> {
        // returns precedence level and op string
        match self.peek() {
            Tok::Op("//") => Some((3, "//")),
            Tok::Punct('=') => Some((4, "=")),
            Tok::Op("|=") => Some((4, "|=")),
            Tok::Op("+=") => Some((4, "+=")),
            Tok::Op("-=") => Some((4, "-=")),
            Tok::Op("*=") => Some((4, "*=")),
            Tok::Op("/=") => Some((4, "/=")),
            Tok::Op("%=") => Some((4, "%=")),
            Tok::Op("//=") => Some((4, "//=")),
            Tok::Keyword("or") => Some((5, "or")),
            Tok::Keyword("and") => Some((6, "and")),
            Tok::Op("==") => Some((7, "==")),
            Tok::Op("!=") => Some((7, "!=")),
            Tok::Punct('<') => Some((7, "<")),
            Tok::Op("<=") => Some((7, "<=")),
            Tok::Punct('>') => Some((7, ">")),
            Tok::Op(">=") => Some((7, ">=")),
            Tok::Punct('+') => Some((8, "+")),
            Tok::Punct('-') => Some((8, "-")),
            Tok::Punct('*') => Some((9, "*")),
            Tok::Punct('/') => Some((9, "/")),
            Tok::Punct('%') => Some((9, "%")),
            _ => None,
        }
    }

    fn parse_binary(&mut self, min_prec: u8, no_comma: bool) -> PResult<Ast> {
        let mut lhs = self.parse_unary(no_comma)?;
        loop {
            let (prec, op) = match self.binop_info() {
                Some(x) => x,
                None => break,
            };
            if prec < min_prec {
                break;
            }
            self.advance();
            let right_assoc = prec == 3;
            let nonassoc = prec == 4 || prec == 7;
            let next_min = if right_assoc { prec } else { prec + 1 };
            let rhs = self.parse_binary(next_min, no_comma)?;
            lhs = make_binop(op, lhs, rhs);
            if nonassoc {
                if let Some((p2, _)) = self.binop_info() {
                    if p2 == prec {
                        return self.fail(&[]);
                    }
                }
            }
        }
        Ok(lhs)
    }

    fn parse_unary(&mut self, no_comma: bool) -> PResult<Ast> {
        if self.is_punct('-') {
            self.advance();
            let e = self.parse_binary(9, no_comma)?;
            return Ok(Ast::Neg(Box::new(e)));
        }
        self.parse_postfix(true, no_comma)
    }

    /// Postfix term; if allow_as, handles `Term as Patterns | Exp`
    fn parse_postfix(&mut self, allow_as: bool, no_comma: bool) -> PResult<Ast> {
        let mut t = self.parse_primary(no_comma)?;
        loop {
            match self.peek().clone() {
                Tok::Field(name) => {
                    self.advance();
                    t = Ast::Index(Box::new(t), Box::new(Ast::Literal(Value::from_string(name))));
                }
                Tok::Punct('.') => {
                    // Term '.' String  or Term '.' '['
                    match self.peek_at(1).clone() {
                        Tok::QQStart => {
                            self.advance();
                            let s = self.parse_string(None)?;
                            t = Ast::Index(Box::new(t), Box::new(s));
                        }
                        Tok::Format(f) => {
                            if *self.peek_at(2) == Tok::QQStart {
                                self.advance();
                                self.advance();
                                let s = self.parse_string(Some(f))?;
                                t = Ast::Index(Box::new(t), Box::new(s));
                            } else {
                                self.advance();
                                self.advance();
                                return self.fail(&["QQSTRING_START"]);
                            }
                        }
                        Tok::Punct('[') => {
                            self.advance();
                            t = self.parse_bracket_suffix(t)?;
                        }
                        _ => {
                            self.advance();
                            return self.fail(&["FORMAT", "QQSTRING_START", "'['"]);
                        }
                    }
                }
                Tok::Punct('[') => {
                    t = self.parse_bracket_suffix(t)?;
                }
                Tok::Punct('?') => {
                    self.advance();
                    t = Ast::Try(Box::new(t), None);
                }
                _ => break,
            }
        }
        if allow_as && self.is_kw("as") {
            if no_comma {
                return self.fail(&["'}'"]);
            }
            self.advance();
            let pats = self.parse_patterns()?;
            if !self.is_punct('|') {
                return self.fail(&["'|'"]);
            }
            self.advance();
            let body = self.parse_pipe(false)?;
            return Ok(Ast::Bind(Box::new(t), pats, Box::new(body)));
        }
        Ok(t)
    }

    fn parse_bracket_suffix(&mut self, t: Ast) -> PResult<Ast> {
        // at '['
        let open_idx = self.pos;
        self.advance();
        self.ctx.push((Ctx::Bracket, open_idx));
        let r = self.parse_bracket_inner(t);
        self.ctx.pop();
        r
    }

    fn parse_bracket_inner(&mut self, t: Ast) -> PResult<Ast> {
        if self.is_punct(']') {
            self.advance();
            return Ok(Ast::Iterate(Box::new(t)));
        }
        if self.is_punct(':') {
            self.advance();
            let hi = self.parse_pipe(false)?;
            if !self.is_punct(']') {
                return self.exp_fail(&[], &["']'"]);
            }
            self.advance();
            return Ok(Ast::Slice(Box::new(t), None, Some(Box::new(hi))));
        }
        let lo = self.parse_pipe(false)?;
        if self.is_punct(':') {
            self.advance();
            if self.is_punct(']') {
                self.advance();
                return Ok(Ast::Slice(Box::new(t), Some(Box::new(lo)), None));
            }
            let hi = self.parse_pipe(false)?;
            if !self.is_punct(']') {
                return self.exp_fail(&[], &["']'"]);
            }
            self.advance();
            return Ok(Ast::Slice(Box::new(t), Some(Box::new(lo)), Some(Box::new(hi))));
        }
        if !self.is_punct(']') {
            return self.exp_fail(&[], &["':'", "']'"]);
        }
        self.advance();
        Ok(Ast::Index(Box::new(t), Box::new(lo)))
    }

    fn parse_string(&mut self, fmt: Option<String>) -> PResult<Ast> {
        // at QQStart
        self.advance();
        let mut parts = Vec::new();
        loop {
            match self.peek().clone() {
                Tok::QQText(s) => {
                    let t = self.advance();
                    if let Some(e) = &t.qqtext_err {
                        self.semantic_error(e.clone(), t.start, t.end);
                    }
                    parts.push(StrPart::Lit(s));
                }
                Tok::QQInterpStart => {
                    self.advance();
                    let e = self.parse_pipe(false)?;
                    if *self.peek() != Tok::QQInterpEnd {
                        return self.exp_fail(&["QQSTRING_INTERP_END"], &[]);
                    }
                    self.advance();
                    parts.push(StrPart::Interp(e));
                }
                Tok::QQEnd => {
                    self.advance();
                    break;
                }
                _ => return self.fail(&["QQSTRING_TEXT", "QQSTRING_INTERP_START", "QQSTRING_END"]),
            }
        }
        // constant string?
        if parts.iter().all(|p| matches!(p, StrPart::Lit(_))) {
            let mut s = String::new();
            for p in &parts {
                if let StrPart::Lit(x) = p {
                    s.push_str(x);
                }
            }
            return Ok(Ast::Literal(Value::from_string(s)));
        }
        Ok(Ast::Str(fmt, parts))
    }

    fn parse_primary(&mut self, no_comma: bool) -> PResult<Ast> {
        let tok = self.peek().clone();
        let tidx = self.pos;
        match tok {
            Tok::Literal(s) => {
                self.advance();
                Ok(Ast::Literal(parse_number_literal(&s)))
            }
            Tok::QQStart => self.parse_string(None),
            Tok::Format(f) => {
                self.advance();
                if *self.peek() == Tok::QQStart {
                    return self.parse_string(Some(f));
                }
                Ok(Ast::Format(f))
            }
            Tok::Punct('.') => {
                self.advance();
                match self.peek().clone() {
                    Tok::QQStart => {
                        let s = self.parse_string(None)?;
                        Ok(Ast::Index(Box::new(Ast::Identity), Box::new(s)))
                    }
                    Tok::Format(f) if *self.peek_at(1) == Tok::QQStart => {
                        self.advance();
                        let s = self.parse_string(Some(f))?;
                        Ok(Ast::Index(Box::new(Ast::Identity), Box::new(s)))
                    }
                    _ => Ok(Ast::Identity),
                }
            }
            Tok::Field(name) => {
                self.advance();
                Ok(Ast::Index(Box::new(Ast::Identity), Box::new(Ast::Literal(Value::from_string(name)))))
            }
            Tok::Op("..") => {
                self.advance();
                Ok(Ast::RecurseDefault)
            }
            Tok::Loc => {
                let t = self.advance();
                Ok(Ast::Loc(t.start))
            }
            Tok::Binding(name) => {
                let t = self.advance();
                Ok(Ast::Var(name, t.start, t.end))
            }
            Tok::Punct('$') => {
                self.advance();
                self.fail(&["'$'"])
            }
            Tok::Punct('(') => {
                self.advance();
                self.ctx.push((Ctx::Paren, tidx));
                let r = (|| -> PResult<Ast> {
                    let e = self.parse_pipe(false)?;
                    if !self.is_punct(')') {
                        return self.exp_fail(&[], &["')'"]);
                    }
                    self.advance();
                    Ok(e)
                })();
                self.ctx.pop();
                r
            }
            Tok::Punct('[') => {
                self.advance();
                if self.is_punct(']') {
                    self.advance();
                    return Ok(Ast::Array(None));
                }
                self.ctx.push((Ctx::Bracket, tidx));
                let r = (|| -> PResult<Ast> {
                    let e = self.parse_pipe(false)?;
                    if !self.is_punct(']') {
                        return self.exp_fail(&[], &["']'"]);
                    }
                    self.advance();
                    Ok(e)
                })();
                self.ctx.pop();
                Ok(Ast::Array(Some(Box::new(r?))))
            }
            Tok::Punct('{') => {
                self.advance();
                self.ctx.push((Ctx::Brace, tidx));
                let r = self.parse_object();
                self.ctx.pop();
                r
            }
            Tok::Ident(name) => {
                let t = self.advance();
                let mut args = Vec::new();
                if self.is_punct('(') {
                    let open = self.pos;
                    self.advance();
                    self.ctx.push((Ctx::Paren, open));
                    let r = (|| -> PResult<()> {
                        loop {
                            let a = self.parse_pipe(false)?;
                            args.push(a);
                            if self.is_punct(';') {
                                self.advance();
                                continue;
                            }
                            if self.is_punct(')') {
                                self.advance();
                                break;
                            }
                            return self.fail(&["';'", "')'"]);
                        }
                        Ok(())
                    })();
                    self.ctx.pop();
                    r?;
                }
                Ok(Ast::Call(name, args, t.start, t.end))
            }
            Tok::Keyword("break") => {
                let t = self.advance();
                match self.peek().clone() {
                    Tok::Binding(n) => {
                        let b = self.advance();
                        Ok(Ast::Break(n, t.start, b.end))
                    }
                    _ => self.fail(&["BINDING"]),
                }
            }
            Tok::Keyword("reduce") | Tok::Keyword("foreach") => {
                let is_reduce = tok == Tok::Keyword("reduce");
                self.advance();
                let src = self.parse_postfix(false, false)?;
                if !self.is_kw("as") {
                    return self.fail(&["as"]);
                }
                self.advance();
                let pats = self.parse_patterns()?;
                if !self.is_punct('(') {
                    return self.fail(&["'('"]);
                }
                let open = self.pos;
                self.advance();
                self.ctx.push((Ctx::Paren, open));
                let r = (|| -> PResult<Ast> {
                    let init = self.parse_pipe(false)?;
                    if !self.is_punct(';') {
                        return self.exp_fail(&[], &["';'"]);
                    }
                    self.advance();
                    let update = self.parse_pipe(false)?;
                    if is_reduce {
                        if !self.is_punct(')') {
                            return self.exp_fail(&[], &["')'"]);
                        }
                        self.advance();
                        return Ok(Ast::Reduce(Box::new(src.clone()), pats.clone(), Box::new(init), Box::new(update)));
                    }
                    let mut extract = None;
                    if self.is_punct(';') {
                        self.advance();
                        let ex = self.parse_pipe(false)?;
                        if !self.is_punct(')') {
                            return self.exp_fail(&[], &["')'"]);
                        }
                        extract = Some(Box::new(ex));
                    } else if !self.is_punct(')') {
                        return self.exp_fail(&[], &["';'", "')'"]);
                    }
                    self.advance();
                    Ok(Ast::Foreach(Box::new(src.clone()), pats.clone(), Box::new(init), Box::new(update), extract))
                })();
                self.ctx.pop();
                r
            }
            Tok::Keyword("if") => {
                self.advance();
                let mut branches = Vec::new();
                let cond = self.parse_pipe(false)?;
                if !self.is_kw("then") {
                    return self.exp_fail(&["then"], &[]);
                }
                self.advance();
                self.ctx.push((Ctx::IfThen, tidx));
                let r = (|| -> PResult<Ast> {
                    let mut cond = cond;
                    loop {
                        let body = self.parse_pipe(false)?;
                        branches.push((cond, body));
                        if self.is_kw("elif") {
                            self.advance();
                            cond = self.parse_pipe(false)?;
                            if !self.is_kw("then") {
                                return self.exp_fail(&["then"], &[]);
                            }
                            self.advance();
                            continue;
                        }
                        if self.is_kw("else") {
                            self.advance();
                            let e = self.parse_pipe(false)?;
                            if !self.is_kw("end") {
                                return self.exp_fail(&["end"], &[]);
                            }
                            self.advance();
                            return Ok(Ast::If(branches.clone(), Some(Box::new(e))));
                        }
                        if self.is_kw("end") {
                            self.advance();
                            return Ok(Ast::If(branches.clone(), None));
                        }
                        return self.exp_fail(&["else", "elif", "end"], &[]);
                    }
                })();
                self.ctx.pop();
                r
            }
            Tok::Keyword("try") => {
                self.advance();
                let body = self.parse_try_body()?;
                if self.is_kw("catch") {
                    self.advance();
                    self.ctx.push((Ctx::TryCatch, tidx));
                    let r = self.parse_try_body();
                    self.ctx.pop();
                    let c = r?;
                    return Ok(Ast::Try(Box::new(body), Some(Box::new(c))));
                }
                Ok(Ast::Try(Box::new(body), None))
            }
            Tok::Keyword("label") => {
                if no_comma {
                    return self.fail(&[]);
                }
                self.advance();
                let name = match self.peek().clone() {
                    Tok::Binding(n) => {
                        self.advance();
                        n
                    }
                    _ => return self.fail(&["BINDING"]),
                };
                if !self.is_punct('|') {
                    return self.fail(&["'|'"]);
                }
                self.advance();
                let body = self.parse_pipe(false)?;
                Ok(Ast::Label(name, Box::new(body)))
            }
            Tok::Keyword("def") => {
                if no_comma {
                    return self.fail(&[]);
                }
                let d = self.parse_funcdef()?;
                let rest = self.parse_pipe(false)?;
                Ok(Ast::FuncDef(d, Box::new(rest)))
            }
            _ => self.fail(&[]),
        }
    }

    fn parse_try_body(&mut self) -> PResult<Ast> {
        // "try" Exp with high precedence: effectively a postfix term (or unary minus)
        if self.is_punct('-') {
            self.advance();
            let e = self.parse_try_body()?;
            return Ok(Ast::Neg(Box::new(e)));
        }
        self.parse_postfix(true, false)
    }

    fn parse_object(&mut self) -> PResult<Ast> {
        let mut entries: Vec<(ObjKey, Option<Ast>)> = Vec::new();
        if self.is_punct('}') {
            self.advance();
            return Ok(Ast::Object(entries));
        }
        loop {
            let pair_idx = self.pos;
            self.ctx.push((Ctx::ObjPair(pair_idx), pair_idx));
            let r = self.parse_obj_pair();
            self.ctx.pop();
            let (k, v) = r?;
            entries.push((k, v));
            if self.is_punct(',') {
                self.advance();
                continue;
            }
            if self.is_punct('}') {
                self.advance();
                break;
            }
            return self.fail(&["'}'"]);
        }
        Ok(Ast::Object(entries))
    }

    fn parse_obj_pair(&mut self) -> PResult<(ObjKey, Option<Ast>)> {
        let tok = self.peek().clone();
        let key: ObjKey;
        let mut allow_shorthand = true;
        match tok {
            Tok::Ident(n) => {
                self.advance();
                key = ObjKey::Expr(Ast::Literal(Value::from_string(n)));
            }
            Tok::Keyword(k) => {
                self.advance();
                key = ObjKey::Expr(Ast::Literal(Value::from_str(k)));
            }
            Tok::Binding(n) => {
                let t = self.advance();
                key = ObjKey::Var(n, t.start);
            }
            Tok::Loc => {
                let t = self.advance();
                if self.is_punct(':') {
                    return self.fail(&["'}'"]);
                }
                return Ok((ObjKey::Loc(t.start), None));
            }
            Tok::QQStart => {
                let s = self.parse_string(None)?;
                key = ObjKey::Expr(s);
            }
            Tok::Format(f) => {
                self.advance();
                if *self.peek() != Tok::QQStart {
                    return self.fail(&["QQSTRING_START"]);
                }
                let s = self.parse_string(Some(f))?;
                key = ObjKey::Expr(s);
            }
            Tok::Punct('(') => {
                let open = self.pos;
                self.advance();
                self.ctx.push((Ctx::Paren, open));
                let kst = self.toks[self.pos].start;
                let r = (|| -> PResult<Ast> {
                    let e = self.parse_pipe(false)?;
                    if !self.is_punct(')') {
                        return self.exp_fail(&[], &["')'"]);
                    }
                    Ok(e)
                })();
                self.ctx.pop();
                let e = r?;
                let ken = self.toks[self.pos - 1].end;
                self.advance();
                let e = fold_constants(e);
                if let Ast::Literal(v) = &e {
                    if !matches!(v, Value::Str(_)) {
                        self.semantic_error(
                            format!(
                                "Cannot use {} ({}) as object key",
                                v.type_name(),
                                crate::json::dump_trunc(v, 15)
                            ),
                            kst,
                            ken,
                        );
                    }
                }
                key = ObjKey::Expr(e);
                allow_shorthand = false;
            }
            _ => return self.fail(&[]),
        }
        if self.is_punct(':') {
            self.advance();
            let v = self.parse_pipe(true)?;
            return Ok((key, Some(v)));
        }
        if !allow_shorthand {
            return self.fail(&["':'"]);
        }
        if !self.is_punct(',') && !self.is_punct('}') {
            return self.fail(&["'}'"]);
        }
        Ok((key, None))
    }

    fn parse_patterns(&mut self) -> PResult<Vec<Pattern>> {
        let mut v = vec![self.parse_pattern()?];
        while self.is_op("?//") {
            self.advance();
            v.push(self.parse_pattern()?);
        }
        Ok(v)
    }

    fn parse_pattern(&mut self) -> PResult<Pattern> {
        match self.peek().clone() {
            Tok::Binding(n) => {
                let t = self.advance();
                Ok(Pattern::Var(n, t.start))
            }
            Tok::Punct('[') => {
                self.advance();
                let mut elems = Vec::new();
                loop {
                    elems.push(self.parse_pattern()?);
                    if self.is_punct(',') {
                        self.advance();
                        continue;
                    }
                    if self.is_punct(']') {
                        self.advance();
                        break;
                    }
                    return self.fail(&["','", "']'"]);
                }
                Ok(Pattern::Array(elems))
            }
            Tok::Punct('{') => {
                self.advance();
                let mut entries = Vec::new();
                loop {
                    let e = self.parse_objpat_entry()?;
                    entries.push(e);
                    if self.is_punct(',') {
                        self.advance();
                        continue;
                    }
                    if self.is_punct('}') {
                        self.advance();
                        break;
                    }
                    return self.fail(&["','", "'}'"]);
                }
                Ok(Pattern::Object(entries))
            }
            _ => self.fail(&["BINDING", "'['", "'{'"]),
        }
    }

    fn parse_objpat_entry(&mut self) -> PResult<(ObjPatKey, Option<Pattern>)> {
        match self.peek().clone() {
            Tok::Binding(n) => {
                let t = self.advance();
                if self.is_punct(':') {
                    self.advance();
                    let p = self.parse_pattern()?;
                    return Ok((ObjPatKey::Var(n, t.start), Some(p)));
                }
                Ok((ObjPatKey::Var(n, t.start), None))
            }
            Tok::Ident(n) => {
                self.advance();
                if !self.is_punct(':') {
                    return self.fail(&["':'"]);
                }
                self.advance();
                let p = self.parse_pattern()?;
                Ok((ObjPatKey::Expr(Box::new(Ast::Literal(Value::from_string(n)))), Some(p)))
            }
            Tok::Keyword(k) => {
                self.advance();
                if !self.is_punct(':') {
                    return self.fail(&["':'"]);
                }
                self.advance();
                let p = self.parse_pattern()?;
                Ok((ObjPatKey::Expr(Box::new(Ast::Literal(Value::from_str(k)))), Some(p)))
            }
            Tok::QQStart | Tok::Format(_) => {
                let s = match self.peek().clone() {
                    Tok::Format(f) => {
                        self.advance();
                        if *self.peek() != Tok::QQStart {
                            return self.fail(&["QQSTRING_START"]);
                        }
                        self.parse_string(Some(f))?
                    }
                    _ => self.parse_string(None)?,
                };
                if !self.is_punct(':') {
                    return self.fail(&["':'"]);
                }
                self.advance();
                let p = self.parse_pattern()?;
                Ok((ObjPatKey::Expr(Box::new(s)), Some(p)))
            }
            Tok::Punct('(') => {
                self.advance();
                let e = self.parse_pipe(false)?;
                if !self.is_punct(')') {
                    return self.exp_fail(&[], &["')'"]);
                }
                self.advance();
                if !self.is_punct(':') {
                    return self.fail(&["':'"]);
                }
                self.advance();
                let p = self.parse_pattern()?;
                Ok((ObjPatKey::Expr(Box::new(e)), Some(p)))
            }
            _ => self.fail(&[]),
        }
    }
}

fn make_binop(op: &str, l: Ast, r: Ast) -> Ast {
    let b = |o: BinOp, l: Ast, r: Ast| fold_constants(Ast::Bin(o, Box::new(l), Box::new(r)));
    match op {
        "//" => Ast::Alt(Box::new(l), Box::new(r)),
        "=" => Ast::Assign(AssignOp::Set, Box::new(l), Box::new(r)),
        "|=" => Ast::Assign(AssignOp::Update, Box::new(l), Box::new(r)),
        "+=" => Ast::Assign(AssignOp::Arith(BinOp::Add), Box::new(l), Box::new(r)),
        "-=" => Ast::Assign(AssignOp::Arith(BinOp::Sub), Box::new(l), Box::new(r)),
        "*=" => Ast::Assign(AssignOp::Arith(BinOp::Mul), Box::new(l), Box::new(r)),
        "/=" => Ast::Assign(AssignOp::Arith(BinOp::Div), Box::new(l), Box::new(r)),
        "%=" => Ast::Assign(AssignOp::Arith(BinOp::Mod), Box::new(l), Box::new(r)),
        "//=" => Ast::Assign(AssignOp::Alt, Box::new(l), Box::new(r)),
        "or" => Ast::Or(Box::new(l), Box::new(r)),
        "and" => Ast::And(Box::new(l), Box::new(r)),
        "==" => b(BinOp::Eq, l, r),
        "!=" => b(BinOp::Ne, l, r),
        "<" => b(BinOp::Lt, l, r),
        "<=" => b(BinOp::Le, l, r),
        ">" => b(BinOp::Gt, l, r),
        ">=" => b(BinOp::Ge, l, r),
        "+" => b(BinOp::Add, l, r),
        "-" => b(BinOp::Sub, l, r),
        "*" => b(BinOp::Mul, l, r),
        "/" => b(BinOp::Div, l, r),
        "%" => b(BinOp::Mod, l, r),
        _ => unreachable!(),
    }
}

pub fn fold_constants(e: Ast) -> Ast {
    if let Ast::Bin(op, l, r) = &e {
        if let (Ast::Literal(a), Ast::Literal(b)) = (&**l, &**r) {
            if let Ok(v) = crate::interp::binop(*op, a.clone(), b.clone()) {
                return Ast::Literal(v);
            }
        }
    }
    e
}

pub fn const_value(e: &Ast) -> Option<Value> {
    match e {
        Ast::Literal(v) => Some(v.clone()),
        Ast::Neg(x) => match const_value(x) {
            Some(Value::Num(f)) => Some(Value::Num(-f)),
            Some(Value::Lit(l)) => Some(Value::Lit(Rc::new(number::negate_literal(&l)))),
            _ => None,
        },
        Ast::Array(None) => Some(Value::from_vec(vec![])),
        Ast::Array(Some(x)) => {
            let mut out = Vec::new();
            fn collect(e: &Ast, out: &mut Vec<Value>) -> bool {
                match e {
                    Ast::Comma(a, b) => collect(a, out) && collect(b, out),
                    _ => match const_value(e) {
                        Some(v) => {
                            out.push(v);
                            true
                        }
                        None => false,
                    },
                }
            }
            if collect(x, &mut out) {
                Some(Value::from_vec(out))
            } else {
                None
            }
        }
        Ast::Object(entries) => {
            let mut m = crate::value::Map::new();
            for (k, v) in entries {
                let key = match k {
                    ObjKey::Expr(e) => match const_value(e) {
                        Some(Value::Str(s)) => s,
                        _ => return None,
                    },
                    _ => return None,
                };
                let val = match v {
                    Some(v) => const_value(v)?,
                    None => return None,
                };
                m.insert(key, val);
            }
            Some(Value::from_map(m))
        }
        _ => None,
    }
}
