// Core value operations with jq-compatible error messages
use crate::ast::BinOp;
use crate::json::{dump_trunc, to_json};
use crate::number;
use crate::value::{compare, equal, Map, Value};
use std::cmp::Ordering;
use std::rc::Rc;

pub type VResult = Result<Value, Value>;

pub fn err<T>(msg: String) -> Result<T, Value> {
    Err(Value::from_string(msg))
}

pub fn kind_name(v: &Value) -> &'static str {
    v.type_name()
}

fn type_error2(a: &Value, b: &Value, msg: &str) -> Value {
    Value::from_string(format!(
        "{} ({}) and {} ({}) {}",
        kind_name(a),
        dump_trunc(a, 15),
        kind_name(b),
        dump_trunc(b, 15),
        msg
    ))
}

pub fn type_error(a: &Value, msg: &str) -> Value {
    Value::from_string(format!("{} ({}) {}", kind_name(a), dump_trunc(a, 15), msg))
}

pub fn str_len_cp(s: &str) -> usize {
    s.chars().count()
}

pub fn binop(op: BinOp, a: Value, b: Value) -> VResult {
    match op {
        BinOp::Add => add(a, b),
        BinOp::Sub => sub(a, b),
        BinOp::Mul => mul(a, b),
        BinOp::Div => div(a, b),
        BinOp::Mod => modulo(a, b),
        BinOp::Eq => Ok(Value::from_bool(equal(&a, &b))),
        BinOp::Ne => Ok(Value::from_bool(!equal(&a, &b))),
        BinOp::Lt => Ok(Value::from_bool(compare(&a, &b) == Ordering::Less)),
        BinOp::Le => Ok(Value::from_bool(compare(&a, &b) != Ordering::Greater)),
        BinOp::Gt => Ok(Value::from_bool(compare(&a, &b) == Ordering::Greater)),
        BinOp::Ge => Ok(Value::from_bool(compare(&a, &b) != Ordering::Less)),
    }
}

pub fn add(a: Value, b: Value) -> VResult {
    match (a, b) {
        (Value::Null, b) => Ok(b),
        (a, Value::Null) => Ok(a),
        (a @ (Value::Num(_) | Value::Lit(_)), b @ (Value::Num(_) | Value::Lit(_))) => {
            Ok(Value::Num(a.as_f64() + b.as_f64()))
        }
        (Value::Str(x), Value::Str(y)) => {
            let mut s = String::with_capacity(x.len() + y.len());
            s.push_str(&x);
            s.push_str(&y);
            Ok(Value::from_string(s))
        }
        (Value::Arr(mut x), Value::Arr(y)) => {
            if x.is_empty() {
                return Ok(Value::Arr(y));
            }
            Rc::make_mut(&mut x).extend(y.iter().cloned());
            Ok(Value::Arr(x))
        }
        (Value::Obj(mut x), Value::Obj(y)) => {
            let m = Rc::make_mut(&mut x);
            for (k, v) in y.iter() {
                m.insert(k.clone(), v.clone());
            }
            Ok(Value::Obj(x))
        }
        (a, b) => Err(type_error2(&a, &b, "cannot be added")),
    }
}

pub fn sub(a: Value, b: Value) -> VResult {
    match (&a, &b) {
        (Value::Num(_) | Value::Lit(_), Value::Num(_) | Value::Lit(_)) => Ok(Value::Num(a.as_f64() - b.as_f64())),
        (Value::Arr(x), Value::Arr(y)) => {
            let out: Vec<Value> = x.iter().filter(|e| !y.iter().any(|f| equal(e, f))).cloned().collect();
            Ok(Value::from_vec(out))
        }
        _ => Err(type_error2(&a, &b, "cannot be subtracted")),
    }
}

fn deep_merge(a: Rc<Map>, b: &Map) -> Rc<Map> {
    let mut a = a;
    let m = Rc::make_mut(&mut a);
    for (k, v) in b.iter() {
        let nv = match (m.get(k), v) {
            (Some(Value::Obj(x)), Value::Obj(y)) => Value::Obj(deep_merge(x.clone(), y)),
            _ => v.clone(),
        };
        m.insert(k.clone(), nv);
    }
    a
}

fn repeat_string(s: &str, n: &Value) -> VResult {
    let d = n.as_f64();
    if d.is_nan() || d < 0.0 {
        return Ok(Value::Null);
    }
    let n = if d > i32::MAX as f64 { i32::MAX as usize } else { d as usize };
    let total = s.len().checked_mul(n);
    match total {
        Some(t) if t <= i32::MAX as usize => Ok(Value::from_string(s.repeat(n))),
        _ => err("Repeat string result too long".into()),
    }
}

pub fn mul(a: Value, b: Value) -> VResult {
    match (&a, &b) {
        (Value::Num(_) | Value::Lit(_), Value::Num(_) | Value::Lit(_)) => Ok(Value::Num(a.as_f64() * b.as_f64())),
        (Value::Str(s), Value::Num(_) | Value::Lit(_)) => repeat_string(s, &b),
        (Value::Num(_) | Value::Lit(_), Value::Str(s)) => repeat_string(s, &a),
        (Value::Obj(x), Value::Obj(y)) => Ok(Value::Obj(deep_merge(x.clone(), y))),
        _ => Err(type_error2(&a, &b, "cannot be multiplied")),
    }
}

pub fn div(a: Value, b: Value) -> VResult {
    match (&a, &b) {
        (Value::Num(_) | Value::Lit(_), Value::Num(_) | Value::Lit(_)) => {
            if b.as_f64() == 0.0 {
                return Err(type_error2(&a, &b, "cannot be divided because the divisor is zero"));
            }
            Ok(Value::Num(a.as_f64() / b.as_f64()))
        }
        (Value::Str(x), Value::Str(y)) => Ok(split_string(x, y)),
        _ => Err(type_error2(&a, &b, "cannot be divided")),
    }
}

fn dtoi(n: f64) -> i64 {
    if n < i64::MIN as f64 {
        i64::MIN
    } else if -n < i64::MIN as f64 {
        i64::MAX
    } else {
        n as i64
    }
}

pub fn modulo(a: Value, b: Value) -> VResult {
    match (&a, &b) {
        (Value::Num(_) | Value::Lit(_), Value::Num(_) | Value::Lit(_)) => {
            let na = a.as_f64();
            let nb = b.as_f64();
            if na.is_nan() || nb.is_nan() {
                return Ok(Value::Num(f64::NAN));
            }
            let bi = dtoi(nb);
            if bi == 0 {
                return Err(type_error2(&a, &b, "cannot be divided (remainder) because the divisor is zero"));
            }
            let r = if bi == -1 { 0 } else { dtoi(na) % bi };
            Ok(Value::Num(r as f64))
        }
        _ => Err(type_error2(&a, &b, "cannot be divided (remainder)")),
    }
}

pub fn split_string(s: &str, sep: &str) -> Value {
    let mut out = Vec::new();
    if sep.is_empty() {
        for c in s.chars() {
            out.push(Value::from_string(c.to_string()));
        }
    } else if !s.is_empty() {
        let mut rest = s;
        loop {
            match rest.find(sep) {
                Some(i) => {
                    out.push(Value::from_str(&rest[..i]));
                    rest = &rest[i + sep.len()..];
                    if rest.is_empty() {
                        out.push(Value::from_str(""));
                        break;
                    }
                }
                None => {
                    out.push(Value::from_str(rest));
                    break;
                }
            }
        }
    }
    Value::from_vec(out)
}

pub fn negate(v: Value) -> VResult {
    match &v {
        Value::Num(f) => Ok(Value::Num(-f)),
        Value::Lit(l) => Ok(Value::Lit(Rc::new(number::negate_literal(l)))),
        _ => Err(type_error(&v, "cannot be negated")),
    }
}

// ---------- indexing ----------

fn index_error(t: &Value, k: &Value) -> Value {
    if let Value::Str(s) = k {
        if s.len() < 30 {
            return Value::from_string(format!("Cannot index {} with string \"{}\"", kind_name(t), s));
        }
    }
    Value::from_string(format!("Cannot index {} with {}", kind_name(t), kind_name(k)))
}

fn array_index(len: usize, k: &Value) -> Option<usize> {
    let d = k.as_f64();
    if d.is_nan() {
        return None;
    }
    let mut idx: i64 = if d >= i32::MAX as f64 {
        i32::MAX as i64
    } else if d <= i32::MIN as f64 {
        i32::MIN as i64
    } else {
        d as i64
    };
    if idx < 0 {
        idx += len as i64;
    }
    if idx < 0 || idx >= len as i64 {
        None
    } else {
        Some(idx as usize)
    }
}

/// returns (start, end) for slice
pub fn parse_slice(len: usize, k: &Map) -> Option<(usize, usize)> {
    let start = k.get("start");
    let end = k.get("end");
    let start = match start {
        None => return None,
        Some(Value::Null) => 0.0,
        Some(v) if v.is_number() => v.as_f64(),
        _ => return None,
    };
    let end = match end {
        None => return None,
        Some(Value::Null) => len as f64,
        Some(v) if v.is_number() => v.as_f64(),
        _ => return None,
    };
    let lenf = len as f64;
    let mut ds = if start.is_nan() { 0.0 } else { start };
    let mut de = if end.is_nan() { lenf } else { end };
    if ds < 0.0 {
        ds += lenf;
    }
    if de < 0.0 {
        de += lenf;
    }
    if ds < 0.0 {
        ds = 0.0;
    }
    if ds > lenf {
        ds = lenf;
    }
    if de > lenf {
        de = lenf;
    }
    if de < ds {
        de = ds;
    }
    let s = ds as usize;
    let e = if de > (de as usize) as f64 { de as usize + 1 } else { de as usize };
    let e = e.min(len);
    Some((s, e))
}

pub fn string_slice(s: &str, start: usize, end: usize) -> String {
    let mut out = String::new();
    for (i, c) in s.chars().enumerate() {
        if i >= end {
            break;
        }
        if i >= start {
            out.push(c);
        }
    }
    out
}

pub fn index(t: &Value, k: &Value) -> VResult {
    match (t, k) {
        (Value::Obj(o), Value::Str(s)) => Ok(o.get(s).cloned().unwrap_or(Value::Null)),
        (Value::Arr(a), Value::Num(_) | Value::Lit(_)) => match array_index(a.len(), k) {
            Some(i) => Ok(a[i].clone()),
            None => Ok(Value::Null),
        },
        (Value::Arr(a), Value::Obj(o)) => match parse_slice(a.len(), o) {
            Some((s, e)) => Ok(Value::from_vec(a[s..e].to_vec())),
            None => err("Array/string slice indices must be integers".into()),
        },
        (Value::Str(st), Value::Obj(o)) => {
            let len = str_len_cp(st);
            match parse_slice(len, o) {
                Some((s, e)) => Ok(Value::from_string(string_slice(st, s, e))),
                None => err("Array/string slice indices must be integers".into()),
            }
        }
        (Value::Arr(a), Value::Arr(b)) => Ok(array_indexes(a, b)),
        (Value::Null, Value::Str(_) | Value::Num(_) | Value::Lit(_) | Value::Obj(_)) => Ok(Value::Null),
        _ => Err(index_error(t, k)),
    }
}

pub fn array_indexes(a: &[Value], b: &[Value]) -> Value {
    let mut res = Vec::new();
    if b.is_empty() {
        return Value::from_vec(res);
    }
    let mut idx: i64 = -1;
    for ai in 0..a.len() {
        for (bi, bv) in b.iter().enumerate() {
            if ai + bi < a.len() && equal(&a[ai + bi], bv) {
                idx = ai as i64;
            } else {
                idx = -1;
                break;
            }
        }
        if idx > -1 {
            res.push(Value::Num(idx as f64));
        }
    }
    Value::from_vec(res)
}

pub fn slice_key(lo: Value, hi: Value) -> Value {
    let mut m = Map::new();
    m.insert(Rc::from("start"), lo);
    m.insert(Rc::from("end"), hi);
    Value::from_map(m)
}

// ---------- setting ----------

pub fn set(t: Value, k: &Value, v: Value) -> VResult {
    match (t, k) {
        (Value::Obj(mut o), Value::Str(s)) => {
            Rc::make_mut(&mut o).insert(s.clone(), v);
            Ok(Value::Obj(o))
        }
        (Value::Null, Value::Str(s)) => {
            let mut m = Map::new();
            m.insert(s.clone(), v);
            Ok(Value::from_map(m))
        }
        (t @ (Value::Arr(_) | Value::Null), Value::Num(_) | Value::Lit(_)) => {
            let mut a = match t {
                Value::Arr(a) => a,
                _ => Rc::new(Vec::new()),
            };
            let d = k.as_f64();
            let len = a.len() as i64;
            let mut idx: i64 = if d.is_nan() {
                0
            } else if d >= i32::MAX as f64 {
                i32::MAX as i64
            } else if d <= i32::MIN as f64 {
                i32::MIN as i64
            } else {
                d as i64
            };
            if idx < 0 {
                idx += len;
                if idx < 0 {
                    return err("Out of bounds negative array index".into());
                }
            }
            if idx > 536870911 {
                return err("Array index too large".into());
            }
            let idx = idx as usize;
            let am = Rc::make_mut(&mut a);
            if idx >= am.len() {
                am.resize(idx + 1, Value::Null);
            }
            am[idx] = v;
            Ok(Value::Arr(a))
        }
        (t @ (Value::Arr(_) | Value::Null), Value::Obj(ko)) => {
            let a = match t {
                Value::Arr(a) => a,
                _ => Rc::new(Vec::new()),
            };
            match parse_slice(a.len(), ko) {
                Some((s, e)) => match v {
                    Value::Arr(ins) => {
                        let mut out: Vec<Value> = Vec::with_capacity(a.len() + ins.len());
                        out.extend_from_slice(&a[..s]);
                        out.extend(ins.iter().cloned());
                        out.extend_from_slice(&a[e..]);
                        Ok(Value::from_vec(out))
                    }
                    _ => err("A slice of an array can only be assigned another array".into()),
                },
                None => err("Array/string slice indices must be integers".into()),
            }
        }
        (Value::Str(_), Value::Obj(_)) => err("Cannot update string slices".into()),
        (t, k) => Err(index_error(&t, k)),
    }
}

pub fn getpath(t: &Value, path: &Value) -> VResult {
    match path {
        Value::Null => Ok(t.clone()),
        Value::Arr(p) => {
            let mut cur = t.clone();
            for k in p.iter() {
                cur = index(&cur, k)?;
            }
            Ok(cur)
        }
        _ => err("Path must be specified as an array".into()),
    }
}

pub fn setpath(t: Value, path: &Value, v: Value) -> VResult {
    match path {
        Value::Arr(p) => setpath_slice(t, &p[..], v),
        _ => err("Path must be specified as an array".into()),
    }
}

fn setpath_slice(root: Value, p: &[Value], v: Value) -> VResult {
    if p.is_empty() {
        return Ok(v);
    }
    let cur = &p[0];
    if let Value::Obj(_) = cur {
        let sub = index(&root, cur)?;
        let nv = setpath_slice(sub, &p[1..], v)?;
        return set(root, cur, nv);
    }
    let sub = index(&root, cur)?;
    // drop reference in root to allow in-place modification
    let root = set(root, cur, Value::Null)?;
    let nv = setpath_slice(sub, &p[1..], v)?;
    set(root, cur, nv)
}

pub fn delpaths(t: Value, paths: &Value) -> VResult {
    let ps = match paths {
        Value::Arr(a) => a,
        _ => return err("Paths must be specified as an array".into()),
    };
    let mut ps: Vec<Value> = ps.to_vec();
    ps.sort_by(compare);
    for p in &ps {
        if !matches!(p, Value::Arr(_)) {
            return err(format!("Path must be specified as array, not {}", kind_name(p)));
        }
    }
    if ps.is_empty() {
        return Ok(t);
    }
    if let Value::Arr(first) = &ps[0] {
        if first.is_empty() {
            return Ok(Value::Null);
        }
    }
    let pv: Vec<&[Value]> = ps
        .iter()
        .map(|p| match p {
            Value::Arr(a) => &a[..],
            _ => unreachable!(),
        })
        .collect();
    delpaths_sorted(t, &pv, 0)
}

fn delpaths_sorted(object: Value, paths: &[&[Value]], start: usize) -> VResult {
    let mut delkeys: Vec<Value> = Vec::new();
    let mut object = object;
    let mut i = 0;
    while i < paths.len() {
        let mut j = i;
        let delkey = paths[i].len() == start + 1;
        let key = paths[i][start].clone();
        while j < paths.len() && equal(&key, &paths[j][start]) {
            j += 1;
        }
        if delkey {
            delkeys.push(key);
        } else {
            let sub = index(&object, &key)?;
            if let Value::Null = sub {
            } else {
                let nsub = delpaths_sorted(sub, &paths[i..j], start + 1)?;
                object = set(object, &key, nsub)?;
            }
        }
        i = j;
    }
    dels(object, delkeys)
}

fn dels(t: Value, keys: Vec<Value>) -> VResult {
    if keys.is_empty() {
        return Ok(t);
    }
    match t {
        Value::Null => Ok(Value::Null),
        Value::Arr(a) => {
            let mut neg = Vec::new();
            let mut nonneg = Vec::new();
            let mut ranges = Vec::new();
            for k in &keys {
                match k {
                    Value::Num(_) | Value::Lit(_) => {
                        if k.as_f64() < 0.0 {
                            neg.push(k.as_f64());
                        } else {
                            nonneg.push(k.as_f64());
                        }
                    }
                    Value::Obj(o) => match parse_slice(a.len(), o) {
                        Some(r) => ranges.push(r),
                        None => return err("Array/string slice indices must be integers".into()),
                    },
                    _ => return err(format!("Cannot delete {} element of array", kind_name(k))),
                }
            }
            let len = a.len() as i64;
            let mut out = Vec::new();
            let mut ni = 0;
            let mut pi = 0;
            for (i, e) in a.iter().enumerate() {
                let i = i as i64;
                let mut del = false;
                while ni < neg.len() {
                    let d = len + (neg[ni] as i64);
                    if i == d {
                        del = true;
                    }
                    if i < d {
                        break;
                    }
                    ni += 1;
                }
                while pi < nonneg.len() {
                    let d = nonneg[pi] as i64;
                    if i == d {
                        del = true;
                    }
                    if i < d {
                        break;
                    }
                    pi += 1;
                }
                if !del {
                    for (s, e2) in &ranges {
                        if (*s as i64) <= i && i < (*e2 as i64) {
                            del = true;
                            break;
                        }
                    }
                }
                if !del {
                    out.push(e.clone());
                }
            }
            Ok(Value::from_vec(out))
        }
        Value::Obj(mut o) => {
            for k in &keys {
                match k {
                    Value::Str(s) => {
                        Rc::make_mut(&mut o).remove(s);
                    }
                    _ => return err(format!("Cannot delete {} field of object", kind_name(k))),
                }
            }
            Ok(Value::Obj(o))
        }
        t => err(format!("Cannot delete fields from {}", kind_name(&t))),
    }
}

pub fn has(t: &Value, k: &Value) -> VResult {
    match (t, k) {
        (Value::Null, _) => Ok(Value::False),
        (Value::Obj(o), Value::Str(s)) => Ok(Value::from_bool(o.contains_key(s))),
        (Value::Arr(a), Value::Num(_) | Value::Lit(_)) => {
            let d = k.as_f64();
            if d.is_nan() {
                return Ok(Value::False);
            }
            let i = d as i64;
            Ok(Value::from_bool(i >= 0 && (i as usize) < a.len()))
        }
        _ => err(format!("Cannot check whether {} has a {} key", kind_name(t), kind_name(k))),
    }
}

pub fn keys(t: &Value, sorted: bool) -> VResult {
    match t {
        Value::Obj(o) => {
            let ks: Vec<Value> = if sorted {
                o.sorted_keys().into_iter().map(Value::Str).collect()
            } else {
                o.keys().map(|k| Value::Str(k.clone())).collect()
            };
            Ok(Value::from_vec(ks))
        }
        Value::Arr(a) => Ok(Value::from_vec((0..a.len()).map(|i| Value::Num(i as f64)).collect())),
        _ => Err(type_error(t, "has no keys")),
    }
}

fn kind_code(v: &Value) -> u8 {
    v.kind_order()
}

pub fn contains(a: &Value, b: &Value) -> bool {
    if kind_code(a) != kind_code(b) {
        return false;
    }
    match (a, b) {
        (Value::Obj(x), Value::Obj(y)) => {
            for (k, bv) in y.iter() {
                match x.get(k) {
                    Some(av) => {
                        if !contains(av, bv) {
                            return false;
                        }
                    }
                    None => return false,
                }
            }
            true
        }
        (Value::Arr(x), Value::Arr(y)) => y.iter().all(|bv| x.iter().any(|av| contains(av, bv))),
        (Value::Str(x), Value::Str(y)) => y.is_empty() || x.contains(&**y),
        _ => equal(a, b),
    }
}

pub fn length(v: &Value) -> VResult {
    match v {
        Value::Null => Ok(Value::Num(0.0)),
        Value::True | Value::False => Err(type_error(v, "has no length")),
        Value::Num(f) => Ok(Value::Num(f.abs())),
        Value::Lit(l) => {
            if l.neg {
                Ok(Value::Lit(Rc::new(number::negate_literal(l))))
            } else {
                Ok(v.clone())
            }
        }
        Value::Str(s) => Ok(Value::Num(str_len_cp(s) as f64)),
        Value::Arr(a) => Ok(Value::Num(a.len() as f64)),
        Value::Obj(o) => Ok(Value::Num(o.len() as f64)),
    }
}

pub fn tostring(v: &Value) -> Value {
    match v {
        Value::Str(_) => v.clone(),
        _ => Value::from_string(to_json(v)),
    }
}
