// Compile AST to executable nodes with static name resolution
use crate::ast::*;
use crate::value::{Map, Value};
use std::cell::{Cell, OnceCell, RefCell};
use std::collections::HashMap;
use std::rc::Rc;

#[derive(Debug)]
pub enum CPart {
    Lit(Rc<str>),
    Interp(Node),
}

#[derive(Debug)]
pub enum CPat {
    Var(usize),
    Array(Vec<CPat>),
    Object(Vec<(CPatKey, Option<CPat>)>),
}

#[derive(Debug)]
pub enum CPatKey {
    Var(usize, Rc<str>),
    Expr(Node),
}

#[derive(Debug)]
pub struct CPats {
    pub alts: Vec<CPat>,
    pub nvars: usize,
}

#[derive(Debug)]
pub enum Node {
    Identity,
    RecurseDefault,
    Index(Box<Node>, Box<Node>),
    Slice(Box<Node>, Option<Box<Node>>, Option<Box<Node>>),
    Iterate(Box<Node>),
    Const(Value),
    Str(Option<Rc<str>>, Vec<CPart>),
    Format(Rc<str>),
    Array(Option<Box<Node>>),
    Object(Vec<(Node, Node)>),
    Neg(Box<Node>),
    Pipe(Box<Node>, Box<Node>),
    Comma(Box<Node>, Box<Node>),
    Bin(BinOp, Box<Node>, Box<Node>),
    And(Box<Node>, Box<Node>),
    Or(Box<Node>, Box<Node>),
    Alt(Box<Node>, Box<Node>),
    Assign(AssignOp, Box<Node>, Box<Node>),
    If(Vec<(Node, Node)>, Option<Box<Node>>),
    Try(Box<Node>, Option<Box<Node>>),
    Reduce(Box<Node>, Rc<CPats>, Box<Node>, Box<Node>),
    Foreach(Box<Node>, Rc<CPats>, Box<Node>, Box<Node>, Option<Box<Node>>),
    CallFunc(Rc<Func>, usize, Vec<Rc<Node>>),
    CallClosure(usize),
    CallNative(usize, Vec<Rc<Node>>),
    Var(usize),
    GlobalVar(usize),
    Bind(Box<Node>, Rc<CPats>, Box<Node>),
    Label(Box<Node>),
    Break(usize),
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ParamKind {
    Closure,
    Value,
}

pub struct Func {
    pub name: String,
    pub params: Vec<ParamKind>,
    pub body: OnceCell<Node>,
    pub used: Cell<bool>,
    pub errors: RefCell<Vec<CError>>,
    pub deps: RefCell<Vec<Rc<Func>>>,
}

impl std::fmt::Debug for Func {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Func({}/{})", self.name, self.params.len())
    }
}

#[derive(Clone, Debug)]
pub struct CError {
    pub msg: String,
    pub start: usize,
    pub end: usize,
    pub file: usize, // source index
}

enum SEntry {
    Var(String),
    Closure(String),
    Func(String, usize, Rc<Func>),
    Label(String),
}

impl SEntry {
    fn is_runtime(&self) -> bool {
        !matches!(self, SEntry::Func(..))
    }
}

/// A compiled module's exported definitions
#[derive(Default)]
pub struct ModuleDefs {
    pub funcs: HashMap<(String, usize), Rc<Func>>,
    pub order: Vec<(String, usize)>,
}

pub struct NativeInfo {
    pub name: &'static str,
    pub arity: usize,
}

pub struct Compiler<'a> {
    scope: Vec<SEntry>,
    pub module: ModuleDefs, // current module's defs (top-level)
    pub aliases: HashMap<String, Rc<ModuleDefs>>, // import aliases
    pub builtins: Option<Rc<ModuleDefs>>,
    pub natives: &'a HashMap<(String, usize), usize>,
    pub globals: &'a HashMap<String, usize>,
    pub errors: Vec<CError>,
    cur_func: Option<Rc<Func>>,
    pub file: usize,
    pub top_used: Vec<Rc<Func>>,
}

impl<'a> Compiler<'a> {
    pub fn new(natives: &'a HashMap<(String, usize), usize>, globals: &'a HashMap<String, usize>, file: usize) -> Self {
        Compiler {
            scope: Vec::new(),
            module: ModuleDefs::default(),
            aliases: HashMap::new(),
            builtins: None,
            natives,
            globals,
            errors: Vec::new(),
            cur_func: None,
            file,
            top_used: Vec::new(),
        }
    }

    fn error(&mut self, msg: String, start: usize, end: usize) {
        let e = CError { msg, start, end, file: self.file };
        match &self.cur_func {
            Some(f) => f.errors.borrow_mut().push(e),
            None => self.errors.push(e),
        }
    }

    fn note_use(&mut self, f: &Rc<Func>) {
        match &self.cur_func {
            Some(cf) => {
                if !Rc::ptr_eq(cf, f) {
                    cf.deps.borrow_mut().push(f.clone());
                }
            }
            None => self.top_used.push(f.clone()),
        }
    }

    /// Collect errors from used functions (transitively)
    pub fn finish_errors(&mut self) -> Vec<CError> {
        let mut errs = std::mem::take(&mut self.errors);
        let mut stack: Vec<Rc<Func>> = self.top_used.clone();
        let mut visited: Vec<*const Func> = Vec::new();
        let mut extra = Vec::new();
        while let Some(f) = stack.pop() {
            let p = Rc::as_ptr(&f);
            if visited.contains(&p) {
                continue;
            }
            visited.push(p);
            f.used.set(true);
            extra.extend(f.errors.borrow().iter().cloned());
            for d in f.deps.borrow().iter() {
                stack.push(d.clone());
            }
        }
        extra.sort_by_key(|e| (e.file, e.start));
        errs.extend(extra);
        errs
    }

    // ---------- definitions ----------

    pub fn define_toplevel(&mut self, d: &Rc<FuncDefAst>) -> Rc<Func> {
        let f = self.make_func(d);
        let key = (d.name.clone(), d.params.len());
        self.module.funcs.insert(key.clone(), f.clone());
        self.module.order.retain(|k| *k != key);
        self.module.order.push(key);
        self.compile_func_body(&f, d);
        f
    }

    fn make_func(&self, d: &FuncDefAst) -> Rc<Func> {
        let params = d
            .params
            .iter()
            .map(|p| if p.starts_with('$') { ParamKind::Value } else { ParamKind::Closure })
            .collect();
        Rc::new(Func {
            name: d.name.clone(),
            params,
            body: OnceCell::new(),
            used: Cell::new(false),
            errors: RefCell::new(Vec::new()),
            deps: RefCell::new(Vec::new()),
        })
    }

    fn compile_func_body(&mut self, f: &Rc<Func>, d: &FuncDefAst) {
        // scope: current scope + func itself (for recursion) + params
        let saved_len = self.scope.len();
        self.scope.push(SEntry::Func(d.name.clone(), d.params.len(), f.clone()));
        for p in &d.params {
            let name = p.trim_start_matches('$').to_string();
            self.scope.push(SEntry::Closure(name));
        }
        for p in &d.params {
            if let Some(n) = p.strip_prefix('$') {
                self.scope.push(SEntry::Var(n.to_string()));
            }
        }
        let saved_func = self.cur_func.replace(f.clone());
        let body = self.compile(&d.body);
        self.cur_func = saved_func;
        self.scope.truncate(saved_len);
        let _ = f.body.set(body);
    }

    // ---------- resolution ----------

    fn lookup_var(&self, name: &str) -> Option<Node> {
        let mut depth = 0;
        for e in self.scope.iter().rev() {
            match e {
                SEntry::Var(n) if n == name => return Some(Node::Var(depth)),
                _ => {}
            }
            if e.is_runtime() {
                depth += 1;
            }
        }
        self.globals.get(name).map(|&i| Node::GlobalVar(i))
    }

    fn lookup_label(&self, name: &str) -> Option<usize> {
        let mut depth = 0;
        for e in self.scope.iter().rev() {
            if let SEntry::Label(n) = e {
                if n == name {
                    return Some(depth);
                }
            }
            if e.is_runtime() {
                depth += 1;
            }
        }
        None
    }

    fn lookup_func(&mut self, name: &str, arity: usize, args: Vec<Rc<Node>>) -> Option<Node> {
        let mut depth = 0;
        for e in self.scope.iter().rev() {
            match e {
                SEntry::Closure(n) if arity == 0 && n == name => return Some(Node::CallClosure(depth)),
                SEntry::Func(n, a, f) if *a == arity && n == name => {
                    let f = f.clone();
                    self.note_use(&f);
                    return Some(Node::CallFunc(f, depth, args));
                }
                _ => {}
            }
            if e.is_runtime() {
                depth += 1;
            }
        }
        let key = (name.to_string(), arity);
        if let Some(f) = self.module.funcs.get(&key).cloned() {
            self.note_use(&f);
            return Some(Node::CallFunc(f, usize::MAX, args));
        }
        if let Some(pos) = name.rfind("::") {
            let alias = &name[..pos];
            let fname = &name[pos + 2..];
            if let Some(m) = self.aliases.get(alias) {
                if let Some(f) = m.funcs.get(&(fname.to_string(), arity)).cloned() {
                    self.note_use(&f);
                    return Some(Node::CallFunc(f, usize::MAX, args));
                }
            }
            return None;
        }
        if let Some(b) = &self.builtins {
            if let Some(f) = b.funcs.get(&key).cloned() {
                self.note_use(&f);
                return Some(Node::CallFunc(f, usize::MAX, args));
            }
        }
        if let Some(&id) = self.natives.get(&key) {
            return Some(Node::CallNative(id, args));
        }
        None
    }

    // ---------- expressions ----------

    pub fn compile(&mut self, e: &Ast) -> Node {
        match e {
            Ast::Identity => Node::Identity,
            Ast::RecurseDefault => Node::RecurseDefault,
            Ast::Index(t, k) => {
                let kn = self.compile(k);
                let tn = self.compile(t);
                Node::Index(Box::new(tn), Box::new(kn))
            }
            Ast::Slice(t, lo, hi) => {
                let lo = lo.as_ref().map(|x| Box::new(self.compile(x)));
                let hi = hi.as_ref().map(|x| Box::new(self.compile(x)));
                let tn = self.compile(t);
                Node::Slice(Box::new(tn), lo, hi)
            }
            Ast::Iterate(t) => Node::Iterate(Box::new(self.compile(t))),
            Ast::Literal(v) => Node::Const(v.clone()),
            Ast::Str(fmt, parts) => {
                let cparts = parts
                    .iter()
                    .map(|p| match p {
                        StrPart::Lit(s) => CPart::Lit(Rc::from(s.as_str())),
                        StrPart::Interp(e) => CPart::Interp(self.compile(e)),
                    })
                    .collect();
                Node::Str(fmt.as_ref().map(|f| Rc::from(f.as_str())), cparts)
            }
            Ast::Format(f) => Node::Format(Rc::from(f.as_str())),
            Ast::Array(None) => Node::Const(Value::from_vec(vec![])),
            Ast::Array(Some(x)) => Node::Array(Some(Box::new(self.compile(x)))),
            Ast::Object(entries) => {
                let mut out = Vec::new();
                for (k, v) in entries {
                    let (kn, vn) = match k {
                        ObjKey::Expr(ke) => {
                            let kn = self.compile(ke);
                            let vn = match v {
                                Some(v) => self.compile(v),
                                None => Node::Index(Box::new(Node::Identity), Box::new(self.compile(ke))),
                            };
                            (kn, vn)
                        }
                        ObjKey::Var(name, pos) => match v {
                            Some(v) => {
                                let kn = match self.lookup_var(name) {
                                    Some(n) => n,
                                    None => {
                                        self.error(format!("${} is not defined", name), *pos, *pos + name.len() + 1);
                                        Node::Const(Value::Null)
                                    }
                                };
                                (kn, self.compile(v))
                            }
                            None => {
                                let vn = match self.lookup_var(name) {
                                    Some(n) => n,
                                    None => {
                                        self.error(format!("${} is not defined", name), *pos, *pos + name.len() + 1);
                                        Node::Const(Value::Null)
                                    }
                                };
                                (Node::Const(Value::from_str(name)), vn)
                            }
                        },
                        ObjKey::Loc(pos) => (Node::Const(Value::from_str("__loc__")), Node::Const(self.loc_value(*pos))),
                    };
                    out.push((kn, vn));
                }
                // constant object folding
                let mut all_const = true;
                let mut m = Map::new();
                for (k, v) in &out {
                    match (k, v) {
                        (Node::Const(Value::Str(ks)), Node::Const(vv)) => m.insert(ks.clone(), vv.clone()),
                        _ => {
                            all_const = false;
                            break;
                        }
                    }
                }
                if all_const {
                    return Node::Const(Value::from_map(m));
                }
                Node::Object(out)
            }
            Ast::Neg(x) => Node::Neg(Box::new(self.compile(x))),
            Ast::Pipe(a, b) => Node::Pipe(Box::new(self.compile(a)), Box::new(self.compile(b))),
            Ast::Comma(a, b) => Node::Comma(Box::new(self.compile(a)), Box::new(self.compile(b))),
            Ast::Bin(op, a, b) => Node::Bin(*op, Box::new(self.compile(a)), Box::new(self.compile(b))),
            Ast::And(a, b) => Node::And(Box::new(self.compile(a)), Box::new(self.compile(b))),
            Ast::Or(a, b) => Node::Or(Box::new(self.compile(a)), Box::new(self.compile(b))),
            Ast::Alt(a, b) => Node::Alt(Box::new(self.compile(a)), Box::new(self.compile(b))),
            Ast::Assign(op, a, b) => {
                let an = self.compile(a);
                let bn = self.compile(b);
                Node::Assign(*op, Box::new(an), Box::new(bn))
            }
            Ast::If(branches, els) => {
                let bs = branches.iter().map(|(c, b)| (self.compile(c), self.compile(b))).collect();
                let e = els.as_ref().map(|x| Box::new(self.compile(x)));
                Node::If(bs, e)
            }
            Ast::Try(b, c) => {
                let bn = self.compile(b);
                let cn = c.as_ref().map(|x| Box::new(self.compile(x)));
                Node::Try(Box::new(bn), cn)
            }
            Ast::Reduce(src, pats, init, update) => {
                let initn = self.compile(init);
                let srcn = self.compile(src);
                let saved = self.scope.len();
                let cp = self.compile_patterns(pats);
                let upd = self.compile(update);
                self.scope.truncate(saved);
                Node::Reduce(Box::new(srcn), Rc::new(cp), Box::new(initn), Box::new(upd))
            }
            Ast::Foreach(src, pats, init, update, extract) => {
                let initn = self.compile(init);
                let srcn = self.compile(src);
                let saved = self.scope.len();
                let cp = self.compile_patterns(pats);
                let upd = self.compile(update);
                let ex = extract.as_ref().map(|x| Box::new(self.compile(x)));
                self.scope.truncate(saved);
                Node::Foreach(Box::new(srcn), Rc::new(cp), Box::new(initn), Box::new(upd), ex)
            }
            Ast::FuncDef(d, rest) => {
                let f = self.make_func(d);
                self.compile_func_body(&f, d);
                self.scope.push(SEntry::Func(d.name.clone(), d.params.len(), f));
                let r = self.compile(rest);
                self.scope.pop();
                r
            }
            Ast::Call(name, args, start, end) => {
                let cargs: Vec<Rc<Node>> = Vec::new();
                // resolve first (to report errors in jq order: undefined function, then args)
                let probe = self.probe_func(name, args.len());
                if !probe {
                    self.error(format!("{}/{} is not defined", name, args.len()), *start, *end);
                    return Node::Const(Value::Null);
                }
                let mut cargs = cargs;
                for a in args {
                    cargs.push(Rc::new(self.compile(a)));
                }
                match self.lookup_func(name, args.len(), cargs) {
                    Some(n) => n,
                    None => Node::Const(Value::Null),
                }
            }
            Ast::Var(name, start, end) => match self.lookup_var(name) {
                Some(n) => n,
                None => {
                    self.error(format!("${} is not defined", name), *start, *end);
                    Node::Const(Value::Null)
                }
            },
            Ast::Bind(src, pats, body) => {
                let srcn = self.compile(src);
                let saved = self.scope.len();
                let cp = self.compile_patterns(pats);
                let bn = self.compile(body);
                self.scope.truncate(saved);
                Node::Bind(Box::new(srcn), Rc::new(cp), Box::new(bn))
            }
            Ast::Label(name, body) => {
                self.scope.push(SEntry::Label(name.clone()));
                let bn = self.compile(body);
                self.scope.pop();
                Node::Label(Box::new(bn))
            }
            Ast::Break(name, start, end) => match self.lookup_label(name) {
                Some(d) => Node::Break(d),
                None => {
                    self.error(format!("$*label-{} is not defined", name), *start, *end);
                    Node::Const(Value::Null)
                }
            },
            Ast::Loc(pos) => Node::Const(self.loc_value(*pos)),
        }
    }

    pub fn loc_value(&self, pos: usize) -> Value {
        let line = crate::LOC_LINE.with(|f| f(self.file, pos));
        let file = crate::LOC_FILE.with(|f| f(self.file));
        let mut m = Map::new();
        m.insert(Rc::from("file"), Value::from_string(file));
        m.insert(Rc::from("line"), Value::Num(line as f64));
        Value::from_map(m)
    }

    fn probe_func(&self, name: &str, arity: usize) -> bool {
        for e in self.scope.iter().rev() {
            match e {
                SEntry::Closure(n) if arity == 0 && n == name => return true,
                SEntry::Func(n, a, _) if *a == arity && n == name => return true,
                _ => {}
            }
        }
        let key = (name.to_string(), arity);
        if self.module.funcs.contains_key(&key) {
            return true;
        }
        if let Some(pos) = name.rfind("::") {
            let alias = &name[..pos];
            let fname = &name[pos + 2..];
            if let Some(m) = self.aliases.get(alias) {
                return m.funcs.contains_key(&(fname.to_string(), arity));
            }
            return false;
        }
        if let Some(b) = &self.builtins {
            if b.funcs.contains_key(&key) {
                return true;
            }
        }
        self.natives.contains_key(&key)
    }

    fn compile_patterns(&mut self, pats: &[Pattern]) -> CPats {
        // collect variable names (union, in order of first appearance)
        let mut names: Vec<String> = Vec::new();
        fn collect(p: &Pattern, names: &mut Vec<String>) {
            match p {
                Pattern::Var(n, _) => {
                    if !names.contains(n) {
                        names.push(n.clone());
                    }
                }
                Pattern::Array(ps) => {
                    for p in ps {
                        collect(p, names);
                    }
                }
                Pattern::Object(es) => {
                    for (k, p) in es {
                        if let ObjPatKey::Var(n, _) = k {
                            if !names.contains(n) {
                                names.push(n.clone());
                            }
                        }
                        if let Some(p) = p {
                            collect(p, names);
                        }
                    }
                }
            }
        }
        for p in pats {
            collect(p, &mut names);
        }
        // key expressions are compiled in the outer scope (before vars are bound)
        let alts: Vec<CPat> = pats.iter().map(|p| self.compile_pattern(p, &names)).collect();
        for n in &names {
            self.scope.push(SEntry::Var(n.clone()));
        }
        CPats { alts, nvars: names.len() }
    }

    fn compile_pattern(&mut self, p: &Pattern, names: &[String]) -> CPat {
        match p {
            Pattern::Var(n, _) => CPat::Var(names.iter().position(|x| x == n).unwrap()),
            Pattern::Array(ps) => CPat::Array(ps.iter().map(|p| self.compile_pattern(p, names)).collect()),
            Pattern::Object(es) => {
                let mut out = Vec::new();
                for (k, sub) in es {
                    let ck = match k {
                        ObjPatKey::Var(n, _) => {
                            CPatKey::Var(names.iter().position(|x| x == n).unwrap(), Rc::from(n.as_str()))
                        }
                        ObjPatKey::Expr(e) => CPatKey::Expr(self.compile(e)),
                    };
                    let cs = sub.as_ref().map(|s| self.compile_pattern(s, names));
                    out.push((ck, cs));
                }
                CPat::Object(out)
            }
        }
    }
}
