use crate::ast::{AssignOp, BinOp};
use crate::compile::{CPart, CPat, CPatKey, CPats, Node, ParamKind};
use crate::json::dump_trunc;
use crate::ops;
use crate::value::{Map, Value};
use std::rc::Rc;

pub use crate::ops::binop;

pub enum Exc {
    Err(Value),
    Break(u64),
    Halt,
}

pub type Res = Result<(), Exc>;

pub fn err_msg(s: String) -> Exc {
    Exc::Err(Value::from_string(s))
}

pub enum Entry {
    Var(Value),
    Closure(Rc<Node>, Env),
    Label(u64),
}

pub struct EnvNode {
    pub entry: Entry,
    pub parent: Env,
}

pub type Env = Option<Rc<EnvNode>>;

#[inline]
pub fn env_push(env: &Env, e: Entry) -> Env {
    Some(Rc::new(EnvNode { entry: e, parent: env.clone() }))
}

#[inline]
pub fn env_get(env: &Env, depth: usize) -> &EnvNode {
    let mut cur = env.as_ref().expect("env underflow");
    for _ in 0..depth {
        cur = cur.parent.as_ref().expect("env underflow");
    }
    cur
}

pub fn env_up(env: &Env, n: usize) -> Env {
    let mut cur = env.clone();
    for _ in 0..n {
        cur = cur.and_then(|c| c.parent.clone());
    }
    cur
}

#[derive(Clone)]
pub struct PV {
    pub cur: Value,
    pub path: Rc<Vec<Value>>,
    pub vap: Value,
}

impl PV {
    pub fn root(v: Value) -> PV {
        PV { cur: v.clone(), path: Rc::new(Vec::new()), vap: v }
    }
    pub fn with_cur(&self, v: Value) -> PV {
        PV { cur: v, path: self.path.clone(), vap: self.vap.clone() }
    }
    pub fn extend(&self, k: Value, v: Value) -> PV {
        let mut p = (*self.path).clone();
        p.push(k);
        PV { cur: v.clone(), path: Rc::new(p), vap: v }
    }
}

pub type Out<'a> = &'a mut dyn FnMut(&mut Interp, Value) -> Res;
pub type POut<'a> = &'a mut dyn FnMut(&mut Interp, PV) -> Res;

pub type NativeFn = fn(&mut Interp, &[Rc<Node>], &Env, Value, Out) -> Res;
pub type NativePathFn = fn(&mut Interp, &[Rc<Node>], &Env, PV, POut) -> Res;

pub struct NativeDef {
    pub name: &'static str,
    pub arity: usize,
    pub f: NativeFn,
    pub pf: Option<NativePathFn>,
}

pub trait InputSource {
    fn next_input(&mut self) -> Option<Result<Value, String>>;
    fn current_filename(&self) -> Value;
    fn current_line(&self) -> i64;
}

pub struct Interp {
    pub globals: Vec<Value>,
    pub natives: Vec<NativeDef>,
    next_label: u64,
    pub input: Option<Box<dyn InputSource>>,
    pub halt_code: Option<i32>,
    pub halt_msg: Option<Value>,
    pub env_value: Value,
    pub builtin_names: Vec<String>,
    pub search_list: Value,
    pub jq_origin: Value,
    pub prog_origin: Value,
    pub module_meta: std::collections::HashMap<String, Value>,
    pub stderr_buf: Vec<u8>,
}

fn path_err_elem(k: &Value, v: &Value) -> Exc {
    err_msg(format!(
        "Invalid path expression near attempt to access element {} of {}",
        dump_trunc(k, 15),
        dump_trunc(v, 30)
    ))
}

impl Interp {
    pub fn new() -> Interp {
        Interp {
            globals: Vec::new(),
            natives: Vec::new(),
            next_label: 1000,
            input: None,
            halt_code: None,
            halt_msg: None,
            env_value: Value::Null,
            builtin_names: Vec::new(),
            search_list: Value::Null,
            jq_origin: Value::Null,
            prog_origin: Value::Null,
            module_meta: Default::default(),
            stderr_buf: Vec::new(),
        }
    }

    pub fn new_label(&mut self) -> u64 {
        self.next_label += 1;
        self.next_label
    }

    // ------------------------------------------------------------------
    // Normal evaluation
    // ------------------------------------------------------------------

    pub fn eval(&mut self, node: &Node, env: &Env, input: Value, out: Out) -> Res {
        match node {
            Node::Identity => out(self, input),
            Node::RecurseDefault => self.recurse_default(input, out),
            Node::Const(v) => out(self, v.clone()),
            Node::Index(t, k) => {
                if let Node::Const(kv) = &**k {
                    if let Node::Identity = &**t {
                        return match ops::index(&input, kv) {
                            Ok(v) => out(self, v),
                            Err(e) => Err(Exc::Err(e)),
                        };
                    }
                    return self.eval(t, env, input, &mut |it, tv| match ops::index(&tv, kv) {
                        Ok(v) => out(it, v),
                        Err(e) => Err(Exc::Err(e)),
                    });
                }
                self.eval(k, env, input.clone(), &mut |it, kv| {
                    it.eval(t, env, input.clone(), &mut |it2, tv| match ops::index(&tv, &kv) {
                        Ok(v) => out(it2, v),
                        Err(e) => Err(Exc::Err(e)),
                    })
                })
            }
            Node::Slice(t, lo, hi) => self.eval_slice_key(lo, hi, env, input.clone(), &mut |it, key| {
                it.eval(t, env, input.clone(), &mut |it2, tv| match ops::index(&tv, &key) {
                    Ok(v) => out(it2, v),
                    Err(e) => Err(Exc::Err(e)),
                })
            }),
            Node::Iterate(t) => {
                if let Node::Identity = &**t {
                    return self.iterate(input, out);
                }
                self.eval(t, env, input, &mut |it, tv| it.iterate(tv, out))
            }
            Node::Str(fmt, parts) => {
                let mut acc: Vec<Rc<str>> = Vec::new();
                self.eval_str(fmt, parts, parts.len(), env, &input, &mut acc, out)
            }
            Node::Format(f) => {
                let v = crate::builtins::format(f, &input).map_err(Exc::Err)?;
                out(self, v)
            }
            Node::Array(x) => {
                let mut arr = Vec::new();
                if let Some(x) = x {
                    self.eval(x, env, input, &mut |_, v| {
                        arr.push(v);
                        Ok(())
                    })?;
                }
                out(self, Value::from_vec(arr))
            }
            Node::Object(pairs) => {
                let m = Map::with_capacity(pairs.len());
                self.eval_object(pairs, 0, env, &input, m, out)
            }
            Node::Neg(x) => self.eval(x, env, input, &mut |it, v| match ops::negate(v) {
                Ok(r) => out(it, r),
                Err(e) => Err(Exc::Err(e)),
            }),
            Node::Pipe(a, b) => self.eval(a, env, input, &mut |it, v| it.eval(b, env, v, out)),
            Node::Comma(a, b) => {
                self.eval(a, env, input.clone(), out)?;
                self.eval(b, env, input, out)
            }
            Node::Bin(op, a, b) => {
                let op = *op;
                if let Node::Const(bv) = &**b {
                    return self.eval(a, env, input, &mut |it, av| match ops::binop(op, av, bv.clone()) {
                        Ok(r) => out(it, r),
                        Err(e) => Err(Exc::Err(e)),
                    });
                }
                self.eval(b, env, input.clone(), &mut |it, bv| {
                    it.eval(a, env, input.clone(), &mut |it2, av| match ops::binop(op, av, bv.clone()) {
                        Ok(r) => out(it2, r),
                        Err(e) => Err(Exc::Err(e)),
                    })
                })
            }
            Node::And(a, b) => self.eval(a, env, input.clone(), &mut |it, av| {
                if !av.is_truthy() {
                    return out(it, Value::False);
                }
                it.eval(b, env, input.clone(), &mut |it2, bv| out(it2, Value::from_bool(bv.is_truthy())))
            }),
            Node::Or(a, b) => self.eval(a, env, input.clone(), &mut |it, av| {
                if av.is_truthy() {
                    return out(it, Value::True);
                }
                it.eval(b, env, input.clone(), &mut |it2, bv| out(it2, Value::from_bool(bv.is_truthy())))
            }),
            Node::Alt(a, b) => {
                let mut found = false;
                self.eval(a, env, input.clone(), &mut |it, v| {
                    if v.is_truthy() {
                        found = true;
                        out(it, v)
                    } else {
                        Ok(())
                    }
                })?;
                if !found {
                    self.eval(b, env, input, out)?;
                }
                Ok(())
            }
            Node::Assign(op, lhs, rhs) => self.eval_assign(*op, lhs, rhs, env, input, out),
            Node::If(branches, els) => self.eval_if(branches, 0, els, env, input, out),
            Node::Try(body, catch) => {
                let mut downstream: Option<Exc> = None;
                let r = self.eval(body, env, input, &mut |it, v| match out(it, v) {
                    Ok(()) => Ok(()),
                    Err(e) => {
                        downstream = Some(e);
                        Err(Exc::Halt)
                    }
                });
                match r {
                    Ok(()) => Ok(()),
                    Err(e) => {
                        if let Some(d) = downstream {
                            return Err(d);
                        }
                        match e {
                            Exc::Err(ev) => {
                                if is_break_error(&ev) {
                                    // errors from break inside try propagate? (not used)
                                }
                                match catch {
                                    Some(c) => self.eval(c, env, ev, out),
                                    None => Ok(()),
                                }
                            }
                            other => Err(other),
                        }
                    }
                }
            }
            Node::Reduce(src, pats, init, update) => {
                self.eval(init, env, input.clone(), &mut |it, iv| {
                    let mut state: Option<Value> = Some(iv);
                    it.eval(src, env, input.clone(), &mut |it2, sv| {
                        it2.bind_patterns(pats, sv, env, &input, &mut |it3, benv| {
                            let cur = state.take().unwrap_or(Value::Null);
                            it3.eval(update, benv, cur, &mut |_, u| {
                                state = Some(u);
                                Ok(())
                            })
                        })
                    })?;
                    out(it, state.take().unwrap_or(Value::Null))
                })
            }
            Node::Foreach(src, pats, init, update, extract) => self.eval(init, env, input.clone(), &mut |it, iv| {
                let mut state: Option<Value> = Some(iv);
                it.eval(src, env, input.clone(), &mut |it2, sv| {
                    it2.bind_patterns(pats, sv, env, &input, &mut |it3, benv| {
                        let cur = state.take().unwrap_or(Value::Null);
                        it3.eval(update, benv, cur, &mut |it4, u| {
                            state = Some(u.clone());
                            match extract {
                                Some(ex) => it4.eval(ex, benv, u, out),
                                None => out(it4, u),
                            }
                        })
                    })
                })
            }),
            Node::CallFunc(f, up, args) => {
                let base = if *up == usize::MAX { None } else { env_up(env, *up) };
                let mut fenv = base;
                for a in args.iter() {
                    fenv = env_push(&fenv, Entry::Closure(a.clone(), env.clone()));
                }
                let body = f.body.get().expect("function body not compiled");
                if f.params.iter().any(|p| *p == ParamKind::Value) {
                    let vparams: Vec<usize> =
                        f.params.iter().enumerate().filter(|(_, p)| **p == ParamKind::Value).map(|(i, _)| i).collect();
                    self.call_value_params(&vparams, 0, args, env, fenv, &input, body, out)
                } else {
                    self.eval(body, &fenv, input, out)
                }
            }
            Node::CallClosure(depth) => {
                let node = env_get(env, *depth);
                match &node.entry {
                    Entry::Closure(body, cenv) => {
                        let body = body.clone();
                        let cenv = cenv.clone();
                        self.eval(&body, &cenv, input, out)
                    }
                    _ => panic!("closure expected"),
                }
            }
            Node::CallNative(id, args) => {
                let f = self.natives[*id].f;
                f(self, args, env, input, out)
            }
            Node::Var(depth) => match &env_get(env, *depth).entry {
                Entry::Var(v) => {
                    let v = v.clone();
                    out(self, v)
                }
                _ => panic!("var expected"),
            },
            Node::GlobalVar(i) => {
                let v = self.globals[*i].clone();
                out(self, v)
            }
            Node::Bind(src, pats, body) => self.eval(src, env, input.clone(), &mut |it, sv| {
                it.bind_patterns(pats, sv, env, &input, &mut |it2, benv| it2.eval(body, benv, input.clone(), out))
            }),
            Node::Label(body) => {
                let id = self.new_label();
                let lenv = env_push(env, Entry::Label(id));
                match self.eval(body, &lenv, input, out) {
                    Err(Exc::Break(b)) if b == id => Ok(()),
                    r => r,
                }
            }
            Node::Break(depth) => match &env_get(env, *depth).entry {
                Entry::Label(id) => Err(Exc::Break(*id)),
                _ => panic!("label expected"),
            },
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn call_value_params(
        &mut self,
        vparams: &[usize],
        i: usize,
        args: &[Rc<Node>],
        caller_env: &Env,
        fenv: Env,
        input: &Value,
        body: &Node,
        out: Out,
    ) -> Res {
        if i == vparams.len() {
            return self.eval(body, &fenv, input.clone(), out);
        }
        let arg = &args[vparams[i]];
        self.eval(arg, caller_env, input.clone(), &mut |it, v| {
            let nenv = env_push(&fenv, Entry::Var(v));
            it.call_value_params(vparams, i + 1, args, caller_env, nenv, input, body, out)
        })
    }

    fn eval_if(&mut self, branches: &[(Node, Node)], i: usize, els: &Option<Box<Node>>, env: &Env, input: Value, out: Out) -> Res {
        if i == branches.len() {
            return match els {
                Some(e) => self.eval(e, env, input, out),
                None => out(self, input),
            };
        }
        let (c, b) = &branches[i];
        self.eval(c, env, input.clone(), &mut |it, cv| {
            if cv.is_truthy() {
                it.eval(b, env, input.clone(), out)
            } else {
                it.eval_if(branches, i + 1, els, env, input.clone(), out)
            }
        })
    }

    fn eval_slice_key(
        &mut self,
        lo: &Option<Box<Node>>,
        hi: &Option<Box<Node>>,
        env: &Env,
        input: Value,
        out: Out,
    ) -> Res {
        match lo {
            Some(l) => self.eval(l, env, input.clone(), &mut |it, lv| match hi {
                Some(h) => it.eval(h, env, input.clone(), &mut |it2, hv| out(it2, ops::slice_key(lv.clone(), hv))),
                None => out(it, ops::slice_key(lv, Value::Null)),
            }),
            None => match hi {
                Some(h) => self.eval(h, env, input, &mut |it, hv| out(it, ops::slice_key(Value::Null, hv))),
                None => out(self, ops::slice_key(Value::Null, Value::Null)),
            },
        }
    }

    pub fn iterate(&mut self, v: Value, out: Out) -> Res {
        match v {
            Value::Arr(a) => {
                for e in a.iter() {
                    out(self, e.clone())?;
                }
                Ok(())
            }
            Value::Obj(o) => {
                for e in o.values() {
                    out(self, e.clone())?;
                }
                Ok(())
            }
            other => Err(err_msg(format!("Cannot iterate over {} ({})", other.type_name(), dump_trunc(&other, 15)))),
        }
    }

    fn recurse_default(&mut self, v: Value, out: Out) -> Res {
        out(self, v.clone())?;
        match &v {
            Value::Arr(a) => {
                for e in a.iter() {
                    self.recurse_default(e.clone(), out)?;
                }
            }
            Value::Obj(o) => {
                for e in o.values() {
                    self.recurse_default(e.clone(), out)?;
                }
            }
            _ => {}
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn eval_str(
        &mut self,
        fmt: &Option<Rc<str>>,
        parts: &[CPart],
        n: usize,
        env: &Env,
        input: &Value,
        acc: &mut Vec<Rc<str>>,
        out: Out,
    ) -> Res {
        if n == 0 {
            let mut s = String::new();
            for p in acc.iter().rev() {
                s.push_str(p);
            }
            return out(self, Value::from_string(s));
        }
        match &parts[n - 1] {
            CPart::Lit(s) => {
                acc.push(s.clone());
                let r = self.eval_str(fmt, parts, n - 1, env, input, acc, out);
                acc.pop();
                r
            }
            CPart::Interp(e) => self.eval(e, env, input.clone(), &mut |it, v| {
                let s: Rc<str> = match fmt {
                    None => match &v {
                        Value::Str(s) => s.clone(),
                        _ => Rc::from(crate::json::to_json(&v)),
                    },
                    Some(f) => match crate::builtins::format(f, &v) {
                        Ok(Value::Str(s)) => s,
                        Ok(_) => Rc::from(""),
                        Err(e) => return Err(Exc::Err(e)),
                    },
                };
                acc.push(s);
                let r = it.eval_str(fmt, parts, n - 1, env, input, acc, out);
                acc.pop();
                r
            }),
        }
    }

    fn eval_object(&mut self, pairs: &[(Node, Node)], i: usize, env: &Env, input: &Value, m: Map, out: Out) -> Res {
        if i == pairs.len() {
            return out(self, Value::from_map(m));
        }
        let (k, v) = &pairs[i];
        self.eval(k, env, input.clone(), &mut |it, kv| {
            let ks = match &kv {
                Value::Str(s) => s.clone(),
                _ => {
                    return Err(err_msg(format!(
                        "Cannot use {} ({}) as object key",
                        kv.type_name(),
                        dump_trunc(&kv, 15)
                    )))
                }
            };
            it.eval(v, env, input.clone(), &mut |it2, vv| {
                let mut m2 = m.clone();
                m2.insert(ks.clone(), vv);
                it2.eval_object(pairs, i + 1, env, input, m2, out)
            })
        })
    }

    // ------------------------------------------------------------------
    // Destructuring
    // ------------------------------------------------------------------

    pub fn bind_patterns(
        &mut self,
        pats: &CPats,
        v: Value,
        env: &Env,
        input: &Value,
        k: &mut dyn FnMut(&mut Interp, &Env) -> Res,
    ) -> Res {
        let n = pats.alts.len();
        for (ai, alt) in pats.alts.iter().enumerate() {
            let is_last = ai + 1 == n;
            let mut vars: Vec<Value> = vec![Value::Null; pats.nvars];
            let r = self.destructure(alt, v.clone(), env, input, &mut vars, &mut |it, vars| {
                let mut benv = env.clone();
                for val in vars.iter() {
                    benv = env_push(&benv, Entry::Var(val.clone()));
                }
                k(it, &benv)
            });
            match r {
                Err(Exc::Err(e)) if !is_last => {
                    let _ = e;
                    continue;
                }
                r => return r,
            }
        }
        Ok(())
    }

    fn destructure(
        &mut self,
        pat: &CPat,
        v: Value,
        env: &Env,
        input: &Value,
        vars: &mut Vec<Value>,
        k: &mut dyn FnMut(&mut Interp, &mut Vec<Value>) -> Res,
    ) -> Res {
        match pat {
            CPat::Var(i) => {
                vars[*i] = v;
                k(self, vars)
            }
            CPat::Array(elems) => self.destructure_array(elems, 0, &v, env, input, vars, k),
            CPat::Object(entries) => self.destructure_object(entries, 0, &v, env, input, vars, k),
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn destructure_array(
        &mut self,
        elems: &[CPat],
        i: usize,
        v: &Value,
        env: &Env,
        input: &Value,
        vars: &mut Vec<Value>,
        k: &mut dyn FnMut(&mut Interp, &mut Vec<Value>) -> Res,
    ) -> Res {
        if i == elems.len() {
            return k(self, vars);
        }
        let e = ops::index(v, &Value::Num(i as f64)).map_err(Exc::Err)?;
        self.destructure(&elems[i], e, env, input, vars, &mut |it, vars2| {
            it.destructure_array(elems, i + 1, v, env, input, vars2, k)
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn destructure_object(
        &mut self,
        entries: &[(CPatKey, Option<CPat>)],
        i: usize,
        v: &Value,
        env: &Env,
        input: &Value,
        vars: &mut Vec<Value>,
        k: &mut dyn FnMut(&mut Interp, &mut Vec<Value>) -> Res,
    ) -> Res {
        if i == entries.len() {
            return k(self, vars);
        }
        let (key, sub) = &entries[i];
        match key {
            CPatKey::Var(slot, name) => {
                let e = ops::index(v, &Value::Str(name.clone())).map_err(Exc::Err)?;
                vars[*slot] = e.clone();
                match sub {
                    Some(sp) => self.destructure(sp, e, env, input, vars, &mut |it, vars2| {
                        it.destructure_object(entries, i + 1, v, env, input, vars2, k)
                    }),
                    None => self.destructure_object(entries, i + 1, v, env, input, vars, k),
                }
            }
            CPatKey::Expr(kn) => {
                // key expression evaluated against the value being destructured; vars bound so far visible
                let mut keys = Vec::new();
                let mut benv = env.clone();
                for val in vars.iter() {
                    benv = env_push(&benv, Entry::Var(val.clone()));
                }
                let _ = &benv;
                self.eval(kn, env, v.clone(), &mut |_, kv| {
                    keys.push(kv);
                    Ok(())
                })?;
                for kv in keys {
                    if !matches!(kv, Value::Str(_)) {
                        return Err(err_msg(format!(
                            "Cannot index {} with {}",
                            v.type_name(),
                            kv.type_name()
                        )));
                    }
                    let e = ops::index(v, &kv).map_err(Exc::Err)?;
                    match sub {
                        Some(sp) => self.destructure(sp, e, env, input, vars, &mut |it, vars2| {
                            it.destructure_object(entries, i + 1, v, env, input, vars2, k)
                        })?,
                        None => self.destructure_object(entries, i + 1, v, env, input, vars, k)?,
                    }
                }
                Ok(())
            }
        }
    }

    // ------------------------------------------------------------------
    // Assignment
    // ------------------------------------------------------------------

    fn eval_assign(&mut self, op: AssignOp, lhs: &Node, rhs: &Node, env: &Env, input: Value, out: Out) -> Res {
        match op {
            AssignOp::Set => self.eval(rhs, env, input.clone(), &mut |it, val| {
                let mut state = input.clone();
                it.eval_path(lhs, env, PV::root(input.clone()), &mut |_, pv| {
                    let p = check_path_result(&pv)?;
                    state = ops::setpath(std::mem::replace(&mut state, Value::Null), &p, val.clone()).map_err(Exc::Err)?;
                    Ok(())
                })?;
                out(it, state)
            }),
            AssignOp::Update => {
                let r = self.modify(lhs, env, input, &mut |it, cur, k| it.eval(rhs, env, cur, k))?;
                out(self, r)
            }
            AssignOp::Arith(bop) => self.eval(rhs, env, input.clone(), &mut |it, val| {
                let r = it.modify(lhs, env, input.clone(), &mut |it2, cur, k| match ops::binop(bop, cur, val.clone()) {
                    Ok(v) => k(it2, v),
                    Err(e) => Err(Exc::Err(e)),
                })?;
                out(it, r)
            }),
            AssignOp::Alt => self.eval(rhs, env, input.clone(), &mut |it, val| {
                let r = it.modify(lhs, env, input.clone(), &mut |it2, cur, k| {
                    if cur.is_truthy() {
                        k(it2, cur)
                    } else {
                        k(it2, val.clone())
                    }
                })?;
                out(it, r)
            }),
        }
    }

    /// _modify(paths; update): returns the updated value
    pub fn modify(
        &mut self,
        paths: &Node,
        env: &Env,
        input: Value,
        update: &mut dyn FnMut(&mut Interp, Value, Out) -> Res,
    ) -> Result<Value, Exc> {
        let mut state = input.clone();
        let mut dels: Vec<Value> = Vec::new();
        self.eval_path(paths, env, PV::root(input), &mut |it, pv| {
            let p = check_path_result(&pv)?;
            let cur = ops::getpath(&state, &p).map_err(Exc::Err)?;
            let stop = it.new_label();
            let mut first: Option<Value> = None;
            let r = update(it, cur, &mut |_, v| {
                first = Some(v);
                Err(Exc::Break(stop))
            });
            match r {
                Ok(()) => {}
                Err(Exc::Break(b)) if b == stop => {}
                Err(e) => return Err(e),
            }
            match first {
                Some(v) => {
                    state = ops::setpath(std::mem::replace(&mut state, Value::Null), &p, v).map_err(Exc::Err)?;
                }
                None => dels.push(p),
            }
            Ok(())
        })?;
        if !dels.is_empty() {
            state = ops::delpaths(state, &Value::from_vec(dels)).map_err(Exc::Err)?;
        }
        Ok(state)
    }

    // ------------------------------------------------------------------
    // Path evaluation
    // ------------------------------------------------------------------

    pub fn eval_path(&mut self, node: &Node, env: &Env, pv: PV, out: POut) -> Res {
        match node {
            Node::Identity => out(self, pv),
            Node::RecurseDefault => self.recurse_path(pv, out),
            Node::Index(t, k) => {
                let mut keys = Vec::new();
                if let Node::Const(kv) = &**k {
                    keys.push(kv.clone());
                } else {
                    self.eval(k, env, pv.cur.clone(), &mut |_, kv| {
                        keys.push(kv);
                        Ok(())
                    })?;
                }
                for kv in keys {
                    self.eval_path(t, env, pv.clone(), &mut |it, tpv| {
                        if !tpv.cur.identical(&tpv.vap) {
                            return Err(path_err_elem(&kv, &tpv.cur));
                        }
                        let v = ops::index(&tpv.cur, &kv).map_err(Exc::Err)?;
                        out(it, tpv.extend(kv.clone(), v))
                    })?;
                }
                Ok(())
            }
            Node::Slice(t, lo, hi) => {
                let mut keys = Vec::new();
                self.eval_slice_key(lo, hi, env, pv.cur.clone(), &mut |_, k| {
                    keys.push(k);
                    Ok(())
                })?;
                for kv in keys {
                    self.eval_path(t, env, pv.clone(), &mut |it, tpv| {
                        if !tpv.cur.identical(&tpv.vap) {
                            return Err(path_err_elem(&kv, &tpv.cur));
                        }
                        let v = ops::index(&tpv.cur, &kv).map_err(Exc::Err)?;
                        out(it, tpv.extend(kv.clone(), v))
                    })?;
                }
                Ok(())
            }
            Node::Iterate(t) => self.eval_path(t, env, pv, &mut |it, tpv| it.iterate_path(tpv, out)),
            Node::Pipe(a, b) => self.eval_path(a, env, pv, &mut |it, p| it.eval_path(b, env, p, out)),
            Node::Comma(a, b) => {
                self.eval_path(a, env, pv.clone(), out)?;
                self.eval_path(b, env, pv, out)
            }
            Node::If(branches, els) => self.eval_if_path(branches, 0, els, env, pv, out),
            Node::Alt(a, b) => {
                let mut found = false;
                self.eval_path(a, env, pv.clone(), &mut |it, p| {
                    if p.cur.is_truthy() {
                        found = true;
                        out(it, p)
                    } else {
                        Ok(())
                    }
                })?;
                if !found {
                    self.eval_path(b, env, pv, out)?;
                }
                Ok(())
            }
            Node::Try(body, catch) => {
                let mut downstream: Option<Exc> = None;
                let r = self.eval_path(body, env, pv.clone(), &mut |it, v| match out(it, v) {
                    Ok(()) => Ok(()),
                    Err(e) => {
                        downstream = Some(e);
                        Err(Exc::Halt)
                    }
                });
                match r {
                    Ok(()) => Ok(()),
                    Err(e) => {
                        if let Some(d) = downstream {
                            return Err(d);
                        }
                        match e {
                            Exc::Err(ev) => match catch {
                                Some(c) => self.eval_path(c, env, pv.with_cur(ev), out),
                                None => Ok(()),
                            },
                            other => Err(other),
                        }
                    }
                }
            }
            Node::Reduce(src, pats, init, update) => {
                let input = pv.cur.clone();
                self.eval_path(init, env, pv.clone(), &mut |it, ipv| {
                    let mut state: Option<Value> = Some(ipv.cur.clone());
                    let base = PV { cur: input.clone(), path: ipv.path.clone(), vap: ipv.vap.clone() };
                    it.eval_path(src, env, base, &mut |it2, spv| {
                        it2.bind_patterns(pats, spv.cur.clone(), env, &input, &mut |it3, benv| {
                            let cur = state.take().unwrap_or(Value::Null);
                            it3.eval_path(update, benv, spv.with_cur(cur), &mut |_, u| {
                                state = Some(u.cur);
                                Ok(())
                            })
                        })
                    })?;
                    out(it, ipv.with_cur(state.take().unwrap_or(Value::Null)))
                })
            }
            Node::Foreach(src, pats, init, update, extract) => {
                let input = pv.cur.clone();
                self.eval_path(init, env, pv.clone(), &mut |it, ipv| {
                    let mut state: Option<Value> = Some(ipv.cur.clone());
                    let base = PV { cur: input.clone(), path: ipv.path.clone(), vap: ipv.vap.clone() };
                    it.eval_path(src, env, base, &mut |it2, spv| {
                        it2.bind_patterns(pats, spv.cur.clone(), env, &input, &mut |it3, benv| {
                            let cur = state.take().unwrap_or(Value::Null);
                            it3.eval_path(update, benv, spv.with_cur(cur), &mut |it4, u| {
                                state = Some(u.cur.clone());
                                match extract {
                                    Some(ex) => it4.eval_path(ex, benv, u, out),
                                    None => out(it4, u),
                                }
                            })
                        })
                    })
                })
            }
            Node::CallFunc(f, up, args) => {
                let base = if *up == usize::MAX { None } else { env_up(env, *up) };
                let mut fenv = base;
                for a in args.iter() {
                    fenv = env_push(&fenv, Entry::Closure(a.clone(), env.clone()));
                }
                let body = f.body.get().expect("function body not compiled");
                if f.params.iter().any(|p| *p == ParamKind::Value) {
                    let vparams: Vec<usize> =
                        f.params.iter().enumerate().filter(|(_, p)| **p == ParamKind::Value).map(|(i, _)| i).collect();
                    self.call_value_params_path(&vparams, 0, args, env, fenv, &pv, body, out)
                } else {
                    self.eval_path(body, &fenv, pv, out)
                }
            }
            Node::CallClosure(depth) => {
                let node = env_get(env, *depth);
                match &node.entry {
                    Entry::Closure(body, cenv) => {
                        let body = body.clone();
                        let cenv = cenv.clone();
                        self.eval_path(&body, &cenv, pv, out)
                    }
                    _ => panic!("closure expected"),
                }
            }
            Node::CallNative(id, args) => {
                if let Some(pf) = self.natives[*id].pf {
                    return pf(self, args, env, pv, out);
                }
                let f = self.natives[*id].f;
                f(self, args, env, pv.cur.clone(), &mut |it, v| out(it, pv.with_cur(v)))
            }
            Node::Bind(src, pats, body) => {
                let input = pv.cur.clone();
                self.eval(src, env, input.clone(), &mut |it, sv| {
                    it.bind_patterns(pats, sv, env, &input, &mut |it2, benv| it2.eval_path(body, benv, pv.clone(), out))
                })
            }
            Node::Label(body) => {
                let id = self.new_label();
                let lenv = env_push(env, Entry::Label(id));
                match self.eval_path(body, &lenv, pv, out) {
                    Err(Exc::Break(b)) if b == id => Ok(()),
                    r => r,
                }
            }
            Node::Break(depth) => match &env_get(env, *depth).entry {
                Entry::Label(id) => Err(Exc::Break(*id)),
                _ => panic!("label expected"),
            },
            // Non-path expressions: evaluate normally, keep path state
            _ => self.eval(node, env, pv.cur.clone(), &mut |it, v| out(it, pv.with_cur(v))),
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn call_value_params_path(
        &mut self,
        vparams: &[usize],
        i: usize,
        args: &[Rc<Node>],
        caller_env: &Env,
        fenv: Env,
        pv: &PV,
        body: &Node,
        out: POut,
    ) -> Res {
        if i == vparams.len() {
            return self.eval_path(body, &fenv, pv.clone(), out);
        }
        let arg = &args[vparams[i]];
        self.eval(arg, caller_env, pv.cur.clone(), &mut |it, v| {
            let nenv = env_push(&fenv, Entry::Var(v));
            it.call_value_params_path(vparams, i + 1, args, caller_env, nenv, pv, body, out)
        })
    }

    fn eval_if_path(&mut self, branches: &[(Node, Node)], i: usize, els: &Option<Box<Node>>, env: &Env, pv: PV, out: POut) -> Res {
        if i == branches.len() {
            return match els {
                Some(e) => self.eval_path(e, env, pv, out),
                None => out(self, pv),
            };
        }
        let (c, b) = &branches[i];
        self.eval(c, env, pv.cur.clone(), &mut |it, cv| {
            if cv.is_truthy() {
                it.eval_path(b, env, pv.clone(), out)
            } else {
                it.eval_if_path(branches, i + 1, els, env, pv.clone(), out)
            }
        })
    }

    pub fn iterate_path(&mut self, tpv: PV, out: POut) -> Res {
        if !tpv.cur.identical(&tpv.vap) {
            return Err(err_msg(format!(
                "Invalid path expression near attempt to iterate through {}",
                dump_trunc(&tpv.cur, 30)
            )));
        }
        match &tpv.cur {
            Value::Arr(a) => {
                for (i, e) in a.iter().enumerate() {
                    out(self, tpv.extend(Value::Num(i as f64), e.clone()))?;
                }
                Ok(())
            }
            Value::Obj(o) => {
                for (k, e) in o.iter() {
                    out(self, tpv.extend(Value::Str(k.clone()), e.clone()))?;
                }
                Ok(())
            }
            other => Err(err_msg(format!("Cannot iterate over {} ({})", other.type_name(), dump_trunc(other, 15)))),
        }
    }

    fn recurse_path(&mut self, pv: PV, out: POut) -> Res {
        out(self, pv.clone())?;
        if !pv.cur.identical(&pv.vap) {
            return Ok(());
        }
        match &pv.cur {
            Value::Arr(a) => {
                for (i, e) in a.iter().enumerate() {
                    self.recurse_path(pv.extend(Value::Num(i as f64), e.clone()), out)?;
                }
            }
            Value::Obj(o) => {
                for (k, e) in o.iter() {
                    self.recurse_path(pv.extend(Value::Str(k.clone()), e.clone()), out)?;
                }
            }
            _ => {}
        }
        Ok(())
    }
}

pub fn check_path_result(pv: &PV) -> Result<Value, Exc> {
    if pv.cur.identical(&pv.vap) {
        Ok(Value::Arr(pv.path.clone()))
    } else {
        Err(err_msg(format!("Invalid path expression with result {}", dump_trunc(&pv.cur, 30))))
    }
}

fn is_break_error(_v: &Value) -> bool {
    false
}
