use crate::value::{compare, equal, Map, Value};
use std::cmp::Ordering;
use std::collections::HashMap;
use std::rc::Rc;

fn vres(it: &mut Interp, r: VResult, out: Out) -> Res {
    match r {
        Ok(v) => out(it, v),
        Err(e) => Err(Exc::Err(e)),
    }
}

/// Evaluate arguments as a cartesian product, last argument varying slowest.
fn cart(
    it: &mut Interp,
    args: &[Rc<Node>],
    env: &Env,
    input: &Value,
    vals: &mut Vec<Value>,
    idx: usize,
    k: &mut dyn FnMut(&mut Interp, &[Value]) -> Res,
) -> Res {
    if idx == 0 {
        return k(it, vals);
    }
    let a = args[idx - 1].clone();
    it.eval(&a, env, input.clone(), &mut |it2, v| {
        vals[idx - 1] = v;
        cart(it2, args, env, input, vals, idx - 1, k)
    })
}

fn with_args(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: &Value, k: &mut dyn FnMut(&mut Interp, &[Value]) -> Res) -> Res {
    let mut vals = vec![Value::Null; args.len()];
    cart(it, args, env, input, &mut vals, args.len(), k)
}

fn num_required(v: &Value) -> Exc {
    Exc::Err(type_error(v, "number required"))
}

// ---------------- math ----------------

macro_rules! math1 {
    ($name:ident, $f:expr) => {
        fn $name(it: &mut Interp, _a: &[Rc<Node>], _e: &Env, input: Value, out: Out) -> Res {
            if !input.is_number() {
                return Err(num_required(&input));
            }
            let x = input.as_f64();
            let f: fn(f64) -> f64 = $f;
            out(it, Value::Num(f(x)))
        }
    };
}

macro_rules! math2 {
    ($name:ident, $f:expr) => {
        fn $name(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: Value, out: Out) -> Res {
            with_args(it, args, env, &input, &mut |it2, vals| {
                if !vals[0].is_number() {
                    return Err(num_required(&vals[0]));
                }
                if !vals[1].is_number() {
                    return Err(num_required(&vals[1]));
                }
                let f: fn(f64, f64) -> f64 = $f;
                out(it2, Value::Num(f(vals[0].as_f64(), vals[1].as_f64())))
            })
        }
    };
}

