        let r = ops::has(&input, &v[0]);
        vres(it2, r, out)
    })
}
fn f_contains(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: Value, out: Out) -> Res {
    with_args(it, args, env, &input, &mut |it2, v| {
        let b = &v[0];
        if input.kind_order() == b.kind_order() {
            out(it2, Value::from_bool(ops::contains(&input, b)))
        } else {
            Err(err_msg(format!(
                "{} ({}) and {} ({}) cannot have their containment checked",
                input.type_name(),
                dump_trunc(&input, 15),
                b.type_name(),
                dump_trunc(b, 15)
            )))
        }
    })
}
fn f_path(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: Value, out: Out) -> Res {
    let a = args[0].clone();
    it.eval_path(&a, env, PV::root(input), &mut |it2, pv| {
        let p = check_path_result(&pv)?;
        out(it2, p)
    })
}
fn f_getpath(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: Value, out: Out) -> Res {
    with_args(it, args, env, &input, &mut |it2, v| {
        let r = ops::getpath(&input, &v[0]);
        vres(it2, r, out)
    })
}
fn p_getpath(it: &mut Interp, args: &[Rc<Node>], env: &Env, pv: PV, out: POut) -> Res {
    let input = pv.cur.clone();
    with_args(it, args, env, &input, &mut |it2, v| {
        let r = ops::getpath(&pv.cur, &v[0]).map_err(Exc::Err)?;
        if pv.cur.identical(&pv.vap) {
            if let Value::Arr(p) = &v[0] {
                let mut np = (*pv.path).clone();
                np.extend(p.iter().cloned());
                return out(it2, PV { cur: r.clone(), path: Rc::new(np), vap: r });
            }
            if let Value::Null = &v[0] {
