fn stable_sort_by_keys(values: &[Value], keys: &[Value]) -> Vec<(Value, Value)> {
    let mut v: Vec<(usize, &Value, &Value)> = values.iter().zip(keys.iter()).enumerate().map(|(i, (a, b))| (i, a, b)).collect();
    v.sort_by(|a, b| match compare(a.2, b.2) {
        Ordering::Equal => a.0.cmp(&b.0),
        o => o,
    });
    v.into_iter().map(|(_, a, b)| (a.clone(), b.clone())).collect()
}

fn f_sort(it: &mut Interp, _a: &[Rc<Node>], _e: &Env, input: Value, out: Out) -> Res {
    match &input {
        Value::Arr(a) => {
            let mut v: Vec<Value> = a.to_vec();
            v.sort_by(compare);
            out(it, Value::from_vec(v))
        }
        _ => Err(Exc::Err(type_error(&input, "cannot be sorted, as it is not an array"))),
    }
}
fn f_unique(it: &mut Interp, _a: &[Rc<Node>], _e: &Env, input: Value, out: Out) -> Res {
    match &input {
        Value::Arr(a) => {
            let mut v: Vec<Value> = a.to_vec();
            v.sort_by(compare);
            let mut res: Vec<Value> = Vec::new();
            for x in v {
                if let Some(last) = res.last() {
                    if equal(last, &x) {
                        continue;
                    }
                }
                res.push(x);
            }
            out(it, Value::from_vec(res))
        }
        _ => Err(Exc::Err(type_error(&input, "cannot be sorted, as it is not an array"))),
    }
}
fn type_error2(a: &Value, b: &Value, msg: &str) -> Exc {
    err_msg(format!(
        "{} ({}) and {} ({}) {}",
        a.type_name(),
        dump_trunc(a, 15),
        b.type_name(),
        dump_trunc(b, 15),
        msg
    ))
}
fn f_sort_by_impl(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: Value, out: Out) -> Res {
    with_args(it, args, env, &input, &mut |it2, v| match (&input, &v[0]) {
        (Value::Arr(a), Value::Arr(k)) if a.len() == k.len() => {
            let s = stable_sort_by_keys(a, k);
            out(it2, Value::from_vec(s.into_iter().map(|x| x.0).collect()))
        }
        _ => Err(type_error2(&input, &v[0], "cannot be sorted, as they are not both arrays")),
    })
}
fn f_group_by_impl(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: Value, out: Out) -> Res {
    with_args(it, args, env, &input, &mut |it2, v| match (&input, &v[0]) {
        (Value::Arr(a), Value::Arr(k)) if a.len() == k.len() => {
            let s = stable_sort_by_keys(a, k);
            let mut groups: Vec<Value> = Vec::new();
            let mut cur: Vec<Value> = Vec::new();
            let mut cur_key: Option<Value> = None;
            for (val, key) in s {
                match &cur_key {
                    Some(ck) if equal(ck, &key) => cur.push(val),
                    _ => {
                        if cur_key.is_some() {
                            groups.push(Value::from_vec(std::mem::take(&mut cur)));
                        }
                        cur_key = Some(key);
                        cur.push(val);
                    }
                }
            }
            if cur_key.is_some() {
                groups.push(Value::from_vec(cur));
            }
            out(it2, Value::from_vec(groups))
        }
        _ => Err(type_error2(&input, &v[0], "cannot be sorted, as they are not both arrays")),
    })
}
fn minmax_by(values: &Value, keys: &Value, is_min: bool) -> Result<Value, Exc> {
    let (a, k) = match (values, keys) {
        (Value::Arr(a), Value::Arr(k)) => (a, k),
        _ => return Err(type_error2(values, keys, "cannot be iterated over")),
    };
    if a.len() != k.len() {
        return Err(type_error2(values, keys, "have wrong length"));
    }
    if a.is_empty() {
        return Ok(Value::Null);
    }
    let mut ret = 0;
    for i in 1..a.len() {
        let c = compare(&k[i], &k[ret]);
        if (c == Ordering::Less) == is_min {
            ret = i;
        }
    }
    Ok(a[ret].clone())
}
