// ---------------- formats ----------------

fn escape_html(s: &str) -> String {
    let mut o = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '<' => o.push_str("&lt;"),
            '>' => o.push_str("&gt;"),
            '&' => o.push_str("&amp;"),
            '\'' => o.push_str("&#39;"),
            '"' => o.push_str("&quot;"),
            _ => o.push(c),
        }
    }
    o
}

const B64: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

fn base64_encode(b: &[u8]) -> String {
    let mut o = String::new();
    for chunk in b.chunks(3) {
        let n = chunk.len();
        let v = ((chunk[0] as u32) << 16) | ((if n > 1 { chunk[1] } else { 0 } as u32) << 8) | (if n > 2 { chunk[2] } else { 0 } as u32);
        o.push(B64[(v >> 18) as usize & 63] as char);
        o.push(B64[(v >> 12) as usize & 63] as char);
        if n > 1 {
            o.push(B64[(v >> 6) as usize & 63] as char);
        } else {
            o.push('=');
        }
        if n > 2 {
            o.push(B64[v as usize & 63] as char);
        } else {
            o.push('=');
        }
    }
    o
}

fn base64_decode(input: &Value, s: &str) -> VResult {
    let data = s.as_bytes();
    let mut result: Vec<u8> = Vec::new();
    let mut code: u32 = 0;
    let mut nread = 0;
    for &c in data {
        if c == b'=' {
            break;
        }
        let d = match B64.iter().position(|&x| x == c) {
            Some(d) => d as u32,
            None => return Err(type_error(input, "is not valid base64 data")),
        };
        code |= d;
        nread += 1;
        if nread == 4 {
            result.push((code >> 16) as u8);
            result.push((code >> 8) as u8);
            result.push(code as u8);
            nread = 0;
            code = 0;
        } else {
            code <<= 6;
        }
    }
    if nread == 3 {
        result.push((code >> 10) as u8);
        result.push((code >> 2) as u8);
    } else if nread == 2 {
        result.push((code >> 4) as u8);
    } else if nread == 1 {
        return Err(type_error(input, "trailing base64 byte found"));
    }
    Ok(Value::from_string(crate::json::bytes_to_string(&result)))
}

pub fn format(fmt: &str, input: &Value) -> VResult {
    match fmt {
        "text" => Ok(ops::tostring(input)),
        "json" => Ok(Value::from_string(to_json(input))),
        "html" => {
            let s = ops::tostring(input);
            Ok(Value::from_string(escape_html(s.as_str().unwrap())))
        }
        "uri" => {
            let s = ops::tostring(input);
            let mut o = String::new();
            for &b in s.as_str().unwrap().as_bytes() {
                if b.is_ascii_alphanumeric() || b == b'-' || b == b'_' || b == b'.' || b == b'~' {
                    o.push(b as char);
                } else {
                    o.push_str(&format!("%{:02X}", b));
                }
            }
            Ok(Value::from_string(o))
        }
        "urid" => {
            let sv = ops::tostring(input);
            let s = sv.as_str().unwrap().as_bytes();
            let mut o: Vec<u8> = Vec::new();
            let mut i = 0;
            while i < s.len() {
                if s[i] == b'%' {
                    let hex = |c: u8| -> Option<u8> {
                        match c {
                            b'0'..=b'9' => Some(c - b'0'),
                            b'a'..=b'f' => Some(c - b'a' + 10),
                            b'A'..=b'F' => Some(c - b'A' + 10),
                            _ => None,
                        }
                    };
                    if i + 2 < s.len() + 0 && i + 2 <= s.len() - 1 + 1 && i + 2 < s.len() + 1 {
                        if i + 2 < s.len() || i + 2 == s.len() - 0 {
                        }
                    }
                    if i + 2 >= s.len() + 1 {
                        return Err(type_error(&sv, "is not a valid uri encoding"));
                    }
                    if i + 2 > s.len() - 1 + 1 {
                        return Err(type_error(&sv, "is not a valid uri encoding"));
                    }
                    match (s.get(i + 1).and_then(|&c| hex(c)), s.get(i + 2).and_then(|&c| hex(c))) {
                        (Some(a), Some(b)) => {
                            o.push(a * 16 + b);
                            i += 3;
                        }
                        _ => return Err(type_error(&sv, "is not a valid uri encoding")),
                    }
                } else {
                    o.push(s[i]);
                    i += 1;
                }
            }
            match String::from_utf8(o) {
                Ok(st) => Ok(Value::from_string(st)),
                Err(_) => Err(type_error(&sv, "is not a valid uri encoding")),
            }
        }
        "csv" | "tsv" => {
            let is_csv = fmt == "csv";
            let a = match input {
                Value::Arr(a) => a,
                _ => {
                    return Err(type_error(
                        input,
                        if is_csv { "cannot be csv-formatted, only array" } else { "cannot be tsv-formatted, only array" },
                    ))
                }
            };
            let mut o = String::new();
            for (i, x) in a.iter().enumerate() {
                if i > 0 {
                    o.push_str(if is_csv { "," } else { "\t" });
                }
                match x {
                    Value::Null => {}
                    Value::True | Value::False => o.push_str(&to_json(x)),
                    Value::Num(f) if f.is_nan() => {}
                    Value::Num(_) | Value::Lit(_) => o.push_str(&to_json(x)),
                    Value::Str(s) => {
                        if is_csv {
                            o.push('"');
                            o.push_str(&s.replace('"', "\"\""));
                            o.push('"');
                        } else {
                            for c in s.chars() {
                                match c {
                                    '\t' => o.push_str("\\t"),
                                    '\r' => o.push_str("\\r"),
                                    '\n' => o.push_str("\\n"),
                                    '\\' => o.push_str("\\\\"),
                                    _ => o.push(c),
                                }
                            }
                        }
                    }
                    _ => return Err(type_error(x, "is not valid in a csv row")),
                }
            }
            Ok(Value::from_string(o))
        }
        "sh" => {
            let items: Vec<Value> = match input {
                Value::Arr(a) => a.to_vec(),
                other => vec![other.clone()],
            };
            let mut o = String::new();
            for (i, x) in items.iter().enumerate() {
                if i > 0 {
                    o.push(' ');
                }
                match x {
                    Value::Null | Value::True | Value::False | Value::Num(_) | Value::Lit(_) => o.push_str(&to_json(x)),
                    Value::Str(s) => {
                        o.push('\'');
                        o.push_str(&s.replace('\'', "'\\''"));
                        o.push('\'');
                    }
                    _ => return Err(type_error(x, "can not be escaped for shell")),
                }
            }
            Ok(Value::from_string(o))
        }
        "base64" => {
            let s = ops::tostring(input);
            Ok(Value::from_string(base64_encode(s.as_str().unwrap().as_bytes())))
        }
        "base64d" => {
            let s = ops::tostring(input);
            base64_decode(&s, s.as_str().unwrap())
        }
        _ => Err(Value::from_string(format!("{} is not a valid format", fmt))),
    }
}

