fn vres(it: &mut Interp, r: VResult, out: Out) -> Res {
    match r {
        Ok(v) => out(it, v),
        Err(e) => Err(Exc::Err(e)),
    }
}

/// Evaluate arguments as a cartesian product, last argument varying slowest.
fn cart(
    it: &mut Interp,
    args: &[Rc<Node>],
    env: &Env,
    input: &Value,
    vals: &mut Vec<Value>,
    idx: usize,
    k: &mut dyn FnMut(&mut Interp, &[Value]) -> Res,
) -> Res {
    if idx == 0 {
        return k(it, vals);
    }
    let a = args[idx - 1].clone();
    it.eval(&a, env, input.clone(), &mut |it2, v| {
        vals[idx - 1] = v;
        cart(it2, args, env, input, vals, idx - 1, k)
    })
}

fn with_args(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: &Value, k: &mut dyn FnMut(&mut Interp, &[Value]) -> Res) -> Res {
    let mut vals = vec![Value::Null; args.len()];
    cart(it, args, env, input, &mut vals, args.len(), k)
}

fn num_required(v: &Value) -> Exc {
    Exc::Err(type_error(v, "number required"))
}

