macro_rules! math1 {
    ($name:ident, $f:expr) => {
        fn $name(it: &mut Interp, _a: &[Rc<Node>], _e: &Env, input: Value, out: Out) -> Res {
            if !input.is_number() {
                return Err(num_required(&input));
            }
            let x = input.as_f64();
            let f: fn(f64) -> f64 = $f;
            out(it, Value::Num(f(x)))
        }
    };
}

macro_rules! math2 {
    ($name:ident, $f:expr) => {
        fn $name(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: Value, out: Out) -> Res {
            with_args(it, args, env, &input, &mut |it2, vals| {
                if !vals[0].is_number() {
                    return Err(num_required(&vals[0]));
                }
                if !vals[1].is_number() {
                    return Err(num_required(&vals[1]));
                }
                let f: fn(f64, f64) -> f64 = $f;
                out(it2, Value::Num(f(vals[0].as_f64(), vals[1].as_f64())))
            })
        }
    };
}

