fn m_fma(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: Value, out: Out) -> Res {
    with_args(it, args, env, &input, &mut |it2, vals| {
        for v in vals.iter() {
            if !v.is_number() {
                return Err(num_required(v));
            }
        }
        out(it2, Value::Num(unsafe { ffi::fma(vals[0].as_f64(), vals[1].as_f64(), vals[2].as_f64()) }))
    })
}

fn m_frexp(it: &mut Interp, _a: &[Rc<Node>], _e: &Env, input: Value, out: Out) -> Res {
    if !input.is_number() {
        return Err(num_required(&input));
    }
    let mut e: std::os::raw::c_int = 0;
    let m = unsafe { ffi::frexp(input.as_f64(), &mut e) };
    out(it, Value::from_vec(vec![Value::Num(m), Value::Num(e as f64)]))
