fn f_contains(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: Value, out: Out) -> Res {
    with_args(it, args, env, &input, &mut |it2, v| {
        let b = &v[0];
        if input.kind_order() == b.kind_order() {
            out(it2, Value::from_bool(ops::contains(&input, b)))
        } else {
            Err(err_msg(format!(
                "{} ({}) and {} ({}) cannot have their containment checked",
                input.type_name(),
                dump_trunc(&input, 15),
                b.type_name(),
                dump_trunc(b, 15)
