fn p_getpath(it: &mut Interp, args: &[Rc<Node>], env: &Env, pv: PV, out: POut) -> Res {
    let input = pv.cur.clone();
    with_args(it, args, env, &input, &mut |it2, v| {
        let r = ops::getpath(&pv.cur, &v[0]).map_err(Exc::Err)?;
        if pv.cur.identical(&pv.vap) {
            if let Value::Arr(p) = &v[0] {
                let mut np = (*pv.path).clone();
                np.extend(p.iter().cloned());
                return out(it2, PV { cur: r.clone(), path: Rc::new(np), vap: r });
            }
            if let Value::Null = &v[0] {
                return out(it2, pv.clone());
            }
        }
        out(it2, pv.with_cur(r))
    })
}
