fn f_implode(it: &mut Interp, _a: &[Rc<Node>], _e: &Env, input: Value, out: Out) -> Res {
    match &input {
        Value::Arr(a) => {
            let mut s = String::new();
            for v in a.iter() {
                if !v.is_number() {
                    return Err(Exc::Err(type_error(v, "can't be imploded, unicode codepoint needs to be numeric")));
                }
                let d = v.as_f64();
                let cp = if d.is_nan() || d < 0.0 || d > 0x10FFFF as f64 { 0xFFFD } else { d as u32 };
