fn f_bsearch(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: Value, out: Out) -> Res {
    with_args(it, args, env, &input, &mut |it2, v| match &input {
        Value::Arr(a) => {
            let t = &v[0];
            let mut lo: i64 = 0;
            let mut hi: i64 = a.len() as i64 - 1;
            while lo <= hi {
                let mid = (lo + hi) / 2;
                match compare(&a[mid as usize], t) {
                    Ordering::Equal => return out(it2, Value::Num(mid as f64)),
                    Ordering::Less => lo = mid + 1,
                    Ordering::Greater => hi = mid - 1,
                }
            }
            out(it2, Value::Num((-1 - lo) as f64))
        }
        _ => Err(Exc::Err(type_error(&input, "cannot be searched from"))),
    })
}
fn f_range(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: Value, out: Out) -> Res {
    let a0 = args[0].clone();
    let a1 = args[1].clone();
    it.eval(&a0, env, input.clone(), &mut |it2, from| {
        it2.eval(&a1, env, input.clone(), &mut |it3, upto| {
            if !from.is_number() || !upto.is_number() {
                return Err(err_msg("Range bounds must be numeric".into()));
            }
            let mut i = from.as_f64();
            let u = upto.as_f64();
            if i < u {
                if from.is_number() && matches!(from, Value::Lit(_)) {
                    out(it3, from.clone())?;
                    i += 1.0;
                }
                while i < u {
                    out(it3, Value::Num(i))?;
                    i += 1.0;
                }
            }
            Ok(())
        })
    })
}
