fn jv2tm(a: &Value) -> Option<Tm> {
    let arr = match a {
        Value::Arr(a) => a,
        _ => return None,
    };
    let mut tm = Tm::zero();
    for (i, n) in arr.iter().enumerate().take(8) {
        if !n.is_number() {
            return None;
        }
        let mut d = n.as_f64();
        if i == 0 {
            d -= 1900.0;
        }
        let v = clamp_int(d);
        match i {
            0 => tm.tm_year = v,
            1 => tm.tm_mon = v,
            2 => tm.tm_mday = v,
            3 => tm.tm_hour = v,
            4 => tm.tm_min = v,
            5 => tm.tm_sec = v,
            6 => tm.tm_wday = v,
            7 => tm.tm_yday = v,
            _ => {}
        }
    }
    Some(tm)
}

pub fn gmtime(v: &Value, local: bool) -> VResult {
    if !v.is_number() {
        return Err(err(if local { "localtime() requires numeric inputs" } else { "gmtime() requires numeric inputs" }));
    }
    let fsecs = v.as_f64();
    let secs: i64 = if fsecs.is_nan() {
        0
    } else if fsecs >= 9.2e18 {
        i64::MAX
    } else if fsecs <= -9.2e18 {
        i64::MIN
    } else {
        fsecs as i64
    };
    let mut tm = Tm::zero();
    let r = unsafe {
        if local {
            ffi::tzset();
            ffi::localtime_r(&secs, &mut tm)
        } else {
            ffi::gmtime_r(&secs, &mut tm)
        }
    };
    if r.is_null() {
        return Err(err("error converting number of seconds since epoch to datetime"));
    }
    let sec = tm.tm_sec as f64 + (fsecs - fsecs.floor());
    Ok(tm2jv(&tm, sec))
}

pub fn mktime(v: &Value) -> VResult {
    if !matches!(v, Value::Arr(_)) {
        return Err(err("mktime requires array inputs"));
    }
    let mut tm = match jv2tm(v) {
        Some(t) => t,
        None => return Err(err("mktime requires parsed datetime inputs")),
    };
    let t = unsafe { ffi::timegm(&mut tm) };
    if t == -1 {
        return Err(err("invalid gmtime representation"));
    }
    Ok(Value::Num(t as f64))
}

pub fn strftime(input: &Value, fmt: &Value, local: bool) -> VResult {
    let name = if local { "strflocaltime/1" } else { "strftime/1" };
    let a = match input {
        Value::Num(_) | Value::Lit(_) => gmtime(input, local)?,
        Value::Arr(_) => input.clone(),
        _ => return Err(Value::from_string(format!("{} requires parsed datetime inputs", name))),
    };
    let f = match fmt {
        Value::Str(s) => s.clone(),
        _ => return Err(Value::from_string(format!("{} requires a string format", name))),
    };
    let mut tm = match jv2tm(&a) {
        Some(t) => t,
        None => return Err(Value::from_string(format!("{} requires parsed datetime inputs", name))),
    };
    unsafe {
        if local {
            ffi::tzset();
            ffi::mktime(&mut tm);
        } else {
            ffi::timegm(&mut tm);
        }
    }
    let cf = match CString::new(f.as_bytes()) {
        Ok(c) => c,
        Err(_) => {
            // format with NUL: truncate at NUL like C
            let pos = f.find('\0').unwrap_or(f.len());
            CString::new(&f.as_bytes()[..pos]).unwrap()
        }
    };
    let mut size = f.len() + 100;
    loop {
        let mut buf = vec![0u8; size];
        let n = unsafe { ffi::strftime(buf.as_mut_ptr() as *mut _, size, cf.as_ptr(), &tm) };
        if n == 0 && !cf.as_bytes().is_empty() {
            if size > 1 << 20 {
                return Err(Value::from_string(format!("{}: unknown system failure", name)));
            }
            size *= 4;
            if size > (f.len() + 100) * 4 {
                return Err(Value::from_string(format!("{}: unknown system failure", name)));
            }
            continue;
        }
        buf.truncate(n);
        return Ok(Value::from_string(crate::json::bytes_to_string(&buf)));
    }
}

fn set_tm_wday(tm: &mut Tm) {
    let century = (1900 + tm.tm_year) / 100;
    let mut year = (1900 + tm.tm_year) % 100;
    if tm.tm_mon < 2 {
        year -= 1;
    }
    let mut mon = tm.tm_mon - 1;
    if mon < 1 {
        mon += 12;
    }
    let mut wday = (tm.tm_mday + (2.6 * mon as f64 - 0.2).floor() as i32 + year + (year as f64 / 4.0).floor() as i32
        + (century as f64 / 4.0).floor() as i32
        - 2 * century)
        % 7;
    if wday < 0 {
        wday += 7;
    }
    tm.tm_wday = wday;
}

fn set_tm_yday(tm: &mut Tm) {
    const D: [i32; 12] = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
    let mut mon = tm.tm_mon;
    let year = 1900 + tm.tm_year;
    let mut leap_day = 0;
    if tm.tm_mon > 1 && ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
        leap_day = 1;
    }
    if mon < 0 {
        mon = -mon;
    }
    if mon > 11 {
        mon %= 12;
    }
    tm.tm_yday = D[mon as usize] + leap_day + tm.tm_mday - 1;
}

pub fn strptime(input: &Value, fmt: &Value) -> VResult {
