const fn bit(i: u32) -> u32 {
    1 << i
}
const M_L: u32 = bit(0) | bit(1) | bit(2) | bit(3) | bit(4);
const M_M: u32 = bit(5) | bit(6) | bit(7);
const M_N: u32 = bit(8) | bit(9) | bit(10);
const M_P: u32 = bit(11) | bit(12) | bit(13) | bit(14) | bit(15) | bit(16) | bit(17);
const M_S: u32 = bit(18) | bit(19) | bit(20) | bit(21);
const M_Z: u32 = bit(22) | bit(23) | bit(24);
const M_C: u32 = bit(25) | bit(26) | bit(27) | bit(28) | bit(29);

fn in_cat(c: u32, mask: u32) -> bool {
    mask & (1 << gc_of(c)) != 0
}

fn is_word(c: u32) -> bool {
    if c < 128 {
        let b = c as u8;
        return b.is_ascii_alphanumeric() || b == b'_';
    }
