            if c < 128 {
                (b'0' as u32..=b'9' as u32).contains(&c)
            } else {
                in_cat(c, bit(8))
            }
        }
        Cls::Word => is_word(c),
        Cls::Space => is_space(c),
        Cls::Hex => matches!(char::from_u32(c), Some(ch) if ch.is_ascii_hexdigit()),
        Cls::Alpha => matches!(char::from_u32(c), Some(ch) if ch.is_alphabetic()),
        Cls::Upper => matches!(char::from_u32(c), Some(ch) if ch.is_uppercase()),
        Cls::Lower => matches!(char::from_u32(c), Some(ch) if ch.is_lowercase()),
        Cls::Alnum => matches!(char::from_u32(c), Some(ch) if ch.is_alphabetic()) || in_cat(c, bit(8)),
        Cls::Punct => {
            if c < 128 {
                (c as u8).is_ascii_punctuation()
            } else {
                in_cat(c, M_P)
            }
        }
        Cls::Print => !in_cat(c, M_C) || c == 0x20,
        Cls::Graph => !in_cat(c, M_C | M_Z),
        Cls::Cntrl => in_cat(c, bit(25)),
        Cls::Blank => c == 0x20 || c == 0x09 || in_cat(c, bit(22)),
        Cls::Ascii => c < 128,
        Cls::Cat(m) => in_cat(c, *m),
