fn simple_fold(c: u32) -> u32 {
    match char::from_u32(c) {
        Some(ch) => {
            let mut up = ch.to_uppercase();
            let u = up.next().unwrap();
            if up.next().is_some() {
                let mut lo = ch.to_lowercase();
                let l = lo.next().unwrap();
                return l as u32;
            }
            let mut lo = u.to_lowercase();
            let l = lo.next().unwrap();
            if lo.next().is_some() {
                return c;
            }
            l as u32
        }
        None => c,
    }
}

fn case_variants(c: u32) -> Vec<u32> {
    let mut v = vec![c];
    if let Some(ch) = char::from_u32(c) {
