impl CharSet {
    fn matches_raw(&self, c: u32) -> bool {
        let mut m = false;
        for it in &self.items {
            let r = match it {
                SetItem::Range(a, b) => *a <= c && c <= *b,
                SetItem::Class(cls, neg) => cls_match(cls, c) != *neg,
                SetItem::Sub(s) => s.matches_raw(c),
            };
            if r {
                m = true;
                break;
            }
        }
        if m {
            for s in &self.intersect {
                if !s.matches_raw(c) {
                    m = false;
                    break;
                }
            }
        }
        m != self.negated
    }
    fn matches(&self, c: u32, ci: bool) -> bool {
        if !ci {
