// A backtracking regex engine approximating Oniguruma (Perl_NT syntax) semantics
use crate::ops::{type_error, VResult};
use crate::unicode_tables::GC_RANGES;
use crate::value::{Map, Value};
use std::rc::Rc;

#[derive(Debug, Clone, Copy, PartialEq)]
enum Assert {
    BufStart,
    BufEnd,
    SemiEnd,
    LineStart,
    LineEnd,
    WordB,
    NotWordB,
    SearchStart,
}

#[derive(Debug, Clone)]
enum Cls {
    Digit,
    Word,
    Space,
    Hex,
    Alpha,
    Upper,
    Lower,
    Alnum,
    Punct,
    Print,
    Graph,
    Cntrl,
    Blank,
    Ascii,
    Cat(u32), // bitmask of general categories
    Any,
}

#[derive(Debug, Clone)]
enum SetItem {
    Range(u32, u32),
    Class(Cls, bool),
    Sub(CharSet),
}

#[derive(Debug, Clone)]
struct CharSet {
    negated: bool,
    items: Vec<SetItem>,
    intersect: Vec<CharSet>,
}

#[derive(Debug, Clone)]
enum Node {
    Empty,
    Char(u32, bool),
    Any(bool),
    Set(Box<CharSet>, bool),
    Assert(Assert),
    Group(Box<Node>, usize),
    Concat(Vec<Node>),
    Alt(Vec<Node>),
    Repeat(Box<Node>, u32, Option<u32>, bool),
    Backref(Vec<usize>, bool),
    NamedBackrefPending(String, bool),
    Look(Box<Node>, bool, bool),
    Atomic(Box<Node>),
}

pub struct Regex {
    node: Node,
    ncaps: usize,
    names: Vec<(String, Vec<usize>)>,
}

#[derive(Clone, Copy)]
struct Opts {
    ci: bool,
    dotall: bool,
    ext: bool,
    singleline: bool,
}

struct Parser<'a> {
    p: &'a [char],
    i: usize,
    ncaps: usize,
    names: Vec<(String, Vec<usize>)>,
    max_backref: usize,
}

type PR<T> = Result<T, String>;

fn gc_of(c: u32) -> u8 {
    // binary search
    let mut lo = 0usize;
    let mut hi = GC_RANGES.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b, cat) = GC_RANGES[mid];
        if c < a {
            hi = mid;
        } else if c > b {
            lo = mid + 1;
        } else {
            return cat;
        }
    }
    29 // Cn
}

const fn bit(i: u32) -> u32 {
    1 << i
}
const M_L: u32 = bit(0) | bit(1) | bit(2) | bit(3) | bit(4);
const M_M: u32 = bit(5) | bit(6) | bit(7);
const M_N: u32 = bit(8) | bit(9) | bit(10);
const M_P: u32 = bit(11) | bit(12) | bit(13) | bit(14) | bit(15) | bit(16) | bit(17);
const M_S: u32 = bit(18) | bit(19) | bit(20) | bit(21);
const M_Z: u32 = bit(22) | bit(23) | bit(24);
const M_C: u32 = bit(25) | bit(26) | bit(27) | bit(28) | bit(29);

fn in_cat(c: u32, mask: u32) -> bool {
    mask & (1 << gc_of(c)) != 0
}

fn is_word(c: u32) -> bool {
    if c < 128 {
        let b = c as u8;
        return b.is_ascii_alphanumeric() || b == b'_';
    }
    in_cat(c, M_L | M_M | bit(8) | bit(11))
}

fn is_space(c: u32) -> bool {
    match char::from_u32(c) {
        Some(ch) => ch.is_whitespace(),
        None => false,
    }
}

fn cls_match(cls: &Cls, c: u32) -> bool {
    match cls {
        Cls::Digit => {
            if c < 128 {
                (b'0' as u32..=b'9' as u32).contains(&c)
            } else {
                in_cat(c, bit(8))
            }
        }
        Cls::Word => is_word(c),
        Cls::Space => is_space(c),
        Cls::Hex => matches!(char::from_u32(c), Some(ch) if ch.is_ascii_hexdigit()),
        Cls::Alpha => matches!(char::from_u32(c), Some(ch) if ch.is_alphabetic()),
        Cls::Upper => matches!(char::from_u32(c), Some(ch) if ch.is_uppercase()),
        Cls::Lower => matches!(char::from_u32(c), Some(ch) if ch.is_lowercase()),
        Cls::Alnum => matches!(char::from_u32(c), Some(ch) if ch.is_alphabetic()) || in_cat(c, bit(8)),
        Cls::Punct => {
            if c < 128 {
                (c as u8).is_ascii_punctuation()
            } else {
                in_cat(c, M_P)
            }
        }
        Cls::Print => !in_cat(c, M_C) || c == 0x20,
        Cls::Graph => !in_cat(c, M_C | M_Z),
        Cls::Cntrl => in_cat(c, bit(25)),
        Cls::Blank => c == 0x20 || c == 0x09 || in_cat(c, bit(22)),
        Cls::Ascii => c < 128,
        Cls::Cat(m) => in_cat(c, *m),
        Cls::Any => true,
    }
}

fn simple_fold(c: u32) -> u32 {
    match char::from_u32(c) {
        Some(ch) => {
            let mut up = ch.to_uppercase();
            let u = up.next().unwrap();
            if up.next().is_some() {
                let mut lo = ch.to_lowercase();
                let l = lo.next().unwrap();
                return l as u32;
            }
            let mut lo = u.to_lowercase();
            let l = lo.next().unwrap();
            if lo.next().is_some() {
                return c;
            }
            l as u32
        }
        None => c,
    }
}

fn case_variants(c: u32) -> Vec<u32> {
    let mut v = vec![c];
    if let Some(ch) = char::from_u32(c) {
        for x in ch.to_lowercase() {
            v.push(x as u32);
        }
        for x in ch.to_uppercase() {
            v.push(x as u32);
        }
        v.push(simple_fold(c));
    }
    v
}

impl CharSet {
    fn matches_raw(&self, c: u32) -> bool {
        let mut m = false;
        for it in &self.items {
            let r = match it {
                SetItem::Range(a, b) => *a <= c && c <= *b,
                SetItem::Class(cls, neg) => cls_match(cls, c) != *neg,
                SetItem::Sub(s) => s.matches_raw(c),
            };
            if r {
                m = true;
                break;
            }
        }
        if m {
            for s in &self.intersect {
                if !s.matches_raw(c) {
                    m = false;
                    break;
                }
            }
        }
        m != self.negated
    }
    fn matches(&self, c: u32, ci: bool) -> bool {
        if !ci {
            return self.matches_raw(c);
        }
        // case-insensitive: check variants (negation applies after)
        let pos = CharSet { negated: false, items: self.items.clone(), intersect: self.intersect.clone() };
        let any = case_variants(c).into_iter().any(|v| pos.matches_raw(v));
        any != self.negated
    }
}

fn hexval(c: char) -> Option<u32> {
    c.to_digit(16)
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<char> {
        self.p.get(self.i).copied()
    }
    fn peek_at(&self, k: usize) -> Option<char> {
        self.p.get(self.i + k).copied()
    }
    fn eof(&self) -> bool {
        self.i >= self.p.len()
    }

    fn skip_ext(&mut self, o: &Opts) {
        if !o.ext {
            return;
        }
        loop {
            match self.peek() {
                Some(c) if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\x0c' || c == '\x0b' => self.i += 1,
                Some('#') => {
                    while let Some(c) = self.peek() {
                        self.i += 1;
                        if c == '\n' {
                            break;
                        }
                    }
                }
                _ => break,
            }
        }
    }

    fn parse_alt(&mut self, o: &mut Opts, depth: usize) -> PR<Node> {
        let mut alts = Vec::new();
        loop {
            let c = self.parse_concat(o, depth)?;
            alts.push(c);
            if self.peek() == Some('|') {
                self.i += 1;
                continue;
            }
            break;
        }
        if alts.len() == 1 {
            Ok(alts.pop().unwrap())
        } else {
            Ok(Node::Alt(alts))
        }
    }

    fn parse_concat(&mut self, o: &mut Opts, depth: usize) -> PR<Node> {
        let mut items: Vec<Node> = Vec::new();
        loop {
            self.skip_ext(o);
            let c = match self.peek() {
                None => break,
                Some(c) => c,
            };
            if c == '|' {
                break;
            }
            if c == ')' {
                if depth == 0 {
                    return Err("unmatched close parenthesis".into());
                }
                break;
            }
            if matches!(c, '*' | '+' | '?') {
                return Err("target of repeat operator is not specified".into());
            }
            if c == '{' && self.try_interval().is_some() {
                return Err("target of repeat operator is not specified".into());
            }
            // inline option group without colon changes options for rest
            if c == '(' && self.peek_at(1) == Some('?') {
                if let Some((newo, consumed)) = self.try_inline_options(o)? {
                    self.i += consumed;
                    *o = newo;
                    continue;
                }
            }
            let atom = self.parse_atom(o, depth)?;
            let atom = self.parse_quantifiers(atom, o)?;
            items.push(atom);
        }
        if items.len() == 1 {
            Ok(items.pop().unwrap())
        } else if items.is_empty() {
            Ok(Node::Empty)
        } else {
            Ok(Node::Concat(items))
        }
    }

    // returns (min, max, consumed) if an interval quantifier is at current position
    fn try_interval(&self) -> Option<(u32, Option<u32>, usize, bool)> {
        let mut j = self.i;
        if self.p.get(j) != Some(&'{') {
            return None;
        }
        j += 1;
        let st = j;
        while j < self.p.len() && self.p[j].is_ascii_digit() {
            j += 1;
        }
        if j == st {
            return None; // {,n} is literal in this syntax
        }
        let lo_s: String = self.p[st..j].iter().collect();
        let too_big = lo_s.len() > 6;
        let lo: u32 = lo_s.parse().unwrap_or(u32::MAX);
        let mut hi: Option<u32> = Some(lo);
        if self.p.get(j) == Some(&',') {
            j += 1;
            let st2 = j;
            while j < self.p.len() && self.p[j].is_ascii_digit() {
                j += 1;
            }
            if j == st2 {
                hi = None;
            } else {
                let hs: String = self.p[st2..j].iter().collect();
                hi = Some(hs.parse().unwrap_or(u32::MAX));
            }
        }
        if self.p.get(j) != Some(&'}') {
            return None;
        }
        j += 1;
        Some((lo, hi, j - self.i, too_big))
    }

    fn parse_quantifiers(&mut self, mut atom: Node, o: &Opts) -> PR<Node> {
        loop {
            self.skip_ext(o);
            let c = match self.peek() {
                Some(c) => c,
                None => break,
            };
            let (min, max) = match c {
                '*' => {
                    self.i += 1;
                    (0, None)
                }
                '+' => {
                    self.i += 1;
                    (1, None)
                }
                '?' => {
                    self.i += 1;
                    (0, Some(1))
                }
                '{' => match self.try_interval() {
                    Some((lo, hi, n, too_big)) => {
                        if too_big || lo > 100000 || hi.map(|h| h > 100000).unwrap_or(false) {
                            return Err("too big number for repeat range".into());
                        }
                        if let Some(h) = hi {
                            if h < lo {
                                return Err("upper is smaller than lower in repeat range".into());
                            }
                        }
                        self.i += n;
                        (lo, hi)
                    }
                    None => break,
                },
                _ => break,
            };
            if let Node::Assert(_) = atom {
                return Err("target of repeat operator is invalid".into());
            }
            let mut greedy = true;
            let mut possessive = false;
            if self.peek() == Some('?') {
                self.i += 1;
                greedy = false;
            } else if self.peek() == Some('+') && c != '{' {
                self.i += 1;
                possessive = true;
            }
            atom = Node::Repeat(Box::new(atom), min, max, greedy);
            if possessive {
                atom = Node::Atomic(Box::new(atom));
            }
        }
        Ok(atom)
    }

    fn try_inline_options(&self, o: &Opts) -> PR<Option<(Opts, usize)>> {
        // at "(?" ; parse [imsx]*(-[imsx]*)? followed by ')' (not ':')
        let mut j = self.i + 2;
        let mut no = *o;
        let mut neg = false;
        let mut any = false;
        while j < self.p.len() {
            let c = self.p[j];
            match c {
                'i' | 'm' | 's' | 'x' => {
                    any = true;
                    match c {
                        'i' => no.ci = !neg,
                        'm' => no.singleline = neg,
                        's' => no.dotall = !neg,
                        'x' => no.ext = !neg,
                        _ => {}
                    }
                }
                '-' => neg = true,
                ')' => {
                    if any || neg {
                        return Ok(Some((no, j - self.i + 1)));
                    }
                    return Ok(None);
                }
                _ => return Ok(None),
            }
            j += 1;
        }
        Ok(None)
    }

    fn parse_group_name(&mut self, close: char) -> PR<String> {
        let st = self.i;
        while let Some(c) = self.peek() {
            if c == close {
                break;
            }
            self.i += 1;
        }
        if self.eof() {
            return Err("invalid group name <>".into());
        }
        let name: String = self.p[st..self.i].iter().collect();
        self.i += 1;
        if name.is_empty() {
            return Err("group name is empty".into());
        }
        let first = name.chars().next().unwrap();
        if !(first.is_alphabetic() || first == '_') || !name.chars().all(|c| c.is_alphanumeric() || c == '_') {
            return Err(format!("invalid group name <{}>", name));
        }
        Ok(name)
    }

    fn parse_atom(&mut self, o: &mut Opts, depth: usize) -> PR<Node> {
        let c = self.peek().unwrap();
        match c {
            '(' => {
                self.i += 1;
                if self.peek() == Some('?') {
                    self.i += 1;
                    let c2 = match self.peek() {
                        Some(c) => c,
                        None => return Err("end pattern in group".into()),
                    };
                    match c2 {
                        ':' => {
                            self.i += 1;
                            let mut no = *o;
                            let inner = self.parse_alt(&mut no, depth + 1)?;
                            self.expect_close()?;
                            Ok(inner)
                        }
                        '=' | '!' => {
                            self.i += 1;
                            let mut no = *o;
                            let inner = self.parse_alt(&mut no, depth + 1)?;
                            self.expect_close()?;
                            Ok(Node::Look(Box::new(inner), true, c2 == '!'))
                        }
                        '>' => {
                            self.i += 1;
                            let mut no = *o;
                            let inner = self.parse_alt(&mut no, depth + 1)?;
                            self.expect_close()?;
                            Ok(Node::Atomic(Box::new(inner)))
                        }
                        '#' => {
                            while let Some(c) = self.peek() {
                                self.i += 1;
                                if c == ')' {
                                    return Ok(Node::Empty);
                                }
                            }
                            Err("end pattern in group".into())
                        }
                        '<' => {
                            let c3 = self.peek_at(1);
                            if c3 == Some('=') || c3 == Some('!') {
                                self.i += 2;
                                let mut no = *o;
                                let inner = self.parse_alt(&mut no, depth + 1)?;
                                self.expect_close()?;
                                return Ok(Node::Look(Box::new(inner), false, c3 == Some('!')));
                            }
                            self.i += 1;
                            let name = self.parse_group_name('>')?;
                            self.named_group(name, o, depth)
                        }
                        '\'' => {
                            self.i += 1;
                            let name = self.parse_group_name('\'')?;
                            self.named_group(name, o, depth)
                        }
                        'P' if self.peek_at(1) == Some('<') => {
                            self.i += 2;
                            let name = self.parse_group_name('>')?;
                            self.named_group(name, o, depth)
                        }
                        _ => {
                            // options with colon: (?i:...)
                            let mut no = *o;
                            let mut neg = false;
                            loop {
                                match self.peek() {
                                    Some('i') => no.ci = !neg,
                                    Some('m') => no.singleline = neg,
                                    Some('s') => no.dotall = !neg,
                                    Some('x') => no.ext = !neg,
                                    Some('-') => neg = true,
                                    Some(':') => {
                                        self.i += 1;
                                        let inner = self.parse_alt(&mut no, depth + 1)?;
                                        self.expect_close()?;
                                        return Ok(inner);
                                    }
                                    Some(')') => {
                                        self.i += 1;
                                        *o = no;
                                        return Ok(Node::Empty);
                                    }
                                    None => return Err("end pattern in group".into()),
                                    _ => return Err("undefined group option".into()),
                                }
                                self.i += 1;
                            }
                        }
                    }
                } else {
                    self.ncaps += 1;
                    let n = self.ncaps;
                    let mut no = *o;
                    let inner = self.parse_alt(&mut no, depth + 1)?;
                    self.expect_close()?;
                    Ok(Node::Group(Box::new(inner), n))
                }
            }
            '[' => {
                self.i += 1;
                let set = self.parse_class(o)?;
                Ok(Node::Set(Box::new(set), o.ci))
            }
            '.' => {
                self.i += 1;
                Ok(Node::Any(o.dotall))
            }
            '^' => {
                self.i += 1;
                Ok(Node::Assert(if o.singleline { Assert::BufStart } else { Assert::LineStart }))
            }
            '$' => {
                self.i += 1;
                Ok(Node::Assert(if o.singleline { Assert::SemiEnd } else { Assert::LineEnd }))
            }
            '\\' => self.parse_escape(o),
            _ => {
                self.i += 1;
                Ok(Node::Char(c as u32, o.ci))
            }
        }
    }

    fn named_group(&mut self, name: String, o: &Opts, depth: usize) -> PR<Node> {
        self.ncaps += 1;
        let n = self.ncaps;
        match self.names.iter_mut().find(|(nm, _)| *nm == name) {
            Some((_, v)) => v.push(n),
            None => self.names.push((name, vec![n])),
        }
        let mut no = *o;
        let inner = self.parse_alt(&mut no, depth + 1)?;
        self.expect_close()?;
        Ok(Node::Group(Box::new(inner), n))
    }

    fn expect_close(&mut self) -> PR<()> {
        if self.peek() == Some(')') {
            self.i += 1;
            Ok(())
        } else {
            Err("end pattern with unmatched parenthesis".into())
        }
    }

    fn parse_hex_escape(&mut self) -> PR<u32> {
        // after \x
        if self.peek() == Some('{') {
            self.i += 1;
            let st = self.i;
            while let Some(c) = self.peek() {
                if c == '}' {
                    break;
                }
                if hexval(c).is_none() {
                    return Err("invalid code point value".into());
                }
                self.i += 1;
            }
            if self.eof() {
                return Err("invalid code point value".into());
            }
            let s: String = self.p[st..self.i].iter().collect();
            self.i += 1;
            let v = u32::from_str_radix(&s, 16).map_err(|_| "too big wide-char value".to_string())?;
            if v > 0x10FFFF {
                return Err("invalid code point value".into());
            }
            return Ok(v);
        }
        let mut v = 0u32;
        let mut n = 0;
        while n < 2 {
            match self.peek().and_then(hexval) {
                Some(d) => {
                    v = v * 16 + d;
                    self.i += 1;
                    n += 1;
                }
                None => break,
            }
        }
        Ok(v)
    }

    fn parse_property(&mut self, negated: bool) -> PR<(Cls, bool)> {
        // after \p or \P
        if self.peek() != Some('{') {
            return Err("invalid character property name {}".into());
        }
        self.i += 1;
        let mut neg = negated;
        if self.peek() == Some('^') {
            self.i += 1;
            neg = !neg;
        }
        let st = self.i;
        while let Some(c) = self.peek() {
            if c == '}' {
                break;
            }
            self.i += 1;
        }
        if self.eof() {
            return Err("invalid character property name {}".into());
        }
        let name: String = self.p[st..self.i].iter().collect();
        self.i += 1;
        let key: String = name.chars().filter(|c| *c != '_' && *c != ' ' && *c != '-').collect::<String>().to_lowercase();
        let cls = match key.as_str() {
            "alpha" => Cls::Alpha,
            "digit" => Cls::Digit,
            "alnum" => Cls::Alnum,
            "upper" => Cls::Upper,
            "lower" => Cls::Lower,
            "space" => Cls::Space,
            "punct" => Cls::Punct,
            "print" => Cls::Print,
            "graph" => Cls::Graph,
            "cntrl" => Cls::Cntrl,
            "blank" => Cls::Blank,
            "word" => Cls::Word,
            "xdigit" => Cls::Hex,
            "ascii" => Cls::Ascii,
            "any" => Cls::Any,
            "l" | "letter" => Cls::Cat(M_L),
            "lu" | "uppercaseletter" => Cls::Cat(bit(0)),
            "ll" | "lowercaseletter" => Cls::Cat(bit(1)),
            "lt" | "titlecaseletter" => Cls::Cat(bit(2)),
            "lm" | "modifierletter" => Cls::Cat(bit(3)),
            "lo" | "otherletter" => Cls::Cat(bit(4)),
            "m" | "mark" => Cls::Cat(M_M),
            "mn" => Cls::Cat(bit(5)),
            "mc" => Cls::Cat(bit(6)),
            "me" => Cls::Cat(bit(7)),
            "n" | "number" => Cls::Cat(M_N),
            "nd" | "decimalnumber" => Cls::Cat(bit(8)),
            "nl" => Cls::Cat(bit(9)),
            "no" => Cls::Cat(bit(10)),
            "p" | "punctuation" => Cls::Cat(M_P),
            "pc" => Cls::Cat(bit(11)),
            "pd" => Cls::Cat(bit(12)),
            "ps" => Cls::Cat(bit(13)),
            "pe" => Cls::Cat(bit(14)),
            "pi" => Cls::Cat(bit(15)),
            "pf" => Cls::Cat(bit(16)),
            "po" => Cls::Cat(bit(17)),
            "s" | "symbol" => Cls::Cat(M_S),
            "sm" => Cls::Cat(bit(18)),
            "sc" => Cls::Cat(bit(19)),
            "sk" => Cls::Cat(bit(20)),
            "so" => Cls::Cat(bit(21)),
            "z" | "separator" => Cls::Cat(M_Z),
            "zs" => Cls::Cat(bit(22)),
            "zl" => Cls::Cat(bit(23)),
            "zp" => Cls::Cat(bit(24)),
            "c" | "other" => Cls::Cat(M_C),
            "cc" => Cls::Cat(bit(25)),
            "cf" => Cls::Cat(bit(26)),
            "cs" => Cls::Cat(bit(27)),
            "co" => Cls::Cat(bit(28)),
            "cn" => Cls::Cat(bit(29)),
            _ => return Err(format!("invalid character property name {{{}}}", name)),
        };
        Ok((cls, neg))
    }

    fn parse_escape(&mut self, o: &Opts) -> PR<Node> {
        self.i += 1; // backslash
        let c = match self.peek() {
            Some(c) => c,
            None => return Err("end pattern at escape".into()),
        };
        self.i += 1;
        let set = |cls: Cls, neg: bool| Node::Set(Box::new(CharSet { negated: false, items: vec![SetItem::Class(cls, neg)], intersect: vec![] }), false);
        Ok(match c {
            'd' => set(Cls::Digit, false),
            'D' => set(Cls::Digit, true),
            'w' => set(Cls::Word, false),
            'W' => set(Cls::Word, true),
            's' => set(Cls::Space, false),
            'S' => set(Cls::Space, true),
            'h' => set(Cls::Hex, false),
            'H' => set(Cls::Hex, true),
            'b' => Node::Assert(Assert::WordB),
            'B' => Node::Assert(Assert::NotWordB),
            'A' => Node::Assert(Assert::BufStart),
            'z' => Node::Assert(Assert::BufEnd),
            'Z' => Node::Assert(Assert::SemiEnd),
            'G' => Node::Assert(Assert::SearchStart),
            't' => Node::Char(9, o.ci),
            'n' => Node::Char(10, o.ci),
            'r' => Node::Char(13, o.ci),
            'f' => Node::Char(12, o.ci),
            'v' => Node::Char(11, o.ci),
            'a' => Node::Char(7, o.ci),
            'e' => Node::Char(27, o.ci),
            'x' => Node::Char(self.parse_hex_escape()?, o.ci),
            'p' | 'P' => {
                let (cls, neg) = self.parse_property(c == 'P')?;
                set(cls, neg)
            }
            'k' => {
                let close = match self.peek() {
                    Some('<') => '>',
                    Some('\'') => '\'',
                    _ => return Err("invalid backref number/name".into()),
                };
                self.i += 1;
                let st = self.i;
                while let Some(ch) = self.peek() {
                    if ch == close {
                        break;
                    }
                    self.i += 1;
                }
                if self.eof() {
                    return Err("invalid backref number/name".into());
                }
                let name: String = self.p[st..self.i].iter().collect();
                self.i += 1;
                if let Ok(n) = name.parse::<usize>() {
                    if n > self.max_backref {
                        self.max_backref = n;
                    }
                    Node::Backref(vec![n], o.ci)
                } else {
                    Node::NamedBackrefPending(name, o.ci)
                }
            }
            'Q' => {
                let mut items = Vec::new();
                while !self.eof() {
                    if self.peek() == Some('\\') && self.peek_at(1) == Some('E') {
                        self.i += 2;
                        break;
                    }
                    items.push(Node::Char(self.peek().unwrap() as u32, o.ci));
                    self.i += 1;
                }
                Node::Concat(items)
            }
            '0' => {
                let mut v = 0u32;
                let mut n = 0;
                while n < 2 {
                    match self.peek().and_then(|c| c.to_digit(8)) {
                        Some(d) => {
                            v = v * 8 + d;
                            self.i += 1;
                            n += 1;
                        }
                        None => break,
                    }
                }
                Node::Char(v, o.ci)
            }
            '1'..='9' => {
                let mut n = c.to_digit(10).unwrap() as usize;
                while let Some(d) = self.peek().and_then(|c| c.to_digit(10)) {
                    n = n * 10 + d as usize;
                    self.i += 1;
                }
                if n > self.max_backref {
                    self.max_backref = n;
                }
                Node::Backref(vec![n], o.ci)
            }
            'c' => {
                let ch = match self.peek() {
                    Some(ch) => ch,
                    None => return Err("end pattern at control".into()),
                };
                self.i += 1;
                Node::Char((ch as u32) & 0x1f, o.ci)
            }
            other => Node::Char(other as u32, o.ci),
        })
    }

    fn parse_class(&mut self, o: &Opts) -> PR<CharSet> {
        // after '['
        let mut set = CharSet { negated: false, items: Vec::new(), intersect: Vec::new() };
        if self.peek() == Some('^') {
            self.i += 1;
            set.negated = true;
        }
        let mut first = true;
        loop {
            let c = match self.peek() {
                None => return Err("premature end of char-class".into()),
                Some(c) => c,
            };
            if c == ']' && !first {
                self.i += 1;
                break;
            }
            if c == '&' && self.peek_at(1) == Some('&') {
                self.i += 2;
                // rest of class is intersected
                let mut rest = CharSet { negated: false, items: Vec::new(), intersect: Vec::new() };
                let rest_items = self.parse_class_until_end(o)?;
                rest.items = rest_items.items;
                rest.intersect = rest_items.intersect;
                let left = CharSet { negated: false, items: std::mem::take(&mut set.items), intersect: std::mem::take(&mut set.intersect) };
                set.items = vec![SetItem::Sub(left)];
                set.intersect = vec![rest];
                return Ok(set);
            }
            first = false;
            // single element (possibly range start)
            let lo = self.parse_class_elem(o)?;
            match lo {
                ClassElem::Item(it) => set.items.push(it),
                ClassElem::Char(a) => {
                    if self.peek() == Some('-') && self.peek_at(1).is_some() && self.peek_at(1) != Some(']') {
                        let save = self.i;
                        self.i += 1;
                        let hi = self.parse_class_elem(o)?;
                        match hi {
                            ClassElem::Char(b) => {
                                if b < a {
                                    return Err("empty range in char class".into());
                                }
                                set.items.push(SetItem::Range(a, b));
                            }
                            ClassElem::Item(it) => {
                                // treat '-' literally
                                let _ = save;
                                set.items.push(SetItem::Range(a, a));
                                set.items.push(SetItem::Range('-' as u32, '-' as u32));
                                set.items.push(it);
                            }
                        }
                    } else {
                        set.items.push(SetItem::Range(a, a));
                    }
                }
            }
        }
        Ok(set)
    }

    fn parse_class_until_end(&mut self, o: &Opts) -> PR<CharSet> {
        let mut set = CharSet { negated: false, items: Vec::new(), intersect: Vec::new() };
        loop {
            let c = match self.peek() {
                None => return Err("premature end of char-class".into()),
                Some(c) => c,
            };
            if c == ']' {
                self.i += 1;
                return Ok(set);
            }
            if c == '&' && self.peek_at(1) == Some('&') {
                self.i += 2;
                let rest = self.parse_class_until_end(o)?;
                let left = CharSet { negated: false, items: std::mem::take(&mut set.items), intersect: vec![] };
                set.items = vec![SetItem::Sub(left)];
                set.intersect = vec![rest];
                return Ok(set);
            }
            match self.parse_class_elem(o)? {
                ClassElem::Item(it) => set.items.push(it),
                ClassElem::Char(a) => {
                    if self.peek() == Some('-') && self.peek_at(1).is_some() && self.peek_at(1) != Some(']') {
                        self.i += 1;
                        match self.parse_class_elem(o)? {
                            ClassElem::Char(b) => {
                                if b < a {
                                    return Err("empty range in char class".into());
                                }
                                set.items.push(SetItem::Range(a, b));
                            }
                            ClassElem::Item(it) => {
                                set.items.push(SetItem::Range(a, a));
                                set.items.push(SetItem::Range('-' as u32, '-' as u32));
                                set.items.push(it);
                            }
                        }
                    } else {
                        set.items.push(SetItem::Range(a, a));
                    }
                }
            }
        }
    }

    fn parse_class_elem(&mut self, o: &Opts) -> PR<ClassElem> {
        let c = match self.peek() {
            None => return Err("premature end of char-class".into()),
            Some(c) => c,
        };
        if c == '[' {
            if self.peek_at(1) == Some(':') {
                // POSIX bracket
                let st = self.i + 2;
                let mut j = st;
                while j < self.p.len() && self.p[j] != ':' && self.p[j] != ']' {
                    j += 1;
                }
                if j + 1 < self.p.len() && self.p[j] == ':' && self.p[j + 1] == ']' {
                    let mut name: String = self.p[st..j].iter().collect();
                    let mut neg = false;
                    if let Some(n) = name.strip_prefix('^') {
                        name = n.to_string();
                        neg = true;
                    }
                    let cls = match name.as_str() {
                        "alpha" => Cls::Alpha,
                        "digit" => Cls::Digit,
                        "alnum" => Cls::Alnum,
                        "upper" => Cls::Upper,
                        "lower" => Cls::Lower,
                        "space" => Cls::Space,
                        "punct" => Cls::Punct,
                        "print" => Cls::Print,
                        "graph" => Cls::Graph,
                        "cntrl" => Cls::Cntrl,
                        "blank" => Cls::Blank,
                        "word" => Cls::Word,
                        "xdigit" => Cls::Hex,
                        "ascii" => Cls::Ascii,
                        _ => return Err("invalid POSIX bracket type".into()),
                    };
                    self.i = j + 2;
                    return Ok(ClassElem::Item(SetItem::Class(cls, neg)));
                }
            }
            // nested class
            self.i += 1;
            let sub = self.parse_class(o)?;
            return Ok(ClassElem::Item(SetItem::Sub(sub)));
        }
        if c == '\\' {
            self.i += 1;
            let e = match self.peek() {
                None => return Err("premature end of char-class".into()),
                Some(e) => e,
            };
            self.i += 1;
            let it = |cls: Cls, neg: bool| ClassElem::Item(SetItem::Class(cls, neg));
            return Ok(match e {
                'd' => it(Cls::Digit, false),
                'D' => it(Cls::Digit, true),
                'w' => it(Cls::Word, false),
                'W' => it(Cls::Word, true),
                's' => it(Cls::Space, false),
                'S' => it(Cls::Space, true),
                'h' => it(Cls::Hex, false),
                'H' => it(Cls::Hex, true),
                'p' | 'P' => {
                    let (cls, neg) = self.parse_property(e == 'P')?;
                    it(cls, neg)
                }
                't' => ClassElem::Char(9),
                'n' => ClassElem::Char(10),
                'r' => ClassElem::Char(13),
                'f' => ClassElem::Char(12),
                'v' => ClassElem::Char(11),
                'a' => ClassElem::Char(7),
                'e' => ClassElem::Char(27),
                'b' => ClassElem::Char(8),
                'x' => ClassElem::Char(self.parse_hex_escape()?),
                '0'..='7' => {
                    let mut v = e.to_digit(8).unwrap();
                    let mut n = 1;
                    while n < 3 {
                        match self.peek().and_then(|c| c.to_digit(8)) {
                            Some(d) => {
                                v = v * 8 + d;
                                self.i += 1;
                                n += 1;
                            }
                            None => break,
                        }
                    }
                    ClassElem::Char(v)
                }
                other => ClassElem::Char(other as u32),
            });
        }
        self.i += 1;
        Ok(ClassElem::Char(c as u32))
    }
}

enum ClassElem {
    Char(u32),
    Item(SetItem),
}

fn resolve_named(node: &mut Node, names: &[(String, Vec<usize>)]) -> Result<(), String> {
    match node {
        Node::NamedBackrefPending(name, ci) => match names.iter().find(|(n, _)| n == name) {
            Some((_, v)) => {
                *node = Node::Backref(v.clone(), *ci);
                Ok(())
            }
            None => Err(format!("undefined name <{}> reference", name)),
        },
        Node::Group(n, _) | Node::Repeat(n, _, _, _) | Node::Look(n, _, _) | Node::Atomic(n) => resolve_named(n, names),
        Node::Concat(v) | Node::Alt(v) => {
            for n in v {
                resolve_named(n, names)?;
            }
            Ok(())
        }
        _ => Ok(()),
    }
}

impl Regex {
    pub fn new(pattern: &str, ci: bool, ext: bool, dotall: bool) -> Result<Regex, String> {
        let chars: Vec<char> = pattern.chars().collect();
        let mut p = Parser { p: &chars, i: 0, ncaps: 0, names: Vec::new(), max_backref: 0 };
        let mut o = Opts { ci, dotall, ext, singleline: true };
        let mut node = p.parse_alt(&mut o, 0)?;
        if p.i < chars.len() {
            return Err("unmatched close parenthesis".into());
        }
        if p.max_backref > p.ncaps {
            return Err("invalid backref number/name".into());
        }
        resolve_named(&mut node, &p.names)?;
        Ok(Regex { node, ncaps: p.ncaps, names: p.names })
    }
}

// ---------------- matcher ----------------

struct St<'a> {
    s: &'a [u8],
    caps: Vec<(isize, isize)>,
    search_start: usize,
    steps: u64,
}

#[inline]
fn decode_at(s: &[u8], i: usize) -> (u32, usize) {
    let (cp, len) = crate::json::utf8_next(s, i);
    if cp < 0 {
        (s[i] as u32, 1)
    } else {
        (cp as u32, len)
    }
}

fn prev_char(s: &[u8], i: usize) -> Option<u32> {
    if i == 0 {
        return None;
    }
    let mut j = i - 1;
    while j > 0 && (s[j] & 0xC0) == 0x80 && i - j < 4 {
        j -= 1;
    }
    let (c, l) = decode_at(s, j);
    if j + l == i {
        Some(c)
    } else {
        Some(s[i - 1] as u32)
    }
}

fn eq_ci(a: u32, b: u32, ci: bool) -> bool {
    if a == b {
        return true;
    }
    if !ci {
        return false;
    }
    simple_fold(a) == simple_fold(b)
}

impl Regex {
    fn m(&self, node: &Node, pos: usize, st: &mut St, k: &mut dyn FnMut(&mut St, usize) -> bool) -> bool {
        st.steps += 1;
        match node {
            Node::Empty => k(st, pos),
            Node::Char(c, ci) => {
                if pos >= st.s.len() {
                    return false;
                }
                let (d, l) = decode_at(st.s, pos);
                if eq_ci(*c, d, *ci) {
                    k(st, pos + l)
                } else {
                    false
                }
            }
            Node::Any(dotall) => {
                if pos >= st.s.len() {
                    return false;
                }
                let (d, l) = decode_at(st.s, pos);
                if d == 10 && !*dotall {
                    return false;
                }
                k(st, pos + l)
            }
            Node::Set(set, ci) => {
                if pos >= st.s.len() {
                    return false;
                }
                let (d, l) = decode_at(st.s, pos);
                if set.matches(d, *ci) {
                    k(st, pos + l)
                } else {
                    false
                }
            }
            Node::Assert(a) => {
                let s = st.s;
                let ok = match a {
                    Assert::BufStart => pos == 0,
                    Assert::BufEnd => pos == s.len(),
                    Assert::SemiEnd => pos == s.len() || (pos + 1 == s.len() && s[pos] == b'\n'),
                    Assert::LineStart => pos == 0 || s[pos - 1] == b'\n',
                    Assert::LineEnd => pos == s.len() || s[pos] == b'\n',
                    Assert::WordB | Assert::NotWordB => {
                        let a1 = prev_char(s, pos).map(is_word).unwrap_or(false);
                        let b1 = if pos < s.len() { is_word(decode_at(s, pos).0) } else { false };
                        (a1 != b1) == (*a == Assert::WordB)
                    }
                    Assert::SearchStart => pos == st.search_start,
                };
                if ok {
                    k(st, pos)
                } else {
                    false
                }
            }
            Node::Group(inner, n) => {
                let n = *n;
                self.m(inner, pos, st, &mut |st2, p| {
                    let save = st2.caps[n];
                    st2.caps[n] = (pos as isize, p as isize);
                    if k(st2, p) {
                        true
                    } else {
                        st2.caps[n] = save;
                        false
                    }
                })
            }
            Node::Concat(items) => self.m_seq(items, 0, pos, st, k),
            Node::Alt(alts) => {
                for a in alts {
                    if self.m(a, pos, st, k) {
                        return true;
                    }
                }
                false
            }
            Node::Repeat(inner, min, max, greedy) => self.m_rep(inner, *min, *max, *greedy, 0, pos, usize::MAX, st, k),
            Node::Backref(groups, ci) => {
                for &g in groups.iter().rev() {
                    if g >= st.caps.len() {
                        continue;
                    }
                    let (a, b) = st.caps[g];
                    if a < 0 {
                        continue;
                    }
                    let sub: Vec<u8> = st.s[a as usize..b as usize].to_vec();
                    // compare char by char
                    let mut i = 0;
                    let mut p = pos;
                    let mut ok = true;
                    while i < sub.len() {
                        if p >= st.s.len() {
                            ok = false;
                            break;
                        }
                        let (c1, l1) = decode_at(&sub, i);
                        let (c2, l2) = decode_at(st.s, p);
                        if !eq_ci(c1, c2, *ci) {
                            ok = false;
                            break;
                        }
                        i += l1;
                        p += l2;
                    }
                    if ok {
                        return k(st, p);
                    }
                    return false;
                }
                false
            }
            Node::NamedBackrefPending(..) => false,
            Node::Look(inner, ahead, negate) => {
                let snapshot = st.caps.clone();
                let found = if *ahead {
                    self.m(inner, pos, st, &mut |_, _| true)
                } else {
                    let mut f = false;
                    let mut s0 = pos as isize;
                    while s0 >= 0 {
                        let su = s0 as usize;
                        if su == 0 || su == st.s.len() || (st.s[su] & 0xC0) != 0x80 {
                            if self.m(inner, su, st, &mut |_, p| p == pos) {
                                f = true;
                                break;
                            }
                        }
                        s0 -= 1;
                    }
                    f
                };
                if *negate {
                    st.caps = snapshot;
                    if found {
                        false
                    } else {
                        k(st, pos)
                    }
                } else if found {
                    if k(st, pos) {
                        true
                    } else {
                        st.caps = snapshot;
                        false
                    }
                } else {
                    st.caps = snapshot;
                    false
                }
            }
            Node::Atomic(inner) => {
                let snapshot = st.caps.clone();
                let mut endp: Option<usize> = None;
                if self.m(inner, pos, st, &mut |_, p| {
                    endp = Some(p);
                    true
                }) {
                    let p = endp.unwrap();
                    if k(st, p) {
                        return true;
                    }
                }
                st.caps = snapshot;
                false
            }
        }
    }

    fn m_seq(&self, items: &[Node], i: usize, pos: usize, st: &mut St, k: &mut dyn FnMut(&mut St, usize) -> bool) -> bool {
        if i == items.len() {
            return k(st, pos);
        }
        self.m(&items[i], pos, st, &mut |st2, p| self.m_seq(items, i + 1, p, st2, k))
    }

    #[allow(clippy::too_many_arguments)]
    fn m_rep(
        &self,
        inner: &Node,
        min: u32,
        max: Option<u32>,
        greedy: bool,
        count: u32,
        pos: usize,
        last: usize,
        st: &mut St,
        k: &mut dyn FnMut(&mut St, usize) -> bool,
    ) -> bool {
        if count < min {
            return self.m(inner, pos, st, &mut |st2, p| self.m_rep(inner, min, max, greedy, count + 1, p, pos, st2, k));
        }
        let can_more = max.map(|m| count < m).unwrap_or(true) && !(count > 0 && last == pos && count >= min);
        if greedy {
            if can_more
                && self.m(inner, pos, st, &mut |st2, p| {
                    if p == pos {
                        return false;
                    }
                    self.m_rep(inner, min, max, greedy, count + 1, p, pos, st2, k)
                })
            {
                return true;
            }
            k(st, pos)
        } else {
            if k(st, pos) {
                return true;
            }
            can_more
                && self.m(inner, pos, st, &mut |st2, p| {
                    if p == pos {
                        return false;
                    }
                    self.m_rep(inner, min, max, greedy, count + 1, p, pos, st2, k)
                })
        }
    }

    /// Search from byte offset `start`. Returns capture vector on success.
    fn search(&self, s: &[u8], start: usize, longest: bool, not_empty: bool) -> Option<Vec<(isize, isize)>> {
        let mut st = St { s, caps: vec![(-1, -1); self.ncaps + 1], search_start: start, steps: 0 };
        let mut pos = start;
        let mut best: Option<Vec<(isize, isize)>> = None;
        loop {
            if pos > s.len() {
                break;
            }
            for c in st.caps.iter_mut() {
                *c = (-1, -1);
            }
            let mut result: Option<Vec<(isize, isize)>> = None;
            let p0 = pos;
            let ok = self.m(&self.node, pos, &mut st, &mut |st2, p| {
                if not_empty && p == p0 {
                    return false;
                }
                let mut caps = st2.caps.clone();
                caps[0] = (p0 as isize, p as isize);
                if longest {
                    let better = match &result {
                        None => true,
                        Some(r) => (p as isize - p0 as isize) > (r[0].1 - r[0].0),
                    };
                    if better {
                        result = Some(caps);
                    }
                    false
                } else {
                    result = Some(caps);
                    true
                }
            });
            let _ = ok;
            if let Some(r) = result {
                if !longest {
                    return Some(r);
                }
                let better = match &best {
                    None => true,
                    Some(b) => (r[0].1 - r[0].0) > (b[0].1 - b[0].0),
                };
                if better {
                    best = Some(r);
                }
            }
            if pos >= s.len() {
                break;
            }
            pos += decode_at(s, pos).1;
        }
        best
    }
}

fn decode_length(b: u8) -> usize {
    if b & 0x80 == 0 {
        1
    } else if b & 0xE0 == 0xC0 {
        2
    } else if b & 0xF0 == 0xE0 {
        3
    } else {
        4
    }
}

fn cp_offset(s: &[u8], byte: usize) -> usize {
    let mut fr = 0;
    let mut idx = 0;
    while fr < byte {
        fr += decode_length(s[fr]);
        idx += 1;
    }
    idx
}

fn offset_len(s: &[u8], beg: usize, end: usize) -> (usize, usize) {
    let mut idx = 0;
    let mut len = 0;
    let mut fr = 0;
    while fr < end {
        if fr == beg {
            idx = len;
            len = 0;
        }
        fr += decode_length(s[fr]);
        len += 1;
    }
    (idx, len)
}

fn substr(s: &[u8], a: usize, b: usize) -> Value {
    Value::from_string(crate::json::bytes_to_string(&s[a..b.min(s.len())]))
}

fn kstr(s: &str) -> Rc<str> {
    Rc::from(s)
}

pub fn match_impl(input: &Value, re: &Value, mods: &Value, test: bool) -> VResult {
    let s = match input {
        Value::Str(s) => s.clone(),
        _ => return Err(type_error(input, "cannot be matched, as it is not a string")),
    };
    let pat = match re {
        Value::Str(p) => p.clone(),
        _ => return Err(type_error(re, "is not a string")),
    };
    let mut global = false;
    let mut ci = false;
    let mut ext = false;
    let mut not_empty = false;
    let mut longest = false;
    let mut dotall = false;
    match mods {
        Value::Null => {}
        Value::Str(m) => {
            for c in m.chars() {
                match c {
                    'g' => global = true,
                    'i' => ci = true,
                    'x' => ext = true,
                    'n' => not_empty = true,
                    's' => {}
                    'p' => dotall = true,
                    'l' => longest = true,
                    _ => return Err(Value::from_string(format!("{} is not a valid modifier string", m))),
                }
            }
        }
        _ => return Err(type_error(mods, "is not a string")),
    }
    let rx = match Regex::new(&pat, ci, ext, dotall) {
        Ok(r) => r,
        Err(e) => return Err(Value::from_string(format!("Regex failure: {}", e))),
    };
    let b = s.as_bytes();
    if test {
        return Ok(Value::from_bool(rx.search(b, 0, longest, not_empty).is_some()));
    }
    let mut results = Vec::new();
    let mut start = 0usize;
    // group names
    let mut gnames: Vec<Option<Rc<str>>> = vec![None; rx.ncaps + 1];
    for (n, groups) in &rx.names {
        for &g in groups {
            gnames[g] = Some(kstr(n));
        }
    }
    while start <= b.len() {
        let caps = match rx.search(b, start, longest, not_empty) {
            Some(c) => c,
            None => break,
        };
        let (mb, me) = (caps[0].0 as usize, caps[0].1 as usize);
        let mut m = Map::new();
        if mb == me {
            m.insert(kstr("offset"), Value::Num(cp_offset(b, mb) as f64));
            m.insert(kstr("length"), Value::Num(0.0));
            m.insert(kstr("string"), Value::from_str(""));
        } else {
            let (idx, len) = offset_len(b, mb, me);
            m.insert(kstr("offset"), Value::Num(idx as f64));
            m.insert(kstr("length"), Value::Num(len as f64));
            m.insert(kstr("string"), substr(b, mb, me));
        }
        let mut capv = Vec::new();
        for g in 1..=rx.ncaps {
            let (cb, ce) = caps[g];
            let mut c = Map::new();
            if cb < 0 {
                c.insert(kstr("offset"), Value::Num(-1.0));
                c.insert(kstr("string"), Value::Null);
                c.insert(kstr("length"), Value::Num(0.0));
            } else if cb == ce {
                c.insert(kstr("offset"), Value::Num(cp_offset(b, cb as usize) as f64));
                c.insert(kstr("string"), Value::from_str(""));
                c.insert(kstr("length"), Value::Num(0.0));
            } else {
                let (idx, len) = offset_len(b, cb as usize, ce as usize);
                c.insert(kstr("offset"), Value::Num(idx as f64));
                c.insert(kstr("length"), Value::Num(len as f64));
                c.insert(kstr("string"), substr(b, cb as usize, ce as usize));
            }
            c.insert(
                kstr("name"),
                match &gnames[g] {
                    Some(n) => Value::Str(n.clone()),
                    None => Value::Null,
                },
            );
            capv.push(Value::from_map(c));
        }
        m.insert(kstr("captures"), Value::from_vec(capv));
        results.push(Value::from_map(m));
        if !global {
            break;
        }
        if me == mb {
            start = me + 1;
        } else {
            start = me;
        }
    }
    Ok(Value::from_vec(results))
}
