// Module loading and program compilation
use crate::ast::{Import, Program};
use crate::compile::{CError, Compiler, ModuleDefs, Node};
use crate::interp::Interp;
use crate::parser::{PError, Parser};
use crate::value::{Map, Value};
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::rc::Rc;

pub struct Source {
