}

pub struct Loader {
    pub lib_dirs: Vec<String>,
    pub jq_origin: String,
    pub cache: HashMap<PathBuf, Rc<ModuleDefs>>,
    pub meta_cache: HashMap<PathBuf, Value>,
    pub sources: Vec<Source>,
    pub natives: HashMap<(String, usize), usize>,
    pub globals: HashMap<String, usize>,
    pub builtins: Option<Rc<ModuleDefs>>,
    pub loading: Vec<PathBuf>,
}

pub enum CompileFailure {
    Errors(Vec<CError>),
    Message(String), // already formatted message (without "jq: error: ")
}

fn home() -> String {
    std::env::var("HOME").unwrap_or_default()
}

impl Loader {
    fn expand(&self, p: &str, lib_origin: Option<&str>) -> String {
        let mut p = p.to_string();
        if p == "~" {
            p = home();
        } else if let Some(r) = p.strip_prefix("~/") {
            p = format!("{}/{}", home(), r);
        }
        if p == "." {
            return p;
        }
        if let Some(r) = p.strip_prefix("$ORIGIN/") {
            return format!("{}/{}", self.jq_origin, r);
        }
        if let Some(lo) = lib_origin {
            if !p.starts_with('/') {
                return format!("{}/{}", lo, p);
            }
        }
        p
    }

    pub fn find_module(&self, rel: &str, search: &[String], suffix: &str, lib_origin: Option<&str>) -> Result<PathBuf, String> {
        // validate relpath
        let comps: Vec<&str> = rel.split('/').collect();
        for (i, c) in comps.iter().enumerate() {
            if *c == ".." || (*c == "." && i > 0) {
                return Err(format!("Modules must be named by relative paths that do not contain '.' or '..' components: {}", rel));
            }
        }
        let bname = comps.last().copied().unwrap_or("");
        for sp in search {
            let sp = self.expand(sp, lib_origin);
            if sp.is_empty() {
                continue;
            }
            let cands = [
                format!("{}/{}{}", sp, rel, suffix),
                format!("{}/{}/jq/main{}", sp, rel, suffix),
                format!("{}/{}/{}{}", sp, rel, bname, suffix),
            ];
            for c in cands.iter() {
                let pb = PathBuf::from(c);
                if pb.exists() {
                    return Ok(std::fs::canonicalize(&pb).unwrap_or(pb));
                }
            }
        }
        Err(format!("module not found: {}", rel))
    }

    fn search_for(&self, imp: &Import) -> Vec<String> {
        if let Some(Value::Obj(m)) = &imp.meta {
            if let Some(s) = m.get("search") {
                return match s {
                    Value::Arr(a) => a.iter().filter_map(|v| v.as_str().map(|x| x.to_string())).collect(),
                    Value::Str(x) => vec![x.to_string()],
                    _ => vec![],
                };
            }
        }
        let mut v = vec![".".to_string()];
        v.extend(self.lib_dirs.iter().cloned());
        v
    }

    pub fn add_source(&mut self, name: &str, text: &str) -> usize {
        self.sources.push(Source { name: name.to_string(), text: Rc::from(text) });
        self.sources.len() - 1
    }

    pub fn perrors_to_cerrors(errs: Vec<PError>, file: usize) -> Vec<CError> {
        errs.into_iter().map(|e| CError { msg: e.msg, start: e.start, end: e.end, file }).collect()
    }

    /// Process imports of a program into a compiler. Returns error message on failure.
    fn process_imports(
        &mut self,
        interp: &mut Interp,
        prog: &Program,
        comp: &mut Compiler,
        lib_origin: Option<&str>,
    ) -> Result<(), CompileFailure> {
        for imp in &prog.imports {
            let search = self.search_for(imp);
            if imp.is_data {
                let path = self.find_module(&imp.path, &search, ".json", lib_origin).map_err(CompileFailure::Message)?;
                let data = std::fs::read(&path).map_err(|e| CompileFailure::Message(format!("{}", e)))?;
                let vals = crate::json::parse_all(&data).map_err(CompileFailure::Message)?;
                let v = Value::from_vec(vals);
                let alias = imp.alias.clone().unwrap();
                let idx = interp.globals.len();
                interp.globals.push(v.clone());
                self.globals.insert(alias.clone(), idx);
                let idx2 = interp.globals.len();
                interp.globals.push(v);
                self.globals.insert(format!("{}::{}", alias, alias), idx2);
                comp.globals = unsafe { &*(&self.globals as *const _) };
                continue;
            }
            let path = self.find_module(&imp.path, &search, ".jq", lib_origin).map_err(CompileFailure::Message)?;
            let defs = self.load_module(interp, &path)?;
            match &imp.alias {
                Some(a) => {
                    comp.aliases.insert(a.clone(), defs);
                }
                None => {
                    for k in defs.order.iter() {
                        let f = defs.funcs.get(k).unwrap().clone();
                        comp.module.funcs.insert(k.clone(), f);
                        comp.module.order.retain(|x| x != k);
                        comp.module.order.push(k.clone());
                    }
                }
            }
        }
        Ok(())
    }

    pub fn load_module(&mut self, interp: &mut Interp, path: &Path) -> Result<Rc<ModuleDefs>, CompileFailure> {
        if let Some(d) = self.cache.get(path) {
            return Ok(d.clone());
        }
        if self.loading.iter().any(|p| p == path) {
            return Err(CompileFailure::Message(format!("module cycle detected: {}", path.display())));
        }
        let text = std::fs::read(path).map_err(|e| CompileFailure::Message(format!("{}: {}", path.display(), e)))?;
        let text = crate::json::bytes_to_string(&text);
        let fidx = self.add_source(&path.display().to_string(), &text);
        let mut p = Parser::new(&text);
        let prog = match p.parse_program(true) {
            Some(pr) => pr,
            None => return Err(CompileFailure::Errors(Self::perrors_to_cerrors(p.errors, fidx))),
        };
        if prog.body.is_some() {
            return Err(CompileFailure::Message(format!("jq: error: {} is not a module", path.display())));
        }
        self.loading.push(path.to_path_buf());
        let lib_origin = path.parent().map(|x| x.display().to_string());
        let natives = self.natives.clone();
        let globals = self.globals.clone();
        let mut comp = Compiler::new(&natives, &globals, fidx, path.display().to_string(), Rc::from(text.as_str()));
        comp.builtins = self.builtins.clone();
        let r = self.process_imports(interp, &prog, &mut comp, lib_origin.as_deref());
        if let Err(e) = r {
            self.loading.pop();
            return Err(e);
        }
        let mut own = Vec::new();
        for d in &prog.defs {
            comp.define_toplevel(d);
            own.push((d.name.clone(), d.params.len()));
        }
        // errors from all defs in a module are reported only if used; mark all exported as used roots
        let errs: Vec<CError> = Vec::new();
        let _ = errs;
        self.loading.pop();
        let defs = Rc::new(std::mem::take(&mut comp.module));
        // module metadata
        let mut meta = match &prog.module_meta {
            Some(Value::Obj(m)) => (**m).clone(),
            _ => Map::new(),
        };
        let mut deps = Vec::new();
        for imp in &prog.imports {
            let mut d = match &imp.meta {
                Some(Value::Obj(m)) => (**m).clone(),
                _ => Map::new(),
            };
            if let Some(a) = &imp.alias {
                d.insert(Rc::from("as"), Value::from_str(a));
            }
            d.insert(Rc::from("is_data"), Value::from_bool(imp.is_data));
            d.insert(Rc::from("relpath"), Value::from_str(&imp.path));
            deps.push(Value::from_map(d));
        }
        meta.insert(Rc::from("deps"), Value::from_vec(deps));
        let mut seen = Vec::new();
        let mut defl = Vec::new();
        for (n, a) in own {
            let s = format!("{}/{}", n, a);
            if !seen.contains(&s) {
                seen.push(s.clone());
                defl.push(Value::from_string(s));
            }
        }
        meta.insert(Rc::from("defs"), Value::from_vec(defl));
        self.meta_cache.insert(path.to_path_buf(), Value::from_map(meta));
        self.cache.insert(path.to_path_buf(), defs.clone());
        Ok(defs)
    }

    /// Compile the builtin prelude
    pub fn compile_prelude(&mut self, src: &str) {
        let fidx = self.add_source("<builtin>", src);
        let mut p = Parser::new(src);
        let prog = p.parse_program(true).expect("prelude parse error");
        let natives = self.natives.clone();
        let globals = self.globals.clone();
        let mut comp = Compiler::new(&natives, &globals, fidx, "<builtin>".into(), Rc::from(src));
        for d in &prog.defs {
            comp.define_toplevel(d);
        }
        self.builtins = Some(Rc::new(std::mem::take(&mut comp.module)));
    }

    /// Compile the main program. Returns the main node.
    pub fn compile_main(&mut self, interp: &mut Interp, text: &str, name: &str, lib_origin: Option<&str>) -> Result<Node, CompileFailure> {
        let fidx = self.add_source(name, text);
        let mut p = Parser::new(text);
        let prog = match p.parse_program(false) {
            Some(pr) => pr,
            None => return Err(CompileFailure::Errors(Self::perrors_to_cerrors(p.errors, fidx))),
        };
        let natives = self.natives.clone();
        let globals_snapshot = self.globals.clone();
        let mut comp = Compiler::new(&natives, &globals_snapshot, fidx, name.to_string(), Rc::from(text));
        comp.builtins = self.builtins.clone();
        self.process_imports(interp, &prog, &mut comp, lib_origin)?;
        let globals2 = self.globals.clone();
        comp.globals = unsafe { &*(&globals2 as *const _) };
        let body = match &prog.body {
            Some(b) => b,
            None => return Err(CompileFailure::Message("Top-level program not given (try \".\")".into())),
        };
        let node = comp.compile(body);
        let errs = comp.finish_errors();
        if !errs.is_empty() {
            return Err(CompileFailure::Errors(errs));
        }
        Ok(node)
    }
}

pub fn module_meta(interp: &mut Interp, name: &str) -> Result<Value, String> {
    crate::with_loader(|loader| {
        let mut search = vec![".".to_string()];
        search.extend(loader.lib_dirs.iter().cloned());
        let path = loader.find_module(name, &search, ".jq", None)?;
