// ---------------- input handling ----------------

struct Inputs {
    files: Vec<String>,
    next_file: usize,
    cur_data: Option<Vec<u8>>,
    cur_pos: usize,
    cur_name: Option<String>,
    cur_line: i64,
    parser: Option<JParser>,
    slurp: bool,
    slurped: Option<Value>,
    raw_slurped: Option<String>,
    raw_acc: Option<Vec<u8>>,
    pub failures: usize,
    finished: bool,
    stream_errors: bool,
}

impl Inputs {
    fn at_eof_of_all(&self) -> bool {
        self.next_file >= self.files.len() && self.cur_data.as_ref().map(|d| self.cur_pos >= d.len()).unwrap_or(true)
    }

    /// Read the next chunk like fgets. Returns (chunk, is_last)
    fn read_more(&mut self) -> (Vec<u8>, bool) {
        let need_new = match &self.cur_data {
            None => true,
            Some(d) => self.cur_pos >= d.len(),
        };
        if need_new {
            if self.cur_data.is_some() {
                self.cur_data = None;
                self.cur_name = None;
                self.cur_line = 0;
            }
            while self.next_file < self.files.len() {
                let f = self.files[self.next_file].clone();
                self.next_file += 1;
                if f == "-" {
                    let mut buf = Vec::new();
                    let _ = std::io::Read::read_to_end(&mut std::io::stdin(), &mut buf);
                    self.cur_data = Some(buf);
                    self.cur_name = Some("<stdin>".into());
                } else {
                    match std::fs::read(&f) {
                        Ok(d) => {
                            self.cur_data = Some(d);
                            self.cur_name = Some(f.clone());
                        }
                        Err(e) => {
                            let msg = if e.raw_os_error() == Some(21) {
                                "jq: error: Is a directory\n".to_string()
                            } else {
                                format!("jq: error: Could not open {}: {}\n", f, os_err_str(&e))
                            };
                            write_stderr(msg.as_bytes());
                            self.failures += 1;
                            self.cur_name = Some(f.clone());
                            continue;
                        }
                    }
                }
                self.cur_pos = 0;
                self.cur_line = 0;
                break;
            }
        }
        let mut chunk = Vec::new();
        if let Some(d) = &self.cur_data {
            let start = self.cur_pos;
            let maxlen = 4095;
            let mut end = start;
            let mut has_nl = false;
            while end < d.len() && end - start < maxlen {
                let c = d[end];
                end += 1;
                if c == b'\n' {
                    has_nl = true;
                    break;
                }
            }
            chunk.extend_from_slice(&d[start..end]);
            self.cur_pos = end;
            if has_nl {
                self.cur_line += 1;
            }
            if !has_nl && self.parser.is_some() {
                if let Some(p) = chunk.iter().position(|&c| c == 0) {
                    chunk.truncate(p);
                }
            }
        }
        let is_last = self.at_eof_of_all();
        (chunk, is_last)
    }

    fn next(&mut self) -> Option<Result<Value, String>> {
        if self.finished {
            return None;
        }
        if self.parser.is_none() {
            // raw input
            loop {
                let (chunk, is_last) = self.read_more();
                if !chunk.is_empty() {
                    if self.slurp {
                        let s = self.raw_slurped.get_or_insert_with(String::new);
                        s.push_str(&json::bytes_to_string(&chunk));
                    } else {
                        let acc = self.raw_acc.get_or_insert_with(Vec::new);
                        if *chunk.last().unwrap() == b'\n' {
                            acc.extend_from_slice(&chunk[..chunk.len() - 1]);
                            let line = self.raw_acc.take().unwrap();
                            return Some(Ok(Value::from_string(json::bytes_to_string(&line))));
                        }
                        acc.extend_from_slice(&chunk);
                    }
                }
                if is_last {
                    break;
                }
            }
            self.finished = true;
            if self.slurp {
                return Some(Ok(Value::from_string(self.raw_slurped.take().unwrap_or_default())));
            }
            if let Some(acc) = self.raw_acc.take() {
                return Some(Ok(Value::from_string(json::bytes_to_string(&acc))));
            }
            return None;
        }
        loop {
            let r = self.parser.as_mut().unwrap().next_value();
            match r {
                ParseResult::Value(v) => {
                    if self.slurp {
                        if let Some(Value::Arr(a)) = &mut self.slurped {
                            Rc::make_mut(a).push(v);
                        }
                        continue;
                    }
                    return Some(Ok(v));
                }
                ParseResult::Error(e) => {
                    if self.stream_errors {
                        let p = self.parser.as_ref().unwrap().current_path();
                        return Some(Ok(Value::from_vec(vec![Value::from_string(e), p])));
                    }
                    return Some(Err(e));
                }
                ParseResult::Eof => {
                    self.finished = true;
                    if self.slurp {
                        return self.slurped.take().map(Ok);
                    }
                    return None;
                }
                ParseResult::NeedMore => {
                    let (chunk, is_last) = self.read_more();
                    self.parser.as_mut().unwrap().set_buf(&chunk, !is_last);
                }
            }
        }
    }
}

fn os_err_str(e: &std::io::Error) -> String {
    let s = e.to_string();
    // strip " (os error N)"
    match s.find(" (os error") {
        Some(i) => s[..i].to_string(),
        None => s,
    }
}

struct SharedInputs(Rc<RefCell<Inputs>>);

impl InputSource for SharedInputs {
    fn next_input(&mut self) -> Option<Result<Value, String>> {
        self.0.borrow_mut().next()
    }
    fn current_filename(&self) -> Value {
        match &self.0.borrow().cur_name {
