actions.command:
cd /workspace && head -21 /tmp/help.txt > src/usage_short.txt && cp /tmp/help.txt src/usage_full.txt && cat > src/main.rs <<'EOF'
mod ast;
mod builtins;
mod compile;
mod ffi;
mod interp;
mod json;
mod lexer;
mod modules;
mod number;
mod ops;
mod parser;
mod regex;
mod time;
mod unicode_tables;
mod value;

use interp::{Exc, InputSource, Interp};
use json::{Colors, DumpOpts, ParseResult, Parser as JParser};
use modules::{CompileFailure, Loader};
use std::cell::RefCell;
use std::io::Write;
use std::os::unix::ffi::OsStrExt;
use std::rc::Rc;
use value::{Map, Value};

const PRELUDE: &str = include_str!("prelude.jq");
const USAGE_SHORT: &str = include_str!("usage_short.txt");
const USAGE_FULL: &str = include_str!("usage_full.txt");
const VERSION: &str = "jq-build-f77602d";
const BUILD_CONFIG: &str = "--disable-docs --with-oniguruma=builtin --enable-static --enable-all-static --prefix=/usr/local";

thread_local! {
    static LOADER: RefCell<Option<Loader>> = const { RefCell::new(None) };
}

pub fn with_loader<R>(f: impl FnOnce(&mut Loader) -> R) -> R {
    LOADER.with(|l| {
        let mut b = l.borrow_mut();
        f(b.as_mut().expect("loader"))
    })
}

pub fn write_stderr(b: &[u8]) {
    let e = std::io::stderr();
    let mut l = e.lock();
    let _ = l.write_all(b);
    let _ = l.flush();
}

fn main() {
    let args: Vec<String> = std::env::args_os().map(|a| json::bytes_to_string(a.as_bytes())).collect();
    let t = std::thread::Builder::new().stack_size(2 << 30).spawn(move || real_main(args)).unwrap();
    let code = t.join().unwrap_or(5);
    std::process::exit(code);
}

fn die_usage_hint(msg: &str) -> ! {
    let mut s = String::new();
    if !msg.is_empty() {
        s.push_str(msg);
        s.push('\n');
    }
    s.push_str("Use jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n");
    write_stderr(s.as_bytes());
    std::process::exit(2);
}

// ---------------- input handling ----------------

struct Inputs {
    files: Vec<String>,
    next_file: usize,
    cur_data: Option<Vec<u8>>,
    cur_pos: usize,
    cur_name: Option<String>,
    cur_line: i64,
    parser: Option<JParser>,
    slurp: bool,
    slurped: Option<Value>,
    raw_slurped: Option<String>,
    raw_acc: Option<Vec<u8>>,
    pub failures: usize,
    finished: bool,
    stream_errors: bool,
}

impl Inputs {
    fn at_eof_of_all(&self) -> bool {
        self.next_file >= self.files.len() && self.cur_data.as_ref().map(|d| self.cur_pos >= d.len()).unwrap_or(true)
    }

    /// Read the next chunk like fgets. Returns (chunk, is_last)
    fn read_more(&mut self) -> (Vec<u8>, bool) {
        let need_new = match &self.cur_data {
            None => true,
            Some(d) => self.cur_pos >= d.len(),
        };
        if need_new {
            if self.cur_data.is_some() {
                self.cur_data = None;
                self.cur_name = None;
                self.cur_line = 0;
            }
            while self.next_file < self.files.len() {
                let f = self.files[self.next_file].clone();
                self.next_file += 1;
                if f == "-" {
                    let mut buf = Vec::new();
                    let _ = std::io::Read::read_to_end(&mut std::io::stdin(), &mut buf);
                    self.cur_data = Some(buf);
                    self.cur_name = Some("<stdin>".into());
                } else {
                    match std::fs::read(&f) {
                        Ok(d) => {
                            self.cur_data = Some(d);
                            self.cur_name = Some(f.clone());
                        }
                        Err(e) => {
                            let msg = if e.raw_os_error() == Some(21) {
                                "jq: error: Is a directory\n".to_string()
                            } else {
                                format!("jq: error: Could not open {}: {}\n", f, os_err_str(&e))
                            };
                            write_stderr(msg.as_bytes());
                            self.failures += 1;
                            self.cur_name = Some(f.clone());
                            continue;
                        }
                    }
                }
                self.cur_pos = 0;
                self.cur_line = 0;
                break;
            }
        }
        let mut chunk = Vec::new();
        if let Some(d) = &self.cur_data {
            let start = self.cur_pos;
            let maxlen = 4095;
            let mut end = start;
            let mut has_nl = false;
            while end < d.len() && end - start < maxlen {
                let c = d[end];
                end += 1;
                if c == b'\n' {
                    has_nl = true;
                    break;
                }
            }
            chunk.extend_from_slice(&d[start..end]);
            self.cur_pos = end;
            if has_nl {
                self.cur_line += 1;
            }
            if !has_nl && self.parser.is_some() {
                if let Some(p) = chunk.iter().position(|&c| c == 0) {
                    chunk.truncate(p);
                }
            }
        }
        let is_last = self.at_eof_of_all();
        (chunk, is_last)
    }

    fn next(&mut self) -> Option<Result<Value, String>> {
        if self.finished {
            return None;
        }
        if self.parser.is_none() {
            // raw input
            loop {
                let (chunk, is_last) = self.read_more();
                if !chunk.is_empty() {
                    if self.slurp {
                        let s = self.raw_slurped.get_or_insert_with(String::new);
                        s.push_str(&json::bytes_to_string(&chunk));
                    } else {
                        let acc = self.raw_acc.get_or_insert_with(Vec::new);
                        if *chunk.last().unwrap() == b'\n' {
                            acc.extend_from_slice(&chunk[..chunk.len() - 1]);
                            let line = self.raw_acc.take().unwrap();
                            return Some(Ok(Value::from_string(json::bytes_to_string(&line))));
                        }
                        acc.extend_from_slice(&chunk);
                    }
                }
                if is_last {
                    break;
                }
            }
            self.finished = true;
            if self.slurp {
                return Some(Ok(Value::from_string(self.raw_slurped.take().unwrap_or_default())));
            }
            if let Some(acc) = self.raw_acc.take() {
                return Some(Ok(Value::from_string(json::bytes_to_string(&acc))));
            }
            return None;
        }
        loop {
            let r = self.parser.as_mut().unwrap().next_value();
            match r {
                ParseResult::Value(v) => {
                    if self.slurp {
                        if let Some(Value::Arr(a)) = &mut self.slurped {
                            Rc::make_mut(a).push(v);
                        }
                        continue;
                    }
                    return Some(Ok(v));
                }
                ParseResult::Error(e) => {
                    if self.stream_errors {
                        let p = self.parser.as_ref().unwrap().current_path();
                        return Some(Ok(Value::from_vec(vec![Value::from_string(e), p])));
                    }
                    return Some(Err(e));
                }
                ParseResult::Eof => {
                    self.finished = true;
                    if self.slurp {
                        return self.slurped.take().map(Ok);
                    }
                    return None;
                }
                ParseResult::NeedMore => {
                    let (chunk, is_last) = self.read_more();
                    self.parser.as_mut().unwrap().set_buf(&chunk, !is_last);
                }
            }
        }
    }
}

fn os_err_str(e: &std::io::Error) -> String {
    let s = e.to_string();
    // strip " (os error N)"
    match s.find(" (os error") {
        Some(i) => s[..i].to_string(),
        None => s,
    }
}

struct SharedInputs(Rc<RefCell<Inputs>>);

impl InputSource for SharedInputs {
    fn next_input(&mut self) -> Option<Result<Value, String>> {
        self.0.borrow_mut().next()
    }
    fn current_filename(&self) -> Value {
        match &self.0.borrow().cur_name {
            Some(n) => Value::from_str(n),
            None => Value::Null,
        }
    }
    fn current_line(&self) -> i64 {
        self.0.borrow().cur_line
    }
}

// ---------------- main ----------------

#[derive(Default)]
struct Opts {
    null_input: bool,
    raw_input: bool,
    slurp: bool,
    compact: bool,
    raw_output: bool,
    raw_output0: bool,
    join: bool,
    ascii: bool,
    sort_keys: bool,
    color: Option<bool>,
    tab: bool,
    indent: usize,
    unbuffered: bool,
    stream: bool,
    stream_errors: bool,
    seq: bool,
    from_file: bool,
    exit_status: bool,
}

fn format_cerror(loader: &Loader, e: &compile::CError) -> String {
    let src = &loader.sources[e.file];
    let text: &str = &src.text;
    let start = e.start.min(text.len());
    let before = &text[..start];
    let line_no = before.matches('\n').count() + 1;
    let line_start = before.rfind('\n').map(|i| i + 1).unwrap_or(0);
    let line_end = text[line_start..].find('\n').map(|i| line_start + i).unwrap_or(text.len());
    let col = start - line_start + 1;
    let line_text = &text[line_start..line_end];
    let endc = e.end.min(line_end).max(start);
    let n = (endc - start).max(1);
    let fname = if e.file == loader.sources.len() - 1 || src.name == "<top-level>" { "<top-level>".to_string() } else { src.name.clone() };
    format!(
        "jq: error: {} at {}, line {}, column {}:\n    {}\n    {}{}\n",
        e.msg,
        fname,
        line_no,
        col,
        line_text,
        " ".repeat(col - 1),
        "^".repeat(n)
    )
}

fn parse_colors(c: &str) -> Option<Colors> {
    let mut cols = Colors::default_colors();
    let mut rest = c;
    let mut i = 0;
    while i < 8 && !rest.is_empty() {
        let (field, next) = match rest.find(':') {
            Some(p) => (&rest[..p], &rest[p + 1..]),
            None => (rest, ""),
        };
        if field.len() > 12 {
            return None;
        }
        if !field.chars().all(|ch| ch.is_ascii_digit() || ch == ';') {
            return None;
        }
        let f = field.to_string();
        match i {
            0 => cols.null = f,
            1 => cols.fals = f,
            2 => cols.tru = f,
            3 => cols.num = f,
            4 => cols.str = f,
            5 => cols.arr = f,
            6 => cols.obj = f,
            7 => cols.key = f,
            _ => {}
        }
        rest = next;
        i += 1;
    }
    Some(cols)
}

fn realpath(p: &str) -> String {
    match std::fs::canonicalize(p) {
        Ok(pb) => pb.display().to_string(),
        Err(_) => p.to_string(),
    }
}

fn real_main(args: Vec<String>) -> i32 {
    let mut o = Opts { indent: 2, ..Default::default() };
    let mut program: Option<String> = None;
    let mut files: Vec<String> = Vec::new();
    let mut lib_dirs: Option<Vec<String>> = None;
    let mut named = Map::new();
    let mut named_order: Vec<(String, Value)> = Vec::new();
    let mut positional: Vec<Value> = Vec::new();
    let mut further_strings = false;
    let mut further_json = false;
    let mut args_done = false;
    let argc = args.len();
    let mut i = 1;
    let need = |i: usize, n: usize, msg: &str| {
        if i + n >= argc {
            die_usage_hint(msg);
        }
    };
    while i < argc {
        let text = args[i].clone();
        let is_opt = !args_done && text.starts_with('-') && text.len() > 1;
        if !is_opt {
            if program.is_none() {
                program = Some(text);
            } else if further_strings {
                positional.push(Value::from_string(text));
            } else if further_json {
                match json::parse_single(text.as_bytes()) {
                    Ok(v) => positional.push(v),
                    Err(_) => die_usage_hint("jq: invalid JSON text passed to --jsonargs"),
                }
            } else {
                files.push(text);
            }
            i += 1;
            continue;
        }
        if text == "--" {
            args_done = true;
            i += 1;
            continue;
        }
        if let Some(long) = text.strip_prefix("--") {
            match long {
                "null-input" => o.null_input = true,
                "raw-input" => o.raw_input = true,
                "slurp" => o.slurp = true,
                "compact-output" => o.compact = true,
                "raw-output" => o.raw_output = true,
                "raw-output0" => {
                    o.raw_output = true;
                    o.raw_output0 = true;
                    o.join = true;
                }
                "join-output" => {
                    o.raw_output = true;
                    o.join = true;
                }
                "ascii-output" => o.ascii = true,
                "sort-keys" => o.sort_keys = true,
                "color-output" => o.color = Some(true),
                "monochrome-output" => o.color = Some(false),
                "tab" => o.tab = true,
                "indent" => {
                    if i + 1 >= argc {
                        die_usage_hint("jq: --indent takes one parameter");
                    }
                    let v = &args[i + 1];
                    match v.parse::<i64>() {
                        Ok(n) if (-1..=7).contains(&n) => {
                            if n == -1 {
                                o.tab = true;
                            } else {
                                o.tab = false;
                                o.indent = n as usize;
                            }
                        }
                        _ => die_usage_hint("jq: --indent takes a number between -1 and 7"),
                    }
                    i += 2;
                    continue;
                }
                "unbuffered" => o.unbuffered = true,
                "stream" => o.stream = true,
                "stream-errors" => {
                    o.stream = true;
                    o.stream_errors = true;
                }
                "seq" => o.seq = true,
                "from-file" => o.from_file = true,
                "exit-status" => o.exit_status = true,
                "library-path" => {
                    if i + 1 >= argc {
                        die_usage_hint("-L takes a parameter: (e.g. -L /search/path or -L/search/path)");
                    }
                    lib_dirs.get_or_insert_with(Vec::new).push(realpath(&args[i + 1]));
                    i += 2;
                    continue;
                }
                "arg" => {
                    need(i, 2, "jq: --arg takes two parameters (e.g. --arg varname value)");
                    let name = args[i + 1].clone();
                    let v = Value::from_string(args[i + 2].clone());
                    if !named.contains_key(&name) {
                        named.insert(Rc::from(name.as_str()), v.clone());
                        named_order.push((name, v));
                    }
                    i += 3;
                    continue;
                }
                "argjson" => {
                    need(i, 2, "jq: --argjson takes two parameters (e.g. --argjson varname text)");
                    let name = args[i + 1].clone();
                    let v = match json::parse_single(args[i + 2].as_bytes()) {
                        Ok(v) => v,
                        Err(_) => die_usage_hint("jq: invalid JSON text passed to --argjson"),
                    };
                    if !named.contains_key(&name) {
                        named.insert(Rc::from(name.as_str()), v.clone());
                        named_order.push((name, v));
                    }
                    i += 3;
                    continue;
                }
                "slurpfile" | "rawfile" => {
                    let which = long;
                    need(
                        i,
                        2,
                        &format!("jq: --{} takes two parameters (e.g. --{} varname filename)", which, which),
                    );
                    let name = args[i + 1].clone();
                    let fname = args[i + 2].clone();
                    let data = match std::fs::read(&fname) {
                        Ok(d) => d,
                        Err(e) => {
                            write_stderr(
                                format!("jq: Bad JSON in --{} {} {}: Could not open {}: {}\n", which, name, fname, fname, os_err_str(&e))
                                    .as_bytes(),
                            );
                            return 2;
                        }
                    };
                    let v = if which == "rawfile" {
                        Value::from_string(json::bytes_to_string(&data))
                    } else {
                        match json::parse_all(&data) {
                            Ok(vs) => Value::from_vec(vs),
                            Err(e) => {
                                write_stderr(format!("jq: Bad JSON in --{} {} {}: {}\n", which, name, fname, e).as_bytes());
                                return 2;
                            }
                        }
                    };
                    if !named.contains_key(&name) {
                        named.insert(Rc::from(name.as_str()), v.clone());
                        named_order.push((name, v));
                    }
                    i += 3;
                    continue;
                }
                "args" => {
                    further_strings = true;
                    further_json = false;
                }
                "jsonargs" => {
                    further_json = true;
                    further_strings = false;
                }
                "version" => {
                    println!("{}", VERSION);
                    return 0;
                }
                "build-configuration" => {
                    println!("{}", BUILD_CONFIG);
                    return 0;
                }
                "help" => {
                    print!("{}", USAGE_FULL);
                    return 0;
                }
                "debug-dump-disasm" | "debug-trace" | "debug-trace=all" => {}
                _ => die_usage_hint(&format!("jq: Unknown option {}", text)),
            }
            i += 1;
            continue;
        }
        // short options
        let chars: Vec<char> = text[1..].chars().collect();
        let mut consumed_next = false;
        let mut k = 0;
        while k < chars.len() {
            let c = chars[k];
            match c {
                'n' => o.null_input = true,
                'R' => o.raw_input = true,
                's' => o.slurp = true,
                'c' => o.compact = true,
                'r' => o.raw_output = true,
                'j' => {
                    o.raw_output = true;
                    o.join = true;
                }
                'a' => o.ascii = true,
                'S' => o.sort_keys = true,
                'C' => o.color = Some(true),
                'M' => o.color = Some(false),
                'e' => o.exit_status = true,
                'f' => o.from_file = true,
                'b' => {}
                'h' => {
                    print!("{}", USAGE_FULL);
                    return 0;
                }
                'V' => {
                    println!("{}", VERSION);
                    return 0;
                }
                'L' => {
                    let rest: String = chars[k + 1..].iter().collect();
                    if !rest.is_empty() {
                        lib_dirs.get_or_insert_with(Vec::new).push(realpath(&rest));
                    } else {
                        if i + 1 >= argc {
                            die_usage_hint("-L takes a parameter: (e.g. -L /search/path or -L/search/path)");
                        }
                        lib_dirs.get_or_insert_with(Vec::new).push(realpath(&args[i + 1]));
                        consumed_next = true;
                    }
                    k = chars.len();
                    continue;
                }
                other => die_usage_hint(&format!("jq: Unknown option -{}", other)),
            }
            k += 1;
        }
        i += if consumed_next { 2 } else { 1 };
    }

    // colors
    let mut colors_storage: Option<Colors> = None;
    let use_color = o.color.unwrap_or(false);
    if use_color {
        let mut cols = Colors::default_colors();
        if let Ok(jc) = std::env::var("JQ_COLORS") {
            match parse_colors(&jc) {
                Some(c) => cols = c,
                None => write_stderr(b"Failed to set $JQ_COLORS\n"),
            }
        }
        colors_storage = Some(cols);
    } else if let Ok(jc) = std::env::var("JQ_COLORS") {
        if parse_colors(&jc).is_none() {
            write_stderr(b"Failed to set $JQ_COLORS\n");
        }
    }

    // program
    let stdin_tty = unsafe { isatty(0) } != 0;
    let stdout_tty = unsafe { isatty(1) } != 0;
    let mut prog_name = "<top-level>".to_string();
    let mut lib_origin: Option<String> = None;
    let program_text: String = if o.from_file {
        let f = match &program {
            Some(f) => f.clone(),
            None => {
                write_stderr(USAGE_FULL.as_bytes());
                return 2;
            }
        };
        match std::fs::read(&f) {
            Ok(d) => {
                lib_origin = std::path::Path::new(&realpath(&f)).parent().map(|p| p.display().to_string());
                prog_name = f.clone();
                json::bytes_to_string(&d)
            }
            Err(e) => {
                write_stderr(format!("jq: Could not open {}: {}\n", f, os_err_str(&e)).as_bytes());
                return 2;
            }
        }
    } else {
        match &program {
            Some(p) => p.clone(),
            None => {
                if !stdout_tty || !stdin_tty {
                    ".".to_string()
                } else {
                    let mut s = USAGE_SHORT.to_string();
                    s.push_str("For listing the command options, use jq --help.\n");
                    write_stderr(s.as_bytes());
                    return 2;
                }
            }
        }
    };
    let _ = prog_name;
    if o.from_file && files.is_empty() && program.is_some() {
        // with -f, the program arg was a file; remaining files are inputs (already in files)
    }

    // interpreter setup
    let mut it = Interp::new();
    it.natives = builtins::native_defs();
    let natives_tbl = builtins::native_table(&it.natives);
    let mut globals: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
    // $ENV
    let mut envm = Map::new();
    for (k, v) in std::env::vars_os() {
        envm.insert(Rc::from(json::bytes_to_string(k.as_bytes()).as_str()), Value::from_string(json::bytes_to_string(v.as_bytes())));
    }
    let envv = Value::from_map(envm);
    it.env_value = envv.clone();
    globals.insert("ENV".into(), it.globals.len());
    it.globals.push(envv);
    // $ARGS
    let mut argsm = Map::new();
    argsm.insert(Rc::from("positional"), Value::from_vec(positional));
    argsm.insert(Rc::from("named"), Value::from_map(named.clone()));
    globals.insert("ARGS".into(), it.globals.len());
    it.globals.push(Value::from_map(argsm));
    for (n, v) in named_order {
        globals.insert(n, it.globals.len());
        it.globals.push(v);
    }

    let exe_dir = std::env::current_exe()
        .ok()
        .and_then(|p| p.parent().map(|d| d.display().to_string()))
        .unwrap_or_else(|| ".".into());
    let lib_dirs_v = lib_dirs.clone().unwrap_or_else(|| vec!["~/.jq".into(), "$ORIGIN/../lib/jq".into(), "$ORIGIN/../lib".into()]);
    it.search_list = Value::from_vec(lib_dirs_v.iter().map(|s| Value::from_str(s)).collect());
    it.jq_origin = Value::from_str(&exe_dir);
    let cwd = std::env::current_dir().map(|p| p.display().to_string()).unwrap_or_default();
    it.prog_origin = Value::from_str(lib_origin.as_deref().unwrap_or(&cwd));

    let loader = Loader {
        lib_dirs: lib_dirs_v,
        jq_origin: exe_dir,
        cache: Default::default(),
        meta_cache: Default::default(),
        sources: Vec::new(),
        natives: natives_tbl,
        globals,
        builtins: None,
        loading: Vec::new(),
    };
    LOADER.with(|l| *l.borrow_mut() = Some(loader));
    with_loader(|l| l.compile_prelude(PRELUDE));
    // builtin names
    let names = with_loader(|l| {
        let mut v: Vec<String> = Vec::new();
        if let Some(b) = &l.builtins {
            for (n, a) in b.order.iter() {
                if !n.starts_with('_') {
                    v.push(format!("{}/{}", n, a));
                }
            }
        }
        for d in it.natives.iter() {
            if !d.name.starts_with('_') {
                let s = format!("{}/{}", d.name, d.arity);
                if !v.contains(&s) {
                    v.push(s);
                }
            }
        }
        v
    });
    it.builtin_names = names;

    let lo = lib_origin.clone().unwrap_or(cwd.clone());
    let compiled = LOADER.with(|l| {
        let mut b = l.borrow_mut();
        let ld = b.as_mut().unwrap();
        let r = ld.compile_main(&mut it, &program_text, "<top-level>", Some(&lo));
        match r {
            Ok(n) => Ok(n),
            Err(CompileFailure::Errors(errs)) => {
                let mut s = String::new();
                for e in &errs {
                    s.push_str(&format_cerror(ld, e));
                }
                Err((s, errs.len()))
            }
            Err(CompileFailure::Message(m)) => {
                let s = if m.starts_with("module not found") || m.starts_with("Modules must") {
                    format!("jq: error: {}\n\n", m)
                } else if m.starts_with("jq: error") {
                    format!("{}\n", m)
                } else {
                    format!("jq: error: {}\n", m)
                };
                Err((s, 1))
            }
        }
    });
    let main_node = match compiled {
        Ok(n) => n,
        Err((s, n)) => {
            let mut s = s;
            s.push_str(&format!("jq: {} compile {}\n", n, if n == 1 { "error" } else { "errors" }));
            write_stderr(s.as_bytes());
            return 3;
        }
    };

    // inputs
    if files.is_empty() {
        files.push("-".into());
    }
    let inputs = Rc::new(RefCell::new(Inputs {
        files,
        next_file: 0,
        cur_data: None,
        cur_pos: 0,
        cur_name: None,
        cur_line: 0,
        parser: if o.raw_input { None } else { Some(JParser::new(o.stream, o.seq)) },
        slurp: o.slurp,
        slurped: if o.slurp && !o.raw_input { Some(Value::from_vec(vec![])) } else { None },
        raw_slurped: None,
        raw_acc: None,
