    };

    if o.null_input {
        let r = process(&mut it, Value::Null, &mut out);
        if r >= 1000 {
            halted = true;
            ret = r - 1000;
        } else {
            ret = r;
        }
    } else {
        loop {
            let next = inputs.borrow_mut().next();
            match next {
                None => break,
                Some(Ok(v)) => {
                    let r = process(&mut it, v, &mut out);
                    if r >= 1000 {
