    }
}

fn input_position(it: &Interp) -> String {
    match &it.input {
        Some(src) => match src.current_filename() {
            Value::Str(s) => format!("{}:{}", s, src.current_line()),
            _ => "<unknown>".to_string(),
        },
        None => "<unknown>".to_string(),
    }
}

