            Node::Identity | Node::Const(_) | Node::Var(_) | Node::GlobalVar(_) | Node::Format(_) | Node::Break(_) => true,
            Node::Array(_) => true,
            Node::Index(t, k) => self.is_single(t) && self.is_single(k),
            Node::Slice(t, a, b) => {
                self.is_single(t) && a.as_ref().map(|x| self.is_single(x)).unwrap_or(true) && b.as_ref().map(|x| self.is_single(x)).unwrap_or(true)
            }
            Node::Str(_, parts) => parts.iter().all(|p| match p {
                CPart::Lit(_) => true,
                CPart::Interp(e) => self.is_single(e),
            }),
            Node::Object(pairs) => pairs.iter().all(|(k, v)| self.is_single(k) && self.is_single(v)),
            Node::Neg(x) => self.is_single(x),
            Node::Pipe(a, b) | Node::Bin(_, a, b) | Node::BinS(_, a, b) | Node::And(a, b) | Node::Or(a, b) | Node::Alt(a, b) => {
                self.is_single(a) && self.is_single(b)
            }
            Node::If(bs, e) | Node::IfS(bs, e) => {
                bs.iter().all(|(c, b)| self.is_single(c) && self.is_single(b)) && e.as_ref().map(|x| self.is_single(x)).unwrap_or(true)
            }
            Node::Try(b, c) => self.is_single(b) && c.as_ref().map(|x| self.is_single(x)).unwrap_or(true),
            Node::Reduce(_, _, init, _) => self.is_single(init),
            Node::Assign(_, _, rhs) => self.is_single(rhs),
            Node::Bind(src, _, body) => self.is_single(src) && self.is_single(body),
            Node::Label(b) => self.is_single(b),
            Node::CallNative(id, args) => {
                let name = self.natives.iter().find(|(_, v)| **v == *id).map(|(k, _)| k.0.as_str()).unwrap_or("range");
                !(name == "range" || name == "path") && args.iter().all(|a| self.is_single(a))
            }
            _ => false,
        }
    }

