p='/workspace/src/builtins.rs'
s=open(p).read()
s=s.replace('''fn f_trim(''','''enum Acc {
    S(String),
    V(Value),
}

impl Acc {
    fn add(self, x: Value) -> Result<Acc, Exc> {
        match (self, x) {
            (Acc::S(mut b), Value::Str(s)) => {
                b.push_str(&s);
                Ok(Acc::S(b))
            }
            (Acc::S(b), Value::Null) => Ok(Acc::S(b)),
            (Acc::S(b), other) => {
                let r = ops::add(Value::from_string(b), other).map_err(Exc::Err)?;
                Ok(Acc::V(r))
            }
            (Acc::V(v), x) => {
                let r = ops::add(v, x).map_err(Exc::Err)?;
                match r {
                    Value::Str(s) => Ok(Acc::S(s.to_string())),
                    other => Ok(Acc::V(other)),
                }
            }
        }
    }
    fn into_value(self) -> Value {
        match self {
            Acc::S(b) => Value::from_string(b),
            Acc::V(v) => v,
        }
    }
}

fn iter_values(v: &Value) -> Result<Vec<Value>, Exc> {
    match v {
        Value::Arr(a) => Ok(a.to_vec()),
        Value::Obj(o) => Ok(o.values().cloned().collect()),
        other => Err(err_msg(format!("Cannot iterate over {} ({})", other.type_name(), dump_trunc(other, 15)))),
    }
}

fn f_add(it: &mut Interp, _a: &[Rc<Node>], _e: &Env, input: Value, out: Out) -> Res {
    let items = iter_values(&input)?;
    drop(input);
    let mut acc = Acc::V(Value::Null);
    for x in items {
        acc = acc.add(x)?;
    }
    out(it, acc.into_value())
}

fn f_join(it: &mut Interp, args: &[Rc<Node>], env: &Env, input: Value, out: Out) -> Res {
    with_args(it, args, env, &input, &mut |it2, v| {
        let sep = &v[0];
        let items = iter_values(&input)?;
        let mut acc: Option<Acc> = None;
        for i in items {
            let a = match acc.take() {
                None => Acc::S(String::new()),
                Some(a) => a.add(sep.clone())?,
            };
            let iv = match &i {
                Value::True | Value::False | Value::Num(_) | Value::Lit(_) => Value::from_string(to_json(&i)),
                Value::Null => Value::from_str(""),
                _ => i,
            };
            acc = Some(a.add(iv)?);
        }
        let r = match acc {
            None => Value::Null,
            Some(a) => a.into_value(),
        };
        let r = if r.is_truthy() { r } else { Value::from_str("") };
        out(it2, r)
    })
}

fn f_trim(''')
s=s.replace('''    add("trim", 0, f_trim);''','''    add("trim", 0, f_trim);
    add("add", 0, f_add);
    add("join", 1, f_join);''')
open(p,'w').write(s)
p='/workspace/src/prelude.jq'
s=open(p).read()
s=s.replace('''def add: reduce .[] as $x (null; . + $x);
''','')
i=s.index('def join($x):')
j=s.index('def transpose')
s=s[:i]+s[j:]
open(p,'w').write(s)
EOF
