            break;
        }
    }
    let lower_even = (lower[n - 1] - b'0') % 2 == 0;
    let (cand, cexp) = if lower_even { (lower, exp10) } else { (upper, uexp) };
    let mut cs = String::from_utf8(cand).unwrap();
    while cs.len() > 1 && cs.ends_with('0') {
        cs.pop();
