new='''#[derive(Clone, Default)]
pub struct Map {
    entries: Vec<Option<(Rc<str>, Value)>>,
    live: usize,
    index: Option<HashMap<Rc<str>, usize>>,
}

const INDEX_THRESHOLD: usize = 12;

impl Map {
    pub fn new() -> Map {
        Map { entries: Vec::new(), live: 0, index: None }
    }
    pub fn with_capacity(n: usize) -> Map {
        Map { entries: Vec::with_capacity(n), live: 0, index: None }
    }
    pub fn len(&self) -> usize {
        self.live
    }
    pub fn is_empty(&self) -> bool {
        self.live == 0
    }
    fn find(&self, k: &str) -> Option<usize> {
        if let Some(idx) = &self.index {
            idx.get(k).copied()
        } else {
            self.entries.iter().position(|e| matches!(e, Some((kk, _)) if &**kk == k))
        }
    }
    pub fn get(&self, k: &str) -> Option<&Value> {
        self.find(k).and_then(|i| self.entries[i].as_ref().map(|(_, v)| v))
    }
    pub fn get_mut(&mut self, k: &str) -> Option<&mut Value> {
        match self.find(k) {
            Some(i) => self.entries[i].as_mut().map(|(_, v)| v),
            None => None,
        }
    }
    pub fn contains_key(&self, k: &str) -> bool {
        self.find(k).is_some()
    }
    pub fn insert(&mut self, k: Rc<str>, v: Value) {
        if let Some(i) = self.find(&k) {
            if let Some(e) = self.entries[i].as_mut() {
                e.1 = v;
            }
            return;
        }
        let pos = self.entries.len();
        if let Some(idx) = &mut self.index {
            idx.insert(k.clone(), pos);
        }
        self.entries.push(Some((k, v)));
        self.live += 1;
        if self.index.is_none() && self.live > INDEX_THRESHOLD {
            self.rebuild_index();
        }
    }
    fn rebuild_index(&mut self) {
        let mut idx = HashMap::with_capacity(self.live * 2);
        for (i, e) in self.entries.iter().enumerate() {
            if let Some((k, _)) = e {
                idx.insert(k.clone(), i);
            }
        }
        self.index = Some(idx);
    }
    fn compact(&mut self) {
        self.entries.retain(|e| e.is_some());
        if self.live > INDEX_THRESHOLD {
            self.rebuild_index();
        } else {
            self.index = None;
        }
    }
    pub fn remove(&mut self, k: &str) -> Option<Value> {
        let i = self.find(k)?;
        let (_, v) = self.entries[i].take()?;
        if let Some(idx) = &mut self.index {
            idx.remove(k);
        }
        self.live -= 1;
        let dead = self.entries.len() - self.live;
        if self.index.is_none() || (dead > 16 && dead > self.live) {
            self.compact();
        }
        Some(v)
    }
    pub fn iter(&self) -> impl Iterator<Item = (&Rc<str>, &Value)> {
        self.entries.iter().filter_map(|e| e.as_ref().map(|(k, v)| (k, v)))
    }
    pub fn keys(&self) -> impl Iterator<Item = &Rc<str>> {
        self.entries.iter().filter_map(|e| e.as_ref().map(|(k, _)| k))
    }
    pub fn values(&self) -> impl Iterator<Item = &Value> {
        self.entries.iter().filter_map(|e| e.as_ref().map(|(_, v)| v))
    }
    pub fn sorted_keys(&self) -> Vec<Rc<str>> {
        let mut ks: Vec<Rc<str>> = self.keys().cloned().collect();
        ks.sort_by(|a, b| a.as_bytes().cmp(b.as_bytes()));
        ks
    }
}

